#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <ftw.h>
#include <sys/stat.h>
#include <errno.h>
#include <libgen.h>
#include <limits.h>

#define MAX_EXTENSIONS 6
#define MAX_PATH_LEN 4096

// Global variables for nftw callback
char *source_dir = NULL;
char *dest_dir = NULL;
char *extensions[MAX_EXTENSIONS];
int ext_count = 0;
int is_move = 0;
int is_copy = 0;
int should_delete = 0;

// Function to check if a path is within home directory
int is_within_home(const char *path) {
    char *home = getenv("HOME");
    if (!home) return 0;

    char real_path[PATH_MAX];
    char real_home[PATH_MAX];

    if (realpath(path, real_path) == NULL) return 0;
    if (realpath(home, real_home) == NULL) return 0;

    return strncmp(real_path, real_home, strlen(real_home)) == 0;
}

// Function to check if file should be skipped based on extension
int should_skip_file(const char *filename) {
    if (ext_count == 0) return 0;

    const char *dot = strrchr(filename, '.');
    if (!dot || dot == filename) return 0;

    char ext[256];
    strcpy(ext, dot + 1);

    // Convert to lowercase for case-insensitive comparison
    for (int i = 0; ext[i]; i++) {
        ext[i] = tolower(ext[i]);
    }

    for (int i = 0; i < ext_count; i++) {
        char ext_lower[256];
        strcpy(ext_lower, extensions[i]);
        for (int j = 0; ext_lower[j]; j++) {
            ext_lower[j] = tolower(ext_lower[j]);
        }

        if (strcmp(ext, ext_lower) == 0) {
            return 1;
        }
    }

    return 0;
}

// Function to create destination path
void create_dest_path(const char *src_path, char *dest_path) {
    // Get relative path from source directory
    const char *rel_path = src_path + strlen(source_dir);

    // Handle case where src_path is exactly source_dir
    if (strlen(rel_path) == 0) {
        strcpy(dest_path, dest_dir);
    } else {
        snprintf(dest_path, PATH_MAX, "%s%s", dest_dir, rel_path);
    }
}

// nftw callback function
int process_entry(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    // Skip the source directory itself in the first call
    if (strcmp(fpath, source_dir) == 0 && ftwbuf->level == 0) {
        return 0;
    }

    char dest_path[PATH_MAX];
    create_dest_path(fpath, dest_path);

    switch (typeflag) {
        case FTW_D:  // Directory
            // Create directory in destination
            if (mkdir(dest_path, sb->st_mode) == -1 && errno != EEXIST) {
                fprintf(stderr, "Error creating directory %s: %s\n", dest_path, strerror(errno));
                return -1;
            }
            break;

        case FTW_F:  // Regular file
            // Check if file should be skipped
            if (should_skip_file(fpath)) {
                printf("Skipping: %s\n", fpath);
                return 0;
            }

            // Copy file
            FILE *src_file = fopen(fpath, "rb");
            if (!src_file) {
                fprintf(stderr, "Error opening source file %s: %s\n", fpath, strerror(errno));
                return -1;
            }

            FILE *dest_file = fopen(dest_path, "wb");
            if (!dest_file) {
                fprintf(stderr, "Error opening destination file %s: %s\n", dest_path, strerror(errno));
                fclose(src_file);
                return -1;
            }

            char buffer[8192];
            size_t bytes;
            while ((bytes = fread(buffer, 1, sizeof(buffer), src_file)) > 0) {
                if (fwrite(buffer, 1, bytes, dest_file) != bytes) {
                    fprintf(stderr, "Error writing to %s\n", dest_path);
                    fclose(src_file);
                    fclose(dest_file);
                    return -1;
                }
            }

            fclose(src_file);
            fclose(dest_file);

            // Preserve file permissions
            chmod(dest_path, sb->st_mode);

            printf("Copied: %s -> %s\n", fpath, dest_path);
            break;

        case FTW_SL:  // Symbolic link (skip for simplicity)
            printf("Skipping symbolic link: %s\n", fpath);
            break;

        case FTW_DNR:  // Directory that cannot be read
            fprintf(stderr, "Cannot read directory: %s\n", fpath);
            return -1;

        case FTW_NS:  // Stat failed
            fprintf(stderr, "Cannot stat: %s\n", fpath);
            return -1;
    }

    return 0;
}

// Function to delete source directory tree
int delete_source_tree(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    // Skip the source directory itself until the end
    if (strcmp(fpath, source_dir) == 0 && ftwbuf->level == 0) {
        return 0;
    }

    switch (typeflag) {
        case FTW_F:
        case FTW_SL:
            if (remove(fpath) == -1) {
                fprintf(stderr, "Error removing file %s: %s\n", fpath, strerror(errno));
            } else {
                printf("Removed: %s\n", fpath);
            }
            break;

        case FTW_DP:  // Directory on post-order visit
            if (rmdir(fpath) == -1) {
                fprintf(stderr, "Error removing directory %s: %s\n", fpath, strerror(errno));
            } else {
                printf("Removed directory: %s\n", fpath);
            }
            break;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    // Validate minimum arguments
    if (argc < 4) {
        fprintf(stderr, "Usage: %s source_dir destination_dir [-cp | -mv] [extensions...]\n", argv[0]);
        fprintf(stderr, "Maximum %d extensions allowed\n", MAX_EXTENSIONS);
        return 1;
    }

    // Parse source and destination
    source_dir = realpath(argv[1], NULL);
    dest_dir = argv[2];

    if (!source_dir) {
        fprintf(stderr, "Error: Source directory '%s' does not exist or cannot be accessed\n", argv[1]);
        return 1;
    }

    // Check if paths are within home directory
    if (!is_within_home(source_dir)) {
        fprintf(stderr, "Error: Source directory must be within home directory hierarchy\n");
        free(source_dir);
        return 1;
    }

    if (!is_within_home(dest_dir)) {
        fprintf(stderr, "Error: Destination directory must be within home directory hierarchy\n");
        free(source_dir);
        return 1;
    }

    // Parse option
    if (strcmp(argv[3], "-cp") == 0) {
        is_copy = 1;
    } else if (strcmp(argv[3], "-mv") == 0) {
        is_move = 1;
    } else {
        fprintf(stderr, "Error: Option must be either -cp or -mv\n");
        free(source_dir);
        return 1;
    }

    // Parse extensions (if any)
    ext_count = 0;
    for (int i = 4; i < argc && ext_count < MAX_EXTENSIONS; i++) {
        // Remove leading dot if present
        if (argv[i][0] == '.') {
            extensions[ext_count] = &argv[i][1];
        } else {
            extensions[ext_count] = argv[i];
        }
        ext_count++;
    }

    if (ext_count > MAX_EXTENSIONS) {
        fprintf(stderr, "Error: Maximum %d extensions allowed\n", MAX_EXTENSIONS);
        free(source_dir);
        return 1;
    }

    // Create destination directory if it doesn't exist
    struct stat st;
    if (stat(dest_dir, &st) == -1) {
        if (mkdir(dest_dir, 0755) == -1) {
            fprintf(stderr, "Error creating destination directory %s: %s\n", dest_dir, strerror(errno));
            free(source_dir);
            return 1;
        }
        printf("Created destination directory: %s\n", dest_dir);
    }

    // Resolve destination directory path
    char *real_dest = realpath(dest_dir, NULL);
    if (!real_dest) {
        // If realpath fails, use the path as-is
        real_dest = strdup(dest_dir);
    }
    dest_dir = real_dest;

    printf("Source: %s\n", source_dir);
    printf("Destination: %s\n", dest_dir);
    if (is_copy) printf("Operation: Copy\n");
    if (is_move) printf("Operation: Move\n");
    if (ext_count > 0) {
        printf("Skipping extensions: ");
        for (int i = 0; i < ext_count; i++) {
            printf("%s ", extensions[i]);
        }
        printf("\n");
    }

    // Traverse and copy/move directory tree using nftw
    int flags = FTW_PHYS | FTW_ACTIONRETVAL;
    if (nftw(source_dir, process_entry, 20, flags) == -1) {
        fprintf(stderr, "Error traversing directory tree: %s\n", strerror(errno));
        free(source_dir);
        free(dest_dir);
        return 1;
    }

    // If move operation, delete source tree
    if (is_move) {
        printf("\nDeleting source directory tree...\n");
        flags = FTW_PHYS | FTW_DEPTH | FTW_ACTIONRETVAL;
        if (nftw(source_dir, delete_source_tree, 20, flags) == -1) {
            fprintf(stderr, "Error deleting source tree: %s\n", strerror(errno));
        }

        // Finally, remove the source directory itself
        if (rmdir(source_dir) == -1) {
            fprintf(stderr, "Error removing source directory %s: %s\n", source_dir, strerror(errno));
        } else {
            printf("Removed source directory: %s\n", source_dir);
        }
    }

    printf("\nOperation completed successfully\n");

    // Cleanup
    free(source_dir);
    free(dest_dir);

    return 0;
}
