```dart
import 'dart:io';
import 'dart:typed_data';
import 'package:image/image.dart' as img;

/// Slices an image into four equal parts from the center and returns them as bytes
/// 
/// Parameters:
/// - `imageInput`: Can be a String (file path), Uint8List (image bytes), or img.Image object
/// - `outputFormat`: Output image format (default: img.Format.png)
/// 
/// Returns:
/// - List<Uint8List> containing four image byte arrays in order:
///   [top-left, top-right, bottom-left, bottom-right]
/// 
/// Throws:
/// - ArgumentError: If image is too small to slice
/// - FileSystemException: If file cannot be read
Future<List<Uint8List>> sliceImageIntoFourBytes(
  dynamic imageInput, {
  img.Format outputFormat = img.Format.png,
}) async {
  // Load the image based on input type
  img.Image image;

  if (imageInput is String) {
    // Input is a file path
    final file = File(imageInput);
    final bytes = await file.readAsBytes();
    image = img.decodeImage(bytes)!;
  } else if (imageInput is Uint8List) {
    // Input is raw bytes
    image = img.decodeImage(imageInput)!;
  } else if (imageInput is img.Image) {
    // Input is already an Image object
    image = imageInput;
  } else {
    throw ArgumentError('imageInput must be String (file path), Uint8List, or img.Image');
  }

  // Get image dimensions
  final width = image.width;
  final height = image.height;

  // Check if image is large enough to slice
  if (height < 2 || width < 2) {
    throw ArgumentError('Image too small to slice. Minimum size: 2x2, got: ${width}x${height}');
  }

  // Calculate center point
  final centerX = width ~/ 2;
  final centerY = height ~/ 2;

  // Define the four quadrants
  final quadrants = [
    // Top-left: (0, 0) to (centerX, centerY)
    Rectangle<int>(0, 0, centerX, centerY),
    // Top-right: (centerX, 0) to (width, centerY)
    Rectangle<int>(centerX, 0, width - centerX, centerY),
    // Bottom-left: (0, centerY) to (centerX, height)
    Rectangle<int>(0, centerY, centerX, height - centerY),
    // Bottom-right: (centerX, centerY) to (width, height)
    Rectangle<int>(centerX, centerY, width - centerX, height - centerY),
  ];

  // Extract each quadrant and convert to bytes
  final List<Uint8List> slicedBytes = [];

  for (final quadrant in quadrants) {
    // Skip if quadrant has zero dimensions
    if (quadrant.width <= 0 || quadrant.height <= 0) {
      // Create a 1x1 pixel image for empty quadrants
      final emptyImage = img.Image(width: 1, height: 1);
      final bytes = img.encodePng(emptyImage);
      slicedBytes.add(bytes);
      continue;
    }

    // Extract the quadrant from the image
    final quadrantImage = img.copyCrop(
      image,
      x: quadrant.left,
      y: quadrant.top,
      width: quadrant.width,
      height: quadrant.height,
    );

    // Convert to bytes based on requested format
    Uint8List bytes;
    switch (outputFormat) {
      case img.Format.png:
        bytes = img.encodePng(quadrantImage);
        break;
      case img.Format.jpeg:
        bytes = img.encodeJpg(quadrantImage);
        break;
      case img.Format.bmp:
        bytes = img.encodeBmp(quadrantImage);
        break;
      case img.Format.tga:
        bytes = img.encodeTga(quadrantImage);
        break;
      default:
        bytes = img.encodePng(quadrantImage);
    }

    slicedBytes.add(bytes);
  }

  return slicedBytes;
}

/// Enhanced version that returns both bytes and metadata
/// 
/// Returns:
/// - List<Uint8List>: Four image byte arrays
/// - List<Rectangle<int>>: Dimensions and positions of each quadrant
Future<Map<String, dynamic>> sliceImageWithMetadata(
  dynamic imageInput, {
  img.Format outputFormat = img.Format.png,
}) async {
  final slicedBytes = await sliceImageIntoFourBytes(imageInput, outputFormat: outputFormat);

  // Load image to get dimensions
  img.Image image;
  if (imageInput is String) {
    final file = File(imageInput);
    final bytes = await file.readAsBytes();
    image = img.decodeImage(bytes)!;
  } else if (imageInput is Uint8List) {
    image = img.decodeImage(imageInput)!;
  } else if (imageInput is img.Image) {
    image = imageInput;
  }

  final width = image.width;
  final height = image.height;
  final centerX = width ~/ 2;
  final centerY = height ~/ 2;

  // Define quadrants with metadata
  final quadrants = [
    Rectangle<int>(0, 0, centerX, centerY),
    Rectangle<int>(centerX, 0, width - centerX, centerY),
    Rectangle<int>(0, centerY, centerX, height - centerY),
    Rectangle<int>(centerX, centerY, width - centerX, height - centerY),
  ];

  return {
    'bytes': slicedBytes,
    'quadrants': quadrants,
    'originalDimensions': Rectangle<int>(0, 0, width, height),
  };
}

/// Helper function to save sliced images to files
Future<void> saveSlicedImages(
  List<Uint8List> slicedBytes,
  String outputDir, {
  String prefix = 'slice',
}) async {
  final directory = Directory(outputDir);
  if (!await directory.exists()) {
    await directory.create(recursive: true);
  }

  final positions = ['top_left', 'top_right', 'bottom_left', 'bottom_right'];

  for (int i = 0; i < slicedBytes.length; i++) {
    final outputPath = '${directory.path}/$prefix${positions[i]}.png';
    final file = File(outputPath);
    await file.writeAsBytes(slicedBytes[i]);
    print('Saved: $outputPath');
  }
}

/// Example usage
Future<void> exampleUsage() async {
  try {
    // Method 1: Using file path
    final sliced = await sliceImageIntoFourBytes('path/to/your/image.jpg');
    print('Sliced into ${sliced.length} parts');

    // Save to files
    await saveSlicedImages(sliced, 'output_slices');

