    final file = File('path/to/your/image.jpg');
    final imageBytes = await file.readAsBytes();
    final slicedFromBytes = await sliceImageIntoFourBytes(imageBytes);

    // Method 3: Get metadata along with bytes
    final result = await sliceImageWithMetadata('path/to/your/image.jpg');
    final bytes = result['bytes'] as List<Uint8List>;
    final quadrants = result['quadrants'] as List<Rectangle<int>>;

    print('Quadrant dimensions:');
    for (int i = 0; i < quadrants.length; i++) {
      print('  ${['TL', 'TR', 'BL', 'BR'][i]}: ${quadrants[i].width}x${quadrants[i].height}');
    }

  } on ArgumentError catch (e) {
    print('Error: $e');
  } on FileSystemException catch (e) {
    print('File error: $e');
  }
}

void main() async {
