class BST:
    """Binary Search Tree with robust error handling"""

    def __init__(self):
        self.root: Optional[Node] = None
        self.node_count = 0

    def build_balanced_from_sorted(self, arr: List[int]) -> bool:
        """
        Build balanced BST from sorted array
        Returns: True if successful, False otherwise
        """
        if not arr:
            self.root = None
            self.node_count = 0
            return True

        try:
            self.node_count = len(arr)
            self.root = self._build_balanced(arr, 0, len(arr) - 1)
            return True
        except RecursionError:
            print("Error: Recursion depth exceeded. Array too large for recursive method.")
            return False
        except MemoryError:
            print("Error: Memory allocation failed.")
            return False
        except Exception as e:
            print(f"Error building BST: {e}")
            return False

    def _build_balanced(self, arr: List[int], start: int, end: int) -> Optional[Node]:
        """Recursive balanced tree construction with overflow protection"""
        if start > end:
            return None

        # Safe midpoint calculation - prevents integer overflow
        mid = start + (end - start) // 2

        node = Node(arr[mid])
        node.left = self._build_balanced(arr, start, mid - 1)
        node.right = self._build_balanced(arr, mid + 1, end)

        return node

    def get_inorder(self) -> List[int]:
        """Return values in sorted order"""
        result: List[int] = []
        self._inorder_traversal(self.root, result)
        return result

    def _inorder_traversal(self, node: Optional[Node], result: List[int]) -> None:
        """Inorder traversal helper"""
        if node:
            self._inorder_traversal(node.left, result)
            result.append(node.value)
            self._inorder_traversal(node.right, result)

    def get_height(self) -> int:
        """Calculate tree height"""
        return self._calculate_height(self.root)

    def _calculate_height(self, node: Optional[Node]) -> int:
        """Height calculation helper"""
        if node is None:
            return 0
        return 1 + max(self._calculate_height(node.left), 
                      self._calculate_height(node.right))

    def is_balanced(self) -> bool:
        """Check if tree is height-balanced"""
        return self._check_balance(self.root) != -1

    def _check_balance(self, node: Optional[Node]) -> int:
        """Return height if balanced, -1 if not"""
        if node is None:
            return 0

        left_height = self._check_balance(node.left)
        if left_height == -1:
            return -1

        right_height = self._check_balance(node.right)
        if right_height == -1:
            return -1

        if abs(left_height - right_height) > 1:
            return -1

        return 1 + max(left_height, right_height)

def selection_sort_robust(arr: List[int]) -> Tuple[List[int], bool]:
    """
    Robust selection sort implementation
    Returns: (sorted_array, success_flag)
    """
    if not arr:
