        sorted_arr = arr.copy()
        n = len(sorted_arr)

        # Early check for already sorted
        is_sorted = True
        for i in range(n - 1):
            if sorted_arr[i] > sorted_arr[i + 1]:
                is_sorted = False
                break

        if is_sorted:
