```matlab
function [x, err, fig] = solve_LS(A, b)
    % Solve least squares problem Ax = b and compute error visualization.
    %
    % Parameters:
    %   A : matrix (m x n)
    %   b : column vector (m x 1)
    %
    % Returns:
    %   x   : least squares solution
    %   err : error vector Ax - b
    %   fig : figure handle with error plot

    % Check the rank of A
    rank_A = rank(A);
    [m, n] = size(A);

    % Solve least squares problem
    if rank_A == n && m >= n
        % Full column rank - use normal equations
        x = (A' * A) \ (A' * b);
    else
        % Rank-deficient or underdetermined - use pseudo-inverse
        x = pinv(A) * b;
    end

    % Compute error vector
    err = A * x - b;

    % Create figure
    fig = figure;
    hold on;

    % Generate x-indices for plotting
    x_indices = 1:length(err);

    % Plot black data points with MarkerSize 20
    scatter(x_indices, err, 200, 'k', 'filled', 'DisplayName', 'Error points');

    % Plot horizontal red dotted line at y=0 using yline()
    yline(0, 'r:', 'LineWidth', 1.5, 'DisplayName', 'Zero error line');

    % Plot blue dotted lines from each point to y=0 using line()
    for i = 1:length(err)
        line([i, i], [err(i), 0], 'Color', 'b', 'LineStyle', ':', ...
             'LineWidth', 1.5, 'HandleVisibility', 'off');
    end

    % Set axis limits with padding of 1
    x_min = min(x_indices);
    x_max = max(x_indices);
    y_min = min(err);
    y_max = max(err);

    xlim([x_min - 1, x_max + 1]);
    ylim([y_min - 1, y_max + 1]);

    % Set labels and title
    xlabel('x (data point index)');
    ylabel('Ax - b (error)');
    title('Error computed from Ax - b');

    % Add grid and legend
    grid on;
    legend('Location', 'best');

    hold off;
end
