        return metadata

    def _generate_toc(self, html_content: str) -> List[Dict[str, Any]]:
        """Generate table of contents from HTML"""
        toc = []

        # Extract headings with IDs
        heading_pattern = r'<h([1-6])[^>]*id="([^"]*)"[^>]*>(.*?)</h\1>'
        for match in re.finditer(heading_pattern, html_content, re.DOTALL):
            level = int(match.group(1))
            id = match.group(2)
            text = re.sub(r'<[^>]+>', '', match.group(3)).strip()

            toc.append({
                'level': level,
                'id': id,
                'text': text
            })

        return toc

    def _calculate_stats(self, markdown_text: str) -> Dict[str, Any]:
        """Calculate content statistics"""
        words = markdown_text.split()
        sentences = re.split(r'[.!?]+', markdown_text)

        return {
            'words': len(words),
            'characters': len(markdown_text),
            'sentences': len([s for s in sentences if s.strip()]),
            'paragraphs': len([p for p in markdown_text.split('\n\n') if p.strip()]),
            'reading_time': max(1, len(words) // 200),  # 200 words per minute
            'complexity': self._calculate_complexity(markdown_text)
        }

    def _calculate_complexity(self, text: str) -> float:
        """Calculate text complexity score"""
        words = text.split()
        if not words:
            return 0.0

        avg_word_length = sum(len(word) for word in words) / len(words)
        unique_words = len(set(word.lower() for word in words))
        lexical_diversity = unique_words / len(words)

        return round((avg_word_length * 0.3 + lexical_diversity * 0.7) * 100, 2)

