    """
    try:
        result = processor.process(content.markdown, add_tailwind=False)
        metadata = result['metadata']

        # Perform validation checks
        issues = []
        warnings = []

        # Check for empty headings
        for heading in metadata['headings']:
            if not heading['text'].strip():
                issues.append({
                    "type": "empty_heading",
                    "line": heading['line'],
                    "message": "Empty heading found"
                })

        # Check for very short content
        if metadata['word_count'] < 50:
            warnings.append({
                "type": "short_content",
                "message": "Content is very short. Consider adding more details."
            })

        # Check for missing headings
        if not metadata['headings']:
            warnings.append({
                "type": "no_headings",
                "message": "No headings found. Add headings to organize your content."
            })

        return {
            "success": True,
            "valid": len(issues) == 0,
            "issues": issues,
            "warnings": warnings,
            "metadata": metadata,
            "stats": result['stats']
        }

    except Exception as e:
