    /// <summary>
    /// Converts an Image to a byte array with compression options
    /// </summary>
    /// <param name="image">The input image to process</param>
    /// <param name="format">Image format (JPEG or PNG)</param>
    /// <param name="quality">Quality parameter (1-100 for JPEG, ignored for PNG)</param>
    /// <param name="maxSizeKB">Maximum output size in KB (0 for no limit)</param>
    /// <returns>Byte array containing the compressed image</returns>
    public static byte[] ConvertImageToByteArray(Image image, ImageFormat format, int quality = 85, int maxSizeKB = 0)
    {
        if (image == null)
            throw new ArgumentNullException(nameof(image));

        if (format != ImageFormat.Jpeg && format != ImageFormat.Png)
            throw new ArgumentException("Only JPEG and PNG formats are supported", nameof(format));

        if (quality < 1 || quality > 100)
            throw new ArgumentOutOfRangeException(nameof(quality), "Quality must be between 1 and 100");

        using (MemoryStream ms = new MemoryStream())
        {
            // Handle JPEG compression with quality parameter
            if (format == ImageFormat.Jpeg)
            {
                ImageCodecInfo jpegCodec = GetEncoderInfo("image/jpeg");
                EncoderParameters encoderParams = new EncoderParameters(1);
                encoderParams.Param[0] = new EncoderParameter(Encoder.Quality, quality);

                image.Save(ms, jpegCodec, encoderParams);
            }
            // Handle PNG compression (quality parameter not applicable)
            else
            {
                image.Save(ms, ImageFormat.Png);
            }

            byte[] imageBytes = ms.ToArray();

            // Apply size constraint if specified
            if (maxSizeKB > 0)
            {
                imageBytes = ConstrainImageSize(imageBytes, format, maxSizeKB, quality);
            }

            return imageBytes;
        }
    }

    /// <summary>
    /// Constrains the image size to a maximum KB limit
    /// </summary>
    private static byte[] ConstrainImageSize(byte[] imageBytes, ImageFormat format, int maxSizeKB, int initialQuality)
    {
        int maxBytes = maxSizeKB * 1024;

        // If already under limit, return as-is
        if (imageBytes.Length <= maxBytes)
            return imageBytes;

        // For JPEG, we can reduce quality iteratively
        if (format == ImageFormat.Jpeg)
        {
            using (MemoryStream ms = new MemoryStream(imageBytes))
            using (Image image = Image.FromStream(ms))
            {
                int currentQuality = initialQuality;

                // Reduce quality until we meet size constraint or reach minimum quality
                while (imageBytes.Length > maxBytes && currentQuality > 10)
                {
                    currentQuality -= 5;

                    using (MemoryStream newMs = new MemoryStream())
                    {
                        ImageCodecInfo jpegCodec = GetEncoderInfo("image/jpeg");
                        EncoderParameters encoderParams = new EncoderParameters(1);
                        encoderParams.Param[0] = new EncoderParameter(Encoder.Quality, currentQuality);

                        image.Save(newMs, jpegCodec, encoderParams);
                        imageBytes = newMs.ToArray();
                    }
                }
            }
        }
        // For PNG, we could resize the image, but that's more complex
        // For simplicity, we'll just return the original if it's too large
        // In a production system, you might want to implement resizing

        return imageBytes;
    }

    /// <summary>
    /// Gets the image encoder for a specific MIME type
    /// </summary>
    private static ImageCodecInfo GetEncoderInfo(string mimeType)
    {
        ImageCodecInfo[] codecs = ImageCodecInfo.GetImageEncoders();

        foreach (ImageCodecInfo codec in codecs)
        {
            if (codec.MimeType == mimeType)
                return codec;
        }

        throw new NotSupportedException($"No encoder found for MIME type: {mimeType}");
    }
