    <script>
        class CardioAnimation {
            constructor() {
                // DOM Elements
                this.canvas = document.getElementById('waveformCanvas');
                this.ctx = this.canvas.getContext('2d');
                this.pulseDot = document.getElementById('pulseDot');
                this.statusIndicator = document.getElementById('statusIndicator');
                this.statusText = document.getElementById('statusText');
                this.speedValue = document.getElementById('speedValue');
                this.pulseHeightValue = document.getElementById('pulseHeightValue');

                // Animation state
                this.isRunning = false;
                this.animationId = null;
                this.lastTimestamp = 0;

                // Container dimensions
                this.container = document.querySelector('.animation-container');
                this.width = this.container.clientWidth;
                this.height = this.container.clientHeight;

                // Set canvas dimensions
                this.canvas.width = this.width;
                this.canvas.height = this.height;

                // Animation parameters
                this.pulseX = 0;
                this.pulseSpeed = 3; // pixels per frame
                this.baseY = this.height / 2;

                // Pulse parameters
                this.isPulsing = false;
                this.pulseStartTime = 0;
                this.pulseDuration = 1000; // 1 second pulse duration
                this.maxPulseHeight = 20; // Maximum pulse height in pixels
                this.pulseInterval = 2000 + Math.random() * 2000; // 2-4 seconds between pulses
                this.lastPulseTime = 0;

                // Waveform data
                this.wavePoints = [];
                this.generateWaveform();

                // Initialize controls
                this.initControls();
                this.initKeyboardControls();

                // Update status
                this.updateStatus();
            }

            generateWaveform() {
                this.wavePoints = [];
                let x = 0;
                let currentY = this.baseY;

                // Generate a realistic ECG-like waveform
                while (x < this.width * 2) { // Generate extra width for smooth scrolling
                    // Add small random variations
                    const segmentLength = Math.floor(Math.random() * 50) + 30;

                    for (let i = 0; i < segmentLength && x < this.width * 2; i++) {
                        // Small vertical variations
                        const yVariation = (Math.random() - 0.5) * 4;
                        this.wavePoints.push({
                            x: x,
                            y: currentY + yVariation
                        });
                        x++;
                    }

                    // Occasionally add larger variations (like heartbeats)
                    if (Math.random() < 0.3) {
                        const variationSize = Math.random() * 15 + 5;
                        const variationDirection = Math.random() < 0.5 ? 1 : -1;
                        currentY += variationSize * variationDirection;

                        // Keep within bounds
                        currentY = Math.max(10, Math.min(this.height - 10, currentY));
                    }
                }
            }

            getWaveformYAtX(x) {
                // Find the Y value at a given X position in the waveform
                const wrappedX = x % (this.width * 2);

                // Find the two nearest points
                let point1 = null;
                let point2 = null;

                for (let i = 0; i < this.wavePoints.length - 1; i++) {
                    if (this.wavePoints[i].x <= wrappedX && this.wavePoints[i + 1].x >= wrappedX) {
                        point1 = this.wavePoints[i];
                        point2 = this.wavePoints[i + 1];
                        break;
                    }
                }

                if (!point1 || !point2) {
                    return this.baseY;
                }

                // Linear interpolation between points
                const t = (wrappedX - point1.x) / (point2.x - point1.x);
                return point1.y + (point2.y - point1.y) * t;
            }

            updatePulse(timestamp) {
                if (!this.lastTimestamp) {
                    this.lastTimestamp = timestamp;
                }

                const deltaTime = timestamp - this.lastTimestamp;
                this.lastTimestamp = timestamp;

                // Move pulse from left to right
                this.pulseX += this.pulseSpeed;
                if (this.pulseX > this.width) {
                    this.pulseX = 0;
                }

                // Check for automatic pulse trigger
                const currentTime = Date.now();
                if (currentTime - this.lastPulseTime > this.pulseInterval && !this.isPulsing) {
                    this.startPulse();
                    this.lastPulseTime = currentTime;
                    this.pulseInterval = 2000 + Math.random() * 2000; // New random interval
                }

                // Update pulse animation
                if (this.isPulsing) {
                    const pulseElapsed = currentTime - this.pulseStartTime;

                    if (pulseElapsed < this.pulseDuration) {
                        // Triangular waveform calculation
                        const progress = pulseElapsed / this.pulseDuration;
                        let pulseHeight;

                        if (progress < 0.5) {
                            // Rising phase: 0 to max height
                            pulseHeight = (progress * 2) * this.maxPulseHeight;
                        } else {
                            // Falling phase: max height to 0
                            pulseHeight = ((1 - progress) * 2) * this.maxPulseHeight;
                        }

                        this.currentPulseHeight = pulseHeight;
                        this.pulseHeightValue.textContent = Math.round(pulseHeight);

                        // Update dot position with pulse effect
                        const waveformY = this.getWaveformYAtX(this.pulseX);
                        const pulseY = waveformY - pulseHeight;

                        this.pulseDot.style.top = `${pulseY}px`;
                        this.pulseDot.classList.add('pulsing');

                        // Scale the dot based on pulse height
                        const scale = 1 + (pulseHeight / this.maxPulseHeight) * 2;
                        this.pulseDot.style.transform = `translate(-50%, -50%) scale(${scale})`;
                    } else {
                        // End pulse
                        this.isPulsing = false;
                        this.currentPulseHeight = 0;
                        this.pulseDot.classList.remove('pulsing');
                        this.pulseDot.style.transform = `translate(-50%, -50%) scale(1)`;
                        this.pulseHeightValue.textContent = '0';
                    }
                } else {
                    // Normal movement without pulse
                    const waveformY = this.getWaveformYAtX(this.pulseX);
                    this.pulseDot.style.top = `${waveformY}px`;
                }

                // Update dot horizontal position
                this.pulseDot.style.left = `${this.pulseX}px`;

                // Draw waveform
                this.drawWaveform();
            }

            startPulse() {
                this.isPulsing = true;
                this.pulseStartTime = Date.now();
                this.updateStatus();
            }

            drawWaveform() {
                // Clear canvas
                this.ctx.clearRect(0, 0, this.width, this.height);

                // Draw waveform line
                this.ctx.beginPath();
                this.ctx.strokeStyle = '#0f0';
                this.ctx.lineWidth = 2;
                this.ctx.lineCap = 'round';
                this.ctx.lineJoin = 'round';

                // Draw visible portion of waveform
                for (let i = 0; i < this.wavePoints.length - 1; i++) {
                    const point1 = this.wavePoints[i];
                    const point2 = this.wavePoints[i + 1];

                    // Adjust X position for scrolling effect
                    const x1 = (point1.x - this.pulseX) % (this.width * 2);
                    const x2 = (point2.x - this.pulseX) % (this.width * 2);

                    // Only draw if points are visible
                    if ((x1 >= 0 && x1 <= this.width) || (x2 >= 0 && x2 <= this.width)) {
                        // Adjust X to ensure continuity
                        const adjustedX1 = x1 < 0 ? x1 + this.width * 2 : x1;
                        const adjustedX2 = x2 < 0 ? x2 + this.width * 2 : x2;

                        if (i === 0) {
                            this.ctx.moveTo(adjustedX1, point1.y);
                        }
                        this.ctx.lineTo(adjustedX2, point2.y);
                    }
                }

                this.ctx.stroke();
            }

            animate(timestamp) {
                if (!this.isRunning) return;

                this.updatePulse(timestamp);
                this.animationId = requestAnimationFrame(this.animate.bind(this));
            }

            start() {
                if (!this.isRunning) {
                    this.isRunning = true;
                    this.lastTimestamp = 0;
                    this.animationId = requestAnimationFrame(this.animate.bind(this));
                    this.updateStatus();
                }
            }

            stop() {
                this.isRunning = false;
                if (this.animationId) {
                    cancelAnimationFrame(this.animationId);
                    this.animationId = null;
                }
                this.updateStatus();
            }

            updateStatus() {
                if (this.isRunning) {
                    this.statusIndicator.classList.add('active');
                    this.statusText.textContent = this.isPulsing ? 'Pulsing' : 'Running';
                } else {
                    this.statusIndicator.classList.remove('active');
                    this.statusText.textContent = 'Stopped';
                }
                this.speedValue.textContent = this.pulseSpeed;
            }

            initControls() {
                document.getElementById('startBtn').addEventListener('click', () => this.start());
                document.getElementById('stopBtn').addEventListener('click', () => this.stop());
                document.getElementById('triggerPulseBtn').addEventListener('click', () => this.startPulse());
                document.getElementById('resetWaveBtn').addEventListener('click', () => {
                    this.generateWaveform();
                    this.drawWaveform();
                });
                document.getElementById('increaseSpeedBtn').addEventListener('click', () => {
                    this.pulseSpeed = Math.min(10, this.pulseSpeed + 0.5);
                    this.updateStatus();
                });
                document.getElementById('decreaseSpeedBtn').addEventListener('click', () => {
                    this.pulseSpeed = Math.max(0.5, this.pulseSpeed - 0.5);
                    this.updateStatus();
                });
            }

            initKeyboardControls() {
                document.addEventListener('keydown', (e) => {
                    switch (e.code) {
                        case 'Space':
                            e.preventDefault();
                            this.startPulse();
                            break;
                        case 'KeyS':
                            if (this.isRunning) {
                                this.stop();
                            } else {
                                this.start();
                            }
                            break;
                        case 'KeyR':
                            this.generateWaveform();
                            this.drawWaveform();
                            break;
                        case 'ArrowUp':
                            this.pulseSpeed = Math.min(10, this.pulseSpeed + 0.5);
                            this.updateStatus();
                            break;
                        case 'ArrowDown':
                            this.pulseSpeed = Math.max(0.5, this.pulseSpeed - 0.5);
                            this.updateStatus();
                            break;
                    }
                });
            }

            handleResize() {
                this.width = this.container.clientWidth;
                this.height = this.container.clientHeight;
                this.canvas.width = this.width;
                this.canvas.height = this.height;
                this.baseY = this.height / 2;
                this.generateWaveform();
                this.drawWaveform();
            }
        }

