using Autodesk.AdvanceSteel.DocumentManagement;
using Autodesk.AdvanceSteel.Modeling;
using Autodesk.AdvanceSteel.CADAccess;
using Autodesk.AdvanceSteel.Drafting;

namespace AdvanceSteelHoleDimensioning
{
    /// <summary>
    /// Provides methods for creating Cartesian hole dimensions relative to plate bottom-left corner
    /// </summary>
    public class HoleDimensioningService
    {
        /// <summary>
        /// Creates Cartesian dimensions for holes in a plate relative to bottom-left corner
        /// </summary>
        /// <param name="plateHandle">Handle to the plate object</param>
        /// <param name="drawingViewHandle">Handle to the drawing view</param>
        /// <returns>List of created dimension lines</returns>
        public List<DimensionLine> CreateCartesianHoleDimensions(string plateHandle, string drawingViewHandle)
        {
            if (string.IsNullOrEmpty(plateHandle))
                throw new ArgumentNullException(nameof(plateHandle));
            if (string.IsNullOrEmpty(drawingViewHandle))
                throw new ArgumentNullException(nameof(drawingViewHandle));

            var dimensionLines = new List<DimensionLine>();

            try
            {
                // Get objects from handles
                var plate = DocumentManager.GetObject(plateHandle) as Plate;
                var drawingView = DocumentManager.GetObject(drawingViewHandle) as DrawingView;

                if (plate == null)
                    throw new InvalidOperationException("Invalid plate handle");
                if (drawingView == null)
                    throw new InvalidOperationException("Invalid drawing view handle");

                // Get plate boundary for origin calculation
                var plateBoundingBox = plate.GetBoundingBox();

                // Define origin as bottom-left corner of plate
                var originX = plateBoundingBox.MinPoint.X;
                var originY = plateBoundingBox.MinPoint.Y;

                // Get all holes in the plate
                var holes = GetHolesFromPlate(plate);

                foreach (var hole in holes)
                {
                    // Get hole center position
                    var holePosition = hole.GetPosition();

                    // Calculate relative coordinates
                    var relativeX = holePosition.X - originX;
                    var relativeY = holePosition.Y - originY;

                    // Convert model coordinates to drawing view coordinates
                    var viewPoint = drawingView.ModelToView(holePosition);
                    var originViewPoint = drawingView.ModelToView(
                        new Point3d(originX, originY, holePosition.Z));

                    // Create horizontal dimension line (X coordinate)
                    var dimensionLineX = CreateDimensionLine(
                        originViewPoint,
                        new Point3d(viewPoint.X, originViewPoint.Y, viewPoint.Z),
                        viewPoint,
                        $"X={relativeX:F1}");

                    // Create vertical dimension line (Y coordinate)
                    var dimensionLineY = CreateDimensionLine(
                        originViewPoint,
                        new Point3d(originViewPoint.X, viewPoint.Y, viewPoint.Z),
                        viewPoint,
                        $"Y={relativeY:F1}");

                    // Add to drawing view
                    drawingView.AddObject(dimensionLineX);
                    drawingView.AddObject(dimensionLineY);

                    dimensionLines.Add(dimensionLineX);
                    dimensionLines.Add(dimensionLineY);
                }

                // Update the drawing
                drawingView.Update();
            }
            catch (Exception ex)
            {
                // Log error and rethrow or handle appropriately
                throw new InvalidOperationException("Failed to create hole dimensions", ex);
            }

            return dimensionLines;
        }

        /// <summary>
        /// Alternative method: Creates a coordinate table for holes
        /// </summary>
        public TextNote CreateHoleCoordinateTable(string plateHandle, string drawingViewHandle)
        {
            if (string.IsNullOrEmpty(plateHandle))
                throw new ArgumentNullException(nameof(plateHandle));
            if (string.IsNullOrEmpty(drawingViewHandle))
                throw new ArgumentNullException(nameof(drawingViewHandle));

            try
            {
                var plate = DocumentManager.GetObject(plateHandle) as Plate;
                var drawingView = DocumentManager.GetObject(drawingViewHandle) as DrawingView;

                if (plate == null || drawingView == null)
                    throw new InvalidOperationException("Invalid object handles");

                var plateBoundingBox = plate.GetBoundingBox();
                var originX = plateBoundingBox.MinPoint.X;
                var originY = plateBoundingBox.MinPoint.Y;

                var holes = GetHolesFromPlate(plate);

                // Build coordinate table text
                var tableText = BuildCoordinateTableText(holes, originX, originY);

                // Create text object in drawing
                var textPosition = drawingView.ModelToView(
                    new Point3d(originX, originY - 100, 0)); // Position below plate

                var textNote = new TextNote
                {
                    TextString = tableText,
                    Position = textPosition,
                    Height = 3.0 // Text height in drawing units
                };

                drawingView.AddObject(textNote);
                drawingView.Update();

                return textNote;
            }
            catch (Exception ex)
            {
                throw new InvalidOperationException("Failed to create coordinate table", ex);
            }
        }

        /// <summary>
        /// Retrieves holes from a plate using multiple strategies
        /// </summary>
        private List<dynamic> GetHolesFromPlate(Plate plate)
        {
            var holes = new List<dynamic>();

            // Strategy 1: Try GetHoles() method if available
            try
            {
                // Note: The actual method name might differ - check API documentation
                var plateHoles = plate.GetType().GetMethod("GetHoles")?.Invoke(plate, null);
                if (plateHoles is IEnumerable<dynamic> holeCollection)
                {
                    holes.AddRange(holeCollection);
                    return holes;
                }
            }
            catch
            {
                // Method not available or failed
            }

            // Strategy 2: Search through features
            try
            {
                var features = plate.GetFeatures();
                foreach (var feature in features)
                {
                    var featureType = feature.GetType().Name;
                    if (featureType.Contains("Hole", StringComparison.OrdinalIgnoreCase))
                    {
                        holes.Add(feature);
                    }
                }
            }
            catch
            {
                // Features not accessible
            }

            // Strategy 3: Search through children
            try
            {
                var children = plate.GetChildren();
                foreach (var child in children)
                {
                    var childType = child.GetType().Name;
                    if (childType.Contains("Hole", StringComparison.OrdinalIgnoreCase))
                    {
                        holes.Add(child);
                    }
                }
            }
            catch
            {
                // Children not accessible
            }

            return holes;
        }

        /// <summary>
        /// Creates a dimension line with specified points and text
        /// </summary>
        private DimensionLine CreateDimensionLine(Point3d point1, Point3d point2, Point3d point3, string text)
        {
            var dimensionLine = new DimensionLine
            {
                DimensionType = DimensionType.eLinearDimension
            };

            var points = new List<Point3d> { point1, point2, point3 };
            dimensionLine.SetPoints(points);
            dimensionLine.Text = text;

            return dimensionLine;
        }

        /// <summary>
        /// Builds formatted coordinate table text
        /// </summary>
        private string BuildCoordinateTableText(List<dynamic> holes, double originX, double originY)
        {
            var tableText = "Hole Coordinates (relative to bottom-left):\n";
            tableText += "Hole #\tX\t\tY\t\tDiameter\n";
            tableText += new string('-', 50) + "\n";

            for (int i = 0; i < holes.Count; i++)
            {
                var hole = holes[i];
                var holePosition = hole.GetPosition();
                var relativeX = holePosition.X - originX;
                var relativeY = holePosition.Y - originY;

                double diameter = 0.0;
                try
                {
                    // Try to get diameter property
                    diameter = hole.Diameter;
                }
                catch
                {
                    // Diameter property not available
                }

                tableText += $"{i + 1}\t\t{relativeX:F1}\t\t{relativeY:F1}\t\t{diameter:F1}\n";
            }

            return tableText;
        }
    }

    /// <summary>
    /// Example usage class
    /// </summary>
    public class ExampleUsage
    {
        public void RunExample()
        {
            var dimensioningService = new HoleDimensioningService();

            // Get current document
            var document = DocumentManager.CurrentDocument;

            // Find plates (simplified - use proper selection in production)
            var plates = document.GetObjectsByType(typeof(Plate)).Cast<Plate>().ToList();

            if (plates.Count > 0)
            {
                var plateHandle = plates[0].Handle;

                // Find drawing views (simplified)
                var drawingViews = document.GetObjectsByType(typeof(DrawingView)).Cast<DrawingView>().ToList();

                if (drawingViews.Count > 0)
                {
                    var drawingViewHandle = drawingViews[0].Handle;

                    try
                    {
                        // Option 1: Create Cartesian dimensions
                        var dimensions = dimensioningService.CreateCartesianHoleDimensions(
                            plateHandle, drawingViewHandle);

                        Console.WriteLine($"Created {dimensions.Count} dimension lines");

                        // Option 2: Create coordinate table
                        // var table = dimensioningService.CreateHoleCoordinateTable(
                        //     plateHandle, drawingViewHandle);
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Error: {ex.Message}");
                    }
                }
            }
        }
    }
}
