        'dbus', 'expat',
    }

    # Dependencies that are usually in base-devel or base
    base_system_deps = {'glibc', 'libstdc++', 'zlib', 'gcc-libs'}

    # Check for missing essential dependencies
    missing_essential = essential_electron_deps - dependencies - base_system_deps

    if missing_essential:
        results["missing_dependencies"].append("Missing essential Electron dependencies:")
        for dep in sorted(missing_essential):
