    // Hide all tabs
    document.querySelectorAll('.tab-content').forEach(tab => {
        tab.classList.remove('active');
    });
    document.querySelectorAll('.tab').forEach(tab => {
        tab.classList.remove('active');
    });

    // Show selected tab
    document.getElementById(tabName + 'Tab').classList.add('active');
    event.target.classList.add('active');

    // Clear error messages
    hideAllMessages();
}

// Hide all error/success messages
function hideAllMessages() {
    document.querySelectorAll('.error-message, .success-message').forEach(msg => {
        msg.style.display = 'none';
    });
}

// User registration function
function register() {
    const username = document.getElementById('registerUsername').value.trim();
    const password = document.getElementById('registerPassword').value;
    const confirmPassword = document.getElementById('registerConfirmPassword').value;
    const errorElement = document.getElementById('registerError');
    const successElement = document.getElementById('registerSuccess');

    // Hide previous messages
    hideAllMessages();

    // Validation
    if (!username || !password || !confirmPassword) {
        errorElement.textContent = 'Please fill in all fields';
        errorElement.style.display = 'block';
        return;
    }

    if (username.length < 3) {
        errorElement.textContent = 'Username must be at least 3 characters';
        errorElement.style.display = 'block';
        return;
    }

    if (password.length < 6) {
        errorElement.textContent = 'Password must be at least 6 characters';
        errorElement.style.display = 'block';
        return;
    }

    if (password !== confirmPassword) {
        errorElement.textContent = 'Passwords do not match';
        errorElement.style.display = 'block';
        return;
    }

    if (users[username]) {
        errorElement.textContent = 'Username already exists';
        errorElement.style.display = 'block';
        return;
    }

    // Register new user
    users[username] = {
        password: password,
        stats: {
            gamesPlayed: 0,
            gamesWon: 0,
            totalScore: 0,
            totalHits: 0,
            totalOpponentHits: 0,
            totalPowerUps: 0,
            joinDate: new Date().toISOString()
        }
    };

    // Save to localStorage
    localStorage.setItem('tennisGameUsers', JSON.stringify(users));

    // Show success message
    successElement.style.display = 'block';

    // Clear form
    document.getElementById('registerUsername').value = '';
    document.getElementById('registerPassword').value = '';
    document.getElementById('registerConfirmPassword').value = '';

    // Switch to login tab after 2 seconds
    setTimeout(() => {
        switchTab('login');
        successElement.style.display = 'none';
    }, 2000);
}

// User login function
function login() {
    const username = document.getElementById('loginUsername').value.trim();
    const password = document.getElementById('loginPassword').value;
    const errorElement = document.getElementById('loginError');

    // Hide previous messages
    hideAllMessages();

    // Validation
    if (!username || !password) {
        errorElement.textContent = 'Please enter username and password';
        errorElement.style.display = 'block';
        return;
    }

    // Check credentials
