def create_robust_playbook_framework():
    """
    Create a framework for robust Ansible playbooks that prevent templating errors.
    """

    framework = """
    ## ROBUST PLAYBOOK FRAMEWORK

    ### 1. PRE-PROCESSING PHASE
    ```yaml
    - name: Initialize playbook with safety checks
      block:
        - name: Check required variables
          assert:
            that: required_vars is defined
            fail_msg: "required_vars must be defined"

        - name: Load custom filters
          include_vars:
            file: filter_plugins/custom_filters.yml

        - name: Set default values for all variables
          set_fact:
            safe_groups: "{{ groups | default({}) }}"
            safe_hostvars: "{{ hostvars | default({}) }}"
            safe_all_hosts: "{{ groups.get('all', []) | default([]) }}"
      rescue:
        - name: Handle initialization errors
          debug:
            msg: "Playbook initialization failed. Check variable definitions."
          meta: end_play
    ```

    ### 2. TEMPLATE VALIDATION PHASE
    ```yaml
    - name: Validate all templates before use
      block:
        - name: Test complex templates
          debug:
            msg: "Template validation: {{ validation_result }}"
          vars:
            test_data:
              groups:
                all: ['test1', 'test2']
              hostvars:
                test1:
                  ansible_host: '192.168.1.1'
            template_to_test: |
              {{ test_data.groups.all | select('in', test_data.hostvars) | list }}
            validation_result: "{{ template_to_test | from_yaml }}"
          when: ansible_verbosity > 1

        - name: Create safe template wrapper
          set_fact:
            safe_template_function: |
              {% macro safe_select_in(items, container) %}
                {% if container is mapping %}
                  {{ items | select('in', container) | list }}
                {% else %}
                  {% set result = [] %}
                  {% for item in items %}
                    {% if item in container %}
                      {% set _ = result.append(item) %}
                    {% endif %}
                  {% endfor %}
                  {{ result }}
                {% endif %}
              {% endmacro %}
    ```

    ### 3. MAIN PROCESSING WITH ERROR HANDLING
    ```yaml
    - name: Main processing with comprehensive error handling
      block:
        - name: Process each target IP
          loop: "{{ target_ips | default([]) }}"
          loop_control:
            label: "Processing IP: {{ item }}"
          block:
            - name: Find matching hosts (safe method)
              set_fact:
                current_matches: "{{ lookup('template', 'safe_find_hosts.j2') }}"
              vars:
                target_ip: "{{ item }}"

            - name: Validate results
              assert:
                that:
                  - "current_matches is defined"
                  - "current_matches is iterable"
                fail_msg: "Template returned invalid result for IP {{ item }}"

            - name: Store results
              set_fact:
                ip_to_hosts: "{{ ip_to_hosts | default({}) | combine({item: current_matches}) }}"

          rescue:
            - name: Handle processing error for this IP
              debug:
                msg: "Failed to process IP {{ item }}: {{ ansible_failed_result.msg }}"
              set_fact:
                ip_to_hosts: "{{ ip_to_hosts | default({}) | combine({item: ['ERROR']}) }}"
    ```

    ### 4. POST-PROCESSING AND REPORTING
    ```yaml
    - name: Generate comprehensive report
      block:
        - name: Create success/failure summary
          set_fact:
            processing_summary: |
              {% set summary = {'total_ips': target_ips|length, 'success': 0, 'failed': 0} %}
              {% for ip, hosts in ip_to_hosts.items() %}
                {% if hosts is iterable and hosts|length > 0 and hosts[0] != 'ERROR' %}
                  {% set _ = summary.update({'success': summary.success + 1}) %}
                {% else %}
                  {% set _ = summary.update({'failed': summary.failed + 1}) %}
                {% endif %}
              {% endfor %}
              {{ summary }}

        - name: Output results
          debug:
            msg: |
              Processing Complete:
              ====================
