              {% for ip, hosts in ip_to_hosts.items() %}
              IP: {{ ip }}
                Hosts: {{ hosts | join(', ') }}
              {% endfor %}
    ```

    ### 5. CLEANUP AND AUDIT
    ```yaml
    - name: Cleanup and audit
      always:
        - name: Log playbook execution
          debug:
            msg: "Playbook completed at {{ ansible_date_time.iso8601 }}"

        - name: Save processing results for audit
