            if not self.validate_command(command_str):
                channel.send(b'{"success": false, "error": "Command validation failed"}\n')
                channel.send_exit_status(1)
                return True

            # Execute in separate thread
            threading.Thread(
                target=self.execute_command_async,
                args=(channel, command_str),
                daemon=True
            ).start()

            return True
        except Exception as e:
            logger.error(f"Error processing command: {e}")
            return False

    def validate_command(self, command: str) -> bool:
        """Validate command with security checks"""
        # Check client permissions
        client_info = self.allowed_clients.get(self.client_id, {})
        permissions = client_info.get('permissions', [])

        # Basic security checks
        dangerous_patterns = [
            'rm -rf /', 'sudo', ';', '&&', '||', '`', '$(',
            '> /dev/', 'cat /etc/shadow', 'chmod 777', 'dd if='
        ]

        for pattern in dangerous_patterns:
            if pattern in command.lower():
                logger.warning(f"Blocked dangerous pattern: {pattern}")
                return False

        # Check if command is allowed for this client
        if 'restricted' in permissions:
            allowed_commands = ['python', 'python3', 'ls', 'pwd', 'echo']
            first_word = command.split()[0] if command.split() else ''
            if first_word not in allowed_commands:
                logger.warning(f"Command not allowed for restricted client: {first_word}")
                return False

        return True

    def execute_command_async(self, channel, command: str):
        """Execute command asynchronously with timeout"""
        try:
            import subprocess
            import json as json_module

            start_time = datetime.now()

            # Execute command
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30,
                encoding='utf-8',
                errors='replace'
            )

            execution_time = (datetime.now() - start_time).total_seconds()

            # Prepare JSON response
            response = {
                'success': result.returncode == 0,
                'stdout': result.stdout,
                'stderr': result.stderr,
                'returncode': result.returncode,
                'execution_time': execution_time,
                'timestamp': start_time.isoformat(),
                'client_id': self.client_id
            }

            # Send response
            channel.send(json_module.dumps(response).encode('utf-8') + b'\n')
            channel.send_exit_status(result.returncode)

        except subprocess.TimeoutExpired:
            response = {
                'success': False,
                'stdout': '',
                'stderr': 'Command timed out after 30 seconds',
                'timestamp': datetime.now().isoformat()
            }
            channel.send(json.dumps(response).encode('utf-8') + b'\n')
            channel.send_exit_status(-1)

        except Exception as e:
            response = {
                'success': False,
                'stdout': '',
                'stderr': f'Execution error: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }
            channel.send(json.dumps(response).encode('utf-8') + b'\n')
            channel.send_exit_status(-1)
        finally:
            channel.close()

class ModernSSHServerManager:
    """Manager for modern SSH server with enhanced features"""

    def __init__(self, host: str = '0.0.0.0', port: int = 2222,
                 host_key_path: str = 'host_key'):
        """
        Initialize SSH server manager

        Args:
            host: Host to bind to
            port: Port to listen on
            host_key_path: Path to host key file
        """
        self.host = host
        self.port = port
        self.host_key_path = Path(host_key_path)
        self.running = False
        self.server_socket = None
        self.client_threads = []

        # Load or generate configuration
        self.allowed_clients = self.load_client_config()
        self.generate_host_key_if_needed()

    def load_client_config(self) -> Dict[str, Dict[str, str]]:
        """Load client configuration from file"""
        config_path = Path.home() / '.raspberry_ssh' / 'clients.json'

        if config_path.exists():
            try:
                with open(config_path, 'r') as f:
                    return json.load(f)
            except Exception as e:
                logger.error(f"Failed to load client config: {e}")

        # Create default configuration
        default_config = {
            'android_app_1': {
                'username': 'android_user',
                'password': secrets.token_hex(16),
                'permissions': ['restricted']
            }
        }

        # Save default config
        config_path.parent.mkdir(parents=True, exist_ok=True)
        with open(config_path, 'w') as f:
            json.dump(default_config, f, indent=2)

        logger.info(f"Generated default client config at {config_path}")
        return default_config

    def generate_host_key_if_needed(self):
        """Generate RSA host key if it doesn't exist"""
        if not self.host_key_path.exists():
            logger.info(f"Generating new host key at {self.host_key_path}")
            key = paramiko.RSAKey.generate(2048)
            key.write_private_key_file(str(self.host_key_path))
            logger.info("Host key generated successfully")

    def handle_client(self, client_socket, addr, host_key):
        """Handle individual client connection"""
        transport = None
        try:
            # Create SSH transport
            transport = paramiko.Transport(client_socket)
            transport.add_server_key(host_key)

            # Create server instance
            server = ModernSSHServer(self.allowed_clients)
            server.client_ip = addr[0]

            # Start SSH server
            transport.start_server(server=server)

            # Wait for authentication
            channel = transport.accept(20)
            if channel is None:
                logger.warning(f"No channel opened for {addr[0]}")
                return

            # Wait for channel to close
            channel.recv_exit_status()

        except paramiko.SSHException as e:
            logger.error(f"SSH negotiation failed for {addr[0]}: {e}")
        except Exception as e:
            logger.error(f"Error handling client {addr[0]}: {e}")
        finally:
            if transport:
                transport.close()
            client_socket.close()

    def start(self):
        """Start the SSH server with modern thread management"""
        try:
            # Load host key
            host_key = paramiko.RSAKey(filename=str(self.host_key_path))

            # Create socket
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind((self.host, self.port))
            self.server_socket.listen(10)

            self.running = True
            logger.info(f"Modern SSH Server started on {self.host}:{self.port}")
            logger.info("Using thread-based approach (similar to ExecutorService)")

            while self.running:
                try:
                    client_socket, addr = self.server_socket.accept()
                    logger.info(f"Connection from {addr[0]}:{addr[1]}")

                    # Handle client in separate thread
                    client_thread = threading.Thread(
                        target=self.handle_client,
                        args=(client_socket, addr, host_key),
                        daemon=True
                    )
                    client_thread.start()

                    # Manage thread pool
                    self.client_threads.append(client_thread)
                    self.client_threads = [t for t in self.client_threads if t.is_alive()]

                    if len(self.client_threads) > 50:
                        logger.warning(f"High concurrent connections: {len(self.client_threads)}")

                except KeyboardInterrupt:
                    logger.info("Shutting down server...")
                    self.running = False
                    break
                except Exception as e:
                    logger.error(f"Error accepting connection: {e}")

        except Exception as e:
            logger.error(f"Failed to start SSH server: {e}")
        finally:
            self.stop()

    def stop(self):
        """Stop the SSH server gracefully"""
        logger.info("Stopping SSH server...")
        self.running = False

        # Clean up threads
        for thread in self.client_threads:
            if thread.is_alive():
                thread.join(timeout=5.0)

        if self.server_socket:
            self.server_socket.close()

        logger.info("SSH Server stopped")

