    Board::Board() : currentTurn(PieceColor::WHITE), gameOver(false), winner(PieceColor::NONE) {
        grid.resize(8, std::vector<std::shared_ptr<Piece>>(8));
        initializeBoard();
    }

    void Board::initializeBoard() {
        // Clear board
        for (int row = 0; row < 8; ++row) {
            for (int col = 0; col < 8; ++col) {
                grid[row][col] = std::make_shared<Piece>();
            }
        }

        // Setup black pieces
        grid[0][0] = std::make_shared<Piece>(PieceType::ROOK, PieceColor::BLACK, Position(0, 0));
        grid[0][1] = std::make_shared<Piece>(PieceType::KNIGHT, PieceColor::BLACK, Position(0, 1));
        grid[0][2] = std::make_shared<Piece>(PieceType::BISHOP, PieceColor::BLACK, Position(0, 2));
        grid[0][3] = std::make_shared<Piece>(PieceType::QUEEN, PieceColor::BLACK, Position(0, 3));
        grid[0][4] = std::make_shared<Piece>(PieceType::KING, PieceColor::BLACK, Position(0, 4));
        grid[0][5] = std::make_shared<Piece>(PieceType::BISHOP, PieceColor::BLACK, Position(0, 5));
        grid[0][6] = std::make_shared<Piece>(PieceType::KNIGHT, PieceColor::BLACK, Position(0, 6));
        grid[0][7] = std::make_shared<Piece>(PieceType::ROOK, PieceColor::BLACK, Position(0, 7));

        for (int col = 0; col < 8; ++col) {
            grid[1][col] = std::make_shared<Piece>(PieceType::PAWN, PieceColor::BLACK, Position(1, col));
        }

        // Setup white pieces
        grid[7][0] = std::make_shared<Piece>(PieceType::ROOK, PieceColor::WHITE, Position(7, 0));
        grid[7][1] = std::make_shared<Piece>(PieceType::KNIGHT, PieceColor::WHITE, Position(7, 1));
        grid[7][2] = std::make_shared<Piece>(PieceType::BISHOP, PieceColor::WHITE, Position(7, 2));
        grid[7][3] = std::make_shared<Piece>(PieceType::QUEEN, PieceColor::WHITE, Position(7, 3));
        grid[7][4] = std::make_shared<Piece>(PieceType::KING, PieceColor::WHITE, Position(7, 4));
        grid[7][5] = std::make_shared<Piece>(PieceType::BISHOP, PieceColor::WHITE, Position(7, 5));
        grid[7][6] = std::make_shared<Piece>(PieceType::KNIGHT, PieceColor::WHITE, Position(7, 6));
        grid[7][7] = std::make_shared<Piece>(PieceType::ROOK, PieceColor::WHITE, Position(7, 7));

        for (int col = 0; col < 8; ++col) {
            grid[6][col] = std::make_shared<Piece>(PieceType::PAWN, PieceColor::WHITE, Position(6, col));
        }
    }

    std::shared_ptr<Piece> Board::getPieceAt(Position pos) const {
        if (pos.row >= 0 && pos.row < 8 && pos.col >= 0 && pos.col < 8) {
            return grid[pos.row][pos.col];
        }
        return nullptr;
    }

    bool Board::movePiece(Position from, Position to) {
        auto piece = getPieceAt(from);
        if (!piece || piece->isEmpty() || piece->getColor() != currentTurn) {
            return false;
        }

        if (!isValidMove(from, to)) {
            return false;
        }

        // Move the piece
        grid[to.row][to.col] = piece;
        grid[from.row][from.col] = std::make_shared<Piece>();
        piece->setPosition(to);
        piece->setHasMoved(true);

        switchTurn();
        checkGameState();
        return true;
    }

    bool Board::isValidMove(Position from, Position to) const {
        auto moves = getValidMoves(from);
        return std::find(moves.begin(), moves.end(), to) != moves.end();
    }

    std::vector<Position> Board::getValidMoves(Position pos) const {
        auto piece = getPieceAt(pos);
        if (!piece || piece->isEmpty()) {
            return {};
        }

        switch (piece->getType()) {
            case PieceType::PAWN: return getPawnMoves(pos);
            case PieceType::ROOK: return getRookMoves(pos);
            case PieceType::KNIGHT: return getKnightMoves(pos);
            case PieceType::BISHOP: return getBishopMoves(pos);
            case PieceType::QUEEN: return getQueenMoves(pos);
            case PieceType::KING: return getKingMoves(pos);
            default: return {};
        }
    }

    void Board::switchTurn() {
        currentTurn = (currentTurn == PieceColor::WHITE) ? PieceColor::BLACK : PieceColor::WHITE;
    }

