    std::vector<Position> Board::getPawnMoves(Position pos) const {
        std::vector<Position> moves;
        auto piece = getPieceAt(pos);
        if (!piece) return moves;

        int direction = (piece->getColor() == PieceColor::WHITE) ? -1 : 1;
        int startRow = (piece->getColor() == PieceColor::WHITE) ? 6 : 1;

        // Move forward
        Position forward(pos.row + direction, pos.col);
        if (forward.row >= 0 && forward.row < 8 && getPieceAt(forward)->isEmpty()) {
            moves.push_back(forward);

            // Double move from starting position
            if (pos.row == startRow) {
                Position doubleForward(pos.row + 2 * direction, pos.col);
                if (getPieceAt(doubleForward)->isEmpty()) {
                    moves.push_back(doubleForward);
                }
            }
        }

        // Capture diagonally
        for (int colOffset : {-1, 1}) {
            Position capture(pos.row + direction, pos.col + colOffset);
            if (capture.row >= 0 && capture.row < 8 && capture.col >= 0 && capture.col < 8) {
                auto target = getPieceAt(capture);
                if (!target->isEmpty() && target->getColor() != piece->getColor()) {
                    moves.push_back(capture);
                }
            }
        }

        return moves;
    }

    std::vector<Position> Board::getRookMoves(Position pos) const {
        std::vector<Position> moves;
        auto piece = getPieceAt(pos);
        if (!piece) return moves;

        // Directions: up, down, left, right
        std::vector<std::pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (auto [dr, dc] : directions) {
            for (int i = 1; i < 8; ++i) {
                Position newPos(pos.row + dr * i, pos.col + dc * i);
                if (newPos.row < 0 || newPos.row >= 8 || newPos.col < 0 || newPos.col >= 8) {
                    break;
                }

                auto target = getPieceAt(newPos);
                if (target->isEmpty()) {
                    moves.push_back(newPos);
                } else {
                    if (target->getColor() != piece->getColor()) {
                        moves.push_back(newPos);
                    }
                    break;
                }
            }
        }

        return moves;
    }

    std::vector<Position> Board::getKnightMoves(Position pos) const {
        std::vector<Position> moves;
        auto piece = getPieceAt(pos);
        if (!piece) return moves;

        std::vector<std::pair<int, int>> knightMoves = {
            {-2, -1}, {-2, 1}, {-1, -2}, {-1, 2},
            {1, -2}, {1, 2}, {2, -1}, {2, 1}
        };

        for (auto [dr, dc] : knightMoves) {
            Position newPos(pos.row + dr, pos.col + dc);
            if (newPos.row >= 0 && newPos.row < 8 && newPos.col >= 0 && newPos.col < 8) {
                auto target = getPieceAt(newPos);
                if (target->isEmpty() || target->getColor() != piece->getColor()) {
                    moves.push_back(newPos);
                }
            }
        }

        return moves;
    }

    std::vector<Position> Board::getBishopMoves(Position pos) const {
        std::vector<Position> moves;
        auto piece = getPieceAt(pos);
        if (!piece) return moves;

        // Directions: diagonals
        std::vector<std::pair<int, int>> directions = {{-1, -1}, {-1, 1}, {1, -1}, {1, 1}};

        for (auto [dr, dc] : directions) {
            for (int i = 1; i < 8; ++i) {
                Position newPos(pos.row + dr * i, pos.col + dc * i);
                if (newPos.row < 0 || newPos.row >= 8 || newPos.col < 0 || newPos.col >= 8) {
                    break;
                }

                auto target = getPieceAt(newPos);
                if (target->isEmpty()) {
                    moves.push_back(newPos);
                } else {
                    if (target->getColor() != piece->getColor()) {
                        moves.push_back(newPos);
                    }
                    break;
                }
            }
        }

        return moves;
    }

    std::vector<Position> Board::getQueenMoves(Position pos) const {
        auto rookMoves = getRookMoves(pos);
        auto bishopMoves = getBishopMoves(pos);

        rookMoves.insert(rookMoves.end(), bishopMoves.begin(), bishopMoves.end());
        return rookMoves;
    }

    std::vector<Position> Board::getKingMoves(Position pos) const {
        std::vector<Position> moves;
        auto piece = getPieceAt(pos);
        if (!piece) return moves;

        for (int dr = -1; dr <= 1; ++dr) {
            for (int dc = -1; dc <= 1; ++dc) {
                if (dr == 0 && dc == 0) continue;

                Position newPos(pos.row + dr, pos.col + dc);
                if (newPos.row >= 0 && newPos.row < 8 && newPos.col >= 0 && newPos.col < 8) {
                    auto target = getPieceAt(newPos);
                    if (target->isEmpty() || target->getColor() != piece->getColor()) {
                        moves.push_back(newPos);
                    }
                }
            }
        }

        return moves;
    }
