    void ChessWindow::loadResources() {
        // Load font
        if (!mainFont.loadFromFile("resources/fonts/arial.ttf")) {
            std::cerr << "Failed to load font!" << std::endl;
        }

        // Load board texture
        if (!boardTexture.loadFromFile("resources/textures/board.png")) {
            std::cerr << "Failed to load board texture!" << std::endl;
            // Create procedural board as fallback
            boardTexture.create(560, 560); // 8 * 70
        }

        // Load pieces texture (sprite sheet)
        if (!piecesTexture.loadFromFile("resources/textures/pieces.png")) {
            std::cerr << "Failed to load pieces texture!" << std::endl;
        }

        // Setup board sprite
        boardSprite.setTexture(boardTexture);
        boardSprite.setPosition(BOARD_OFFSET_X, BOARD_OFFSET_Y);

        // Setup piece sprites (assuming 6x2 sprite sheet: 6 pieces × 2 colors)
        int pieceSize = 70;
        for (int i = 0; i < 6; ++i) {
            // White pieces
            sf::Sprite whiteSprite(piecesTexture);
            whiteSprite.setTextureRect(sf::IntRect(i * pieceSize, 0, pieceSize, pieceSize));

            // Black pieces
            sf::Sprite blackSprite(piecesTexture);
            blackSprite.setTextureRect(sf::IntRect(i * pieceSize, pieceSize, pieceSize, pieceSize));

            // Map to piece types
            PieceType types[] = {PieceType::PAWN, PieceType::ROOK, PieceType::KNIGHT,
                                PieceType::BISHOP, PieceType::QUEEN, PieceType::KING};

            pieceSprites[types[i]] = whiteSprite; // Store white version
            // Note: In full implementation, we'd store both colors
        }
    }

    void ChessWindow::createButtons() {
        int buttonWidth = 120;
        int buttonHeight = 40;
        int buttonY = 620;
        int buttonSpacing = 20;

        buttons.emplace_back(50, buttonY, buttonWidth, buttonHeight, "Start Game", mainFont);
        buttons.emplace_back(50 + buttonWidth + buttonSpacing, buttonY, buttonWidth, buttonHeight, "Settings", mainFont);
        buttons.emplace_back(50 + 2*(buttonWidth + buttonSpacing), buttonY, buttonWidth, buttonHeight, "Ratings", mainFont);
        buttons.emplace_back(50 + 3*(buttonWidth + buttonSpacing), buttonY, buttonWidth, buttonHeight, "Exit", mainFont);
