    void ChessWindow::drawBoard() {
        // Draw board background
        sf::RectangleShape boardBackground(sf::Vector2f(560, 560));
        boardBackground.setPosition(BOARD_OFFSET_X, BOARD_OFFSET_Y);
        boardBackground.setFillColor(sf::Color(50, 50, 50));
        window.draw(boardBackground);

        // Draw squares
        for (int row = 0; row < 8; ++row) {
            for (int col = 0; col < 8; ++col) {
                sf::RectangleShape square(sf::Vector2f(SQUARE_SIZE, SQUARE_SIZE));
                square.setPosition(
                    BOARD_OFFSET_X + col * SQUARE_SIZE,
                    BOARD_OFFSET_Y + row * SQUARE_SIZE
                );
                square.setFillColor((row + col) % 2 == 0 ? lightSquare : darkSquare);
                window.draw(square);
            }
        }

        // Draw selected piece highlight
        if (selectedPiece.row != -1) {
            sf::RectangleShape highlight(sf::Vector2f(SQUARE_SIZE, SQUARE_SIZE));
            highlight.setPosition(
                BOARD_OFFSET_X + selectedPiece.col * SQUARE_SIZE,
                BOARD_OFFSET_Y + selectedPiece.row * SQUARE_SIZE
            );
            highlight.setFillColor(highlightColor);
            window.draw(highlight);
        }
    }

    void ChessWindow::drawPieces() {
        for (int row = 0; row < 8; ++row) {
            for (int col = 0; col < 8; ++col) {
                auto piece = board->getPieceAt(Position(row, col));
                if (piece && !piece->isEmpty()) {
                    // Get appropriate sprite for piece type
                    auto sprite = pieceSprites[piece->getType()];
                    sprite.setPosition(
                        BOARD_OFFSET_X + col * SQUARE_SIZE,
                        BOARD_OFFSET_Y + row * SQUARE_SIZE
                    );

                    // Set color tint
                    if (piece->getColor() == PieceColor::BLACK) {
                        sprite.setColor(sf::Color(50, 50, 50));
                    }

                    window.draw(sprite);
                }
            }
        }
    }

    void ChessWindow::drawValidMoves() {
        for (const auto& move : validMoves) {
            sf::CircleShape indicator(SQUARE_SIZE / 4);
            indicator.setPosition(
                BOARD_OFFSET_X + move.col * SQUARE_SIZE + SQUARE_SIZE / 4,
                BOARD_OFFSET_Y + move.row * SQUARE_SIZE + SQUARE_SIZE / 4
            );
            indicator.setFillColor(sf::Color(0, 255, 0, 150));
            window.draw(indicator);
        }
    }

    void ChessWindow::run() {
        while (window.isOpen()) {
            handleEvents();
            update();
            render();
        }
    }

    void ChessWindow::handleEvents() {
        while (window.pollEvent(event)) {
            switch (event.type) {
                case sf::Event::Closed:
                    window.close();
                    break;

                case sf::Event::MouseButtonPressed:
                    if (event.mouseButton.button == sf::Mouse::Left) {
                        handleMouseClick(event.mouseButton.x, event.mouseButton.y);
                    }
                    break;

                case sf::Event::KeyPressed:
                    if (event.key.code == sf::Keyboard::Escape) {
                        if (showRatings) showRatings = false;
                        else if (settingsPanel.isVisible()) settingsPanel.setVisible(false);
                    }
                    break;

                case sf::Event::TextEntered:
                    if (settingsPanel.isVisible()) {
                        settingsPanel.handleTextInput(event.text.unicode);
                    }
                    break;

                default:
                    break;
            }
        }
    }

    void ChessWindow::handleMouseClick(int x, int y) {
        // Check if clicking on settings panel
        if (settingsPanel.isVisible()) {
            std::string result = settingsPanel.handleClick(x, y);
            if (result == "save") {
                // Save settings logic
            }
            return;
        }

        // Check if clicking on rating window
        if (showRatings) {
            if (!ratingWindow.contains(x, y)) {
                showRatings = false;
            }
            return;
        }

        // Check buttons
        for (const auto& button : buttons) {
            if (button.contains(x, y)) {
                handleButtonClick(button.getText());
                return;
            }
        }

        // Handle board clicks
        if (gameStarted && x >= BOARD_OFFSET_X && x < BOARD_OFFSET_X + 8 * SQUARE_SIZE &&
            y >= BOARD_OFFSET_Y && y < BOARD_OFFSET_Y + 8 * SQUARE_SIZE) {

            int col = (x - BOARD_OFFSET_X) / SQUARE_SIZE;
            int row = (y - BOARD_OFFSET_Y) / SQUARE_SIZE;

            Position clickedPos(row, col);

            if (selectedPiece.row != -1) {
                // Try to move piece
                if (board->movePiece(selectedPiece, clickedPos)) {
                    selectedPiece = Position(-1, -1);
                    validMoves.clear();
                } else {
                    // Select new piece
                    auto piece = board->getPieceAt(clickedPos);
                    if (piece && !piece->isEmpty() && 
                        piece->getColor() == board->getCurrentTurn()) {
                        selectedPiece = clickedPos;
                        validMoves = board->getValidMoves(clickedPos);
                    }
                }
            } else {
                // Select piece
                auto piece = board->getPieceAt(clickedPos);
                if (piece && !piece->isEmpty() && 
                    piece->getColor() == board->getCurrentTurn()) {
                    selectedPiece = clickedPos;
                    validMoves = board->getValidMoves(clickedPos);
                }
            }
        }
    }

    void ChessWindow::handleButtonClick(const std::string& buttonText) {
        if (buttonText == "Start Game") {
            startNewGame();
        } else if (buttonText == "Settings") {
            settingsPanel.setVisible(true);
        } else if (buttonText == "Ratings") {
            showRatings = true;
        } else if (buttonText == "Exit") {
            window.close();
        }
    }

    void ChessWindow::startNewGame() {
        board = std::make_unique<Board>();
        gameStarted = true;
        selectedPiece = Position(-1, -1);
        validMoves.clear();
    }
