    void ChessWindow::createButtons() {
        int buttonWidth = 120;
        int buttonHeight = 40;
        int buttonY = 620;
        int buttonSpacing = 20;

        // BUTTON FUNCTIONALITIES:
        // 1. "Start Game" - Resets board and begins new game
        buttons.emplace_back(50, buttonY, buttonWidth, buttonHeight, "Start Game", mainFont);

        // 2. "Settings" - Opens settings panel
        buttons.emplace_back(50 + buttonWidth + buttonSpacing, buttonY, buttonWidth, buttonHeight, "Settings", mainFont);

        // 3. "Player Rating" - Opens rating display window
        buttons.emplace_back(50 + 2*(buttonWidth + buttonSpacing), buttonY, buttonWidth, buttonHeight, "Ratings", mainFont);

        // 4. "Exit" - Closes application
        buttons.emplace_back(50 + 3*(buttonWidth + buttonSpacing), buttonY, buttonWidth, buttonHeight, "Exit", mainFont);
    }

    void ChessWindow::drawBoard() {
        // Draw 8x8 chess board with alternating colors
        for (int row = 0; row < 8; ++row) {
            for (int col = 0; col < 8; ++col) {
                sf::RectangleShape square(sf::Vector2f(SQUARE_SIZE, SQUARE_SIZE));
                square.setPosition(
                    BOARD_OFFSET_X + col * SQUARE_SIZE,
                    BOARD_OFFSET_Y + row * SQUARE_SIZE
                );
                square.setFillColor((row + col) % 2 == 0 ? 
                    sf::Color(240, 217, 181) : sf::Color(181, 136, 99));
                window.draw(square);
            }
        }
    }

    void ChessWindow::handleButtonClick(const std::string& buttonText) {
        if (buttonText == "Start Game") {
            startNewGame();
        } else if (buttonText == "Settings") {
            settingsPanel.setVisible(true);
        } else if (buttonText == "Ratings") {
            showRatings = true;
            ratingWindow.updateRatings(ratingManager.getAllRatings());
        } else if (buttonText == "Exit") {
            window.close();
        }
    }

    void ChessWindow::startNewGame() {
        board = std::make_unique<Board>();
        gameStarted = true;
        selectedPiece = Position(-1, -1);
        validMoves.clear();
    }
