// include/RatingSystem/RatingManager.h
#pragma once
#include <string>
#include <map>
#include <memory>
#include <mutex>
#include <fstream>
#include <sstream>
#include <iomanip>
#include <ctime>

namespace Chess {
    struct PlayerStats {
        int wins = 0;
        int losses = 0;
        int gamesPlayed = 0;
        double winRate = 0.0;
        std::string lastPlayed;

        std::string toString() const {
            std::stringstream ss;
            ss << std::fixed << std::setprecision(1);
            ss << "Wins: " << wins << " | Losses: " << losses 
               << " | Games: " << gamesPlayed << " | Win Rate: " << (winRate * 100) << "%";
            return ss.str();
        }
    };

    class RatingManager {
    private:
        static std::unique_ptr<RatingManager> instance;
        static std::once_flag initFlag;

        std::map<std::string, PlayerStats> ratings;
        std::string ratingsFile = "ratings.txt";
        mutable std::mutex ratingsMutex;

        RatingManager();
        void loadRatings();
        void saveRatings() const;

        std::string getCurrentTimestamp() const;

    public:
        RatingManager(const RatingManager&) = delete;
        RatingManager& operator=(const RatingManager&) = delete;

        static RatingManager& getInstance();

        void updateRating(const std::string& playerName, bool won);
        PlayerStats getPlayerStats(const std::string& playerName) const;
        std::map<std::string, PlayerStats> getAllRatings() const;

        std::vector<std::pair<std::string, PlayerStats>> getSortedRatings() const;
    };
}

// src/RatingSystem/RatingManager.cpp (partial)
#include "RatingSystem/RatingManager.h"
#include <algorithm>
#include <iostream>

namespace Chess {
    std::unique_ptr<RatingManager> RatingManager::instance = nullptr;
    std::once_flag RatingManager::initFlag;

    RatingManager::RatingManager() {
        loadRatings();
    }

    RatingManager& RatingManager::getInstance() {
        std::call_once(initFlag, []() {
            instance = std::unique_ptr<RatingManager>(new RatingManager());
        });
        return *instance;
    }

    void RatingManager::loadRatings() {
        std::lock_guard<std::mutex> lock(ratingsMutex);
        std::ifstream file(ratingsFile);

        if (!file.is_open()) {
            std::cout << "Creating new ratings file." << std::endl;
            return;
        }

        std::string line;
        while (std::getline(file, line)) {
            std::stringstream ss(line);
            std::string playerName;
            PlayerStats stats;

            if (std::getline(ss, playerName, '|')) {
                ss >> stats.wins >> stats.losses >> stats.gamesPlayed >> stats.winRate;
                std::getline(ss, stats.lastPlayed);
                ratings[playerName] = stats;
            }
        }
        file.close();
    }

    void RatingManager::saveRatings() const {
        std::lock_guard<std::mutex> lock(ratingsMutex);
        std::ofstream file(ratingsFile);

        if (!file.is_open()) {
            std::cerr << "Error: Could not open ratings file for writing." << std::endl;
            return;
        }

        for (const auto& [playerName, stats] : ratings) {
            file << playerName << "|"
                 << stats.wins << " "
                 << stats.losses << " "
                 << stats.gamesPlayed << " "
                 << stats.winRate << " "
                 << stats.lastPlayed << "\n";
        }
        file.close();
    }

    void RatingManager::updateRating(const std::string& playerName, bool won) {
        std::lock_guard<std::mutex> lock(ratingsMutex);

        PlayerStats& stats = ratings[playerName];
        stats.gamesPlayed++;

        if (won) {
            stats.wins++;
        } else {
            stats.losses++;
        }

        stats.winRate = static_cast<double>(stats.wins) / stats.gamesPlayed;
        stats.lastPlayed = getCurrentTimestamp();

        saveRatings();
    }
}
