#include "GUI/RatingWindow.h"
#include <sstream>
#include <iomanip>

namespace Chess {
    RatingWindow::RatingWindow(int x, int y, int width, int height, sf::Font& font)
        : font(font), visible(false), scrollOffset(0) {

        background.setPosition(x, y);
        background.setSize(sf::Vector2f(width, height));
        background.setFillColor(sf::Color(240, 240, 240));
        background.setOutlineThickness(3);
        background.setOutlineColor(sf::Color(50, 50, 50));

        title.setFont(font);
        title.setString("Player Ratings");
        title.setCharacterSize(24);
        title.setFillColor(sf::Color::Black);
        title.setPosition(x + 20, y + 20);
    }

    void RatingWindow::updateRatings(const std::map<std::string, PlayerStats>& newRatings) {
        ratings.clear();
        ratingTexts.clear();

        // Convert to vector and sort by win rate
        for (const auto& [name, stats] : newRatings) {
            ratings.emplace_back(name, stats);
        }

        std::sort(ratings.begin(), ratings.end(),
            [](const auto& a, const auto& b) {
                return a.second.winRate > b.second.winRate;
            });

        // Create text objects for display
        int yOffset = 70;
        for (size_t i = 0; i < ratings.size(); ++i) {
            const auto& [name, stats] = ratings[i];

            std::stringstream ss;
            ss << std::setw(2) << (i + 1) << ". "
               << std::setw(15) << std::left << name
               << " W:" << std::setw(3) << stats.wins
               << " L:" << std::setw(3) << stats.losses
               << " G:" << std::setw(3) << stats.gamesPlayed
               << " WR:" << std::setw(5) << std::fixed << std::setprecision(1) 
               << (stats.winRate * 100) << "%";

            sf::Text text;
            text.setFont(font);
            text.setString(ss.str());
            text.setCharacterSize(18);
            text.setFillColor(stats.winRate > 0.5 ? sf::Color::Green : sf::Color::Red);
            text.setPosition(background.getPosition().x + 20, 
                           background.getPosition().y + yOffset);

            ratingTexts.push_back(text);
            yOffset += 25;
        }
    }

    void RatingWindow::draw(sf::RenderWindow& window) {
        if (!visible) return;

        // Draw semi-transparent overlay
        sf::RectangleShape overlay(sf::Vector2f(window.getSize().x, window.getSize().y));
        overlay.setFillColor(sf::Color(0, 0, 0, 150));
        window.draw(overlay);

        // Draw window
        window.draw(background);
        window.draw(title);

        // Draw ratings with scroll offset
        int startIdx = scrollOffset;
        int endIdx = std::min(startIdx + 15, static_cast<int>(ratingTexts.size()));

        for (int i = startIdx; i < endIdx; ++i) {
            window.draw(ratingTexts[i]);
        }

        // Draw scroll indicator
        if (ratingTexts.size() > 15) {
            sf::Text scrollText;
            scrollText.setFont(font);
            scrollText.setString("Scroll with mouse wheel");
            scrollText.setCharacterSize(14);
            scrollText.setFillColor(sf::Color(100, 100, 100));
            scrollText.setPosition(background.getPosition().x + 20,
                                 background.getPosition().y + background.getSize().y - 30);
            window.draw(scrollText);
        }
    }
}
