            if (window.document.hasFocus()) {
                return true;
            }

            // Try to gain focus through user interaction simulation
            const focusAttempt = () => {
                const fakeBtn = document.createElement('button');
                fakeBtn.style.position = 'fixed';
                fakeBtn.style.top = '-100px';
                document.body.appendChild(fakeBtn);
                fakeBtn.focus();
                fakeBtn.remove();
            };

            try {
                focusAttempt();
            } catch (e) {
                console.log('Focus attempt failed:', e);
            }

            return window.document.hasFocus();
        }

        createNewTab(url) {
            const newTab = window.open(url, '_blank');
            if (newTab) {
                // Store new tab reference
                GM_setValue('secondTabId', this.tabId);
                return true;
            }
            return false;
        }
    }

    // Time management
    class TimeManager {
        static isWithinTimeRange() {
            const now = new Date();
            const hours = now.getHours();
            const minutes = now.getMinutes();
            const currentMinutes = hours * 60 + minutes;

            const startMinutes = CONFIG.TIME_RANGE.start.hour * 60 + CONFIG.TIME_RANGE.start.minute;
            const endMinutes = CONFIG.TIME_RANGE.end.hour * 60 + CONFIG.TIME_RANGE.end.minute;

            // Handle overnight range (22:30 to 03:30)
            if (hours >= 22 || hours < 3) {
                if (hours >= 22) {
                    return currentMinutes >= startMinutes;
                } else {
                    return currentMinutes <= endMinutes;
                }
            }
            return false;
        }

        static getTimeUntilStart() {
            const now = new Date();
            const target = new Date();
            target.setHours(CONFIG.TIME_RANGE.start.hour, 
                          CONFIG.TIME_RANGE.start.minute, 0, 0);

            if (now > target) {
                target.setDate(target.getDate() + 1);
            }

            return target - now;
        }
    }

    // Element finder with multiple strategies
    class ElementFinder {
        static findSubmitButton() {
            // Multiple selector strategies in order of preference
            const selectors = [
                // Exact match from instruction
                'input[type="submit"][id="submit"]',

                // Common variations
                'input#submit',
                '#submit',
                'button#submit',
                '[id="submit"]',

                // Form-related selectors
                'input[type="submit"]',
                'button[type="submit"]',
                'input[value*="رزرو"]',
                'input[value*="ثبت"]',
                'button:contains("رزرو")',
                'button:contains("ثبت")',

                // Generic fallbacks
                'form input[type="submit"]:last-child',
                'form button:last-child',
                '.submit-btn',
                '.reserve-btn'
            ];

            for (const selector of selectors) {
                try {
                    const element = document.querySelector(selector);
                    if (element && this.isVisible(element)) {
                        console.log('Found element with selector:', selector);
                        return element;
                    }
                } catch (e) {
                    console.log('Selector failed:', selector, e);
                }
            }

            // Last resort: find by text content
            const allElements = document.querySelectorAll('input, button, a, div');
            for (const element of allElements) {
                const text = element.textContent || element.value || '';
                if (text.includes('رزرو') || text.includes('ثبت') || 
                    text.includes('submit') || text.includes('Submit')) {
                    if (this.isVisible(element)) {
                        console.log('Found element by text:', text.substring(0, 50));
                        return element;
                    }
                }
            }

            return null;
        }

        static isVisible(element) {
            if (!element) return false;

            const style = window.getComputedStyle(element);
            return style.display !== 'none' && 
                   style.visibility !== 'hidden' && 
                   style.opacity !== '0' &&
                   element.offsetWidth > 0 &&
                   element.offsetHeight > 0;
        }

        static waitForElement(selector, timeout = CONFIG.MAX_WAIT_ELEMENT) {
            return new Promise((resolve) => {
                const startTime = Date.now();

                const check = () => {
                    const element = document.querySelector(selector);
                    if (element && this.isVisible(element)) {
                        resolve(element);
                        return;
                    }

                    if (Date.now() - startTime > timeout) {
                        resolve(null);
                        return;
                    }

                    setTimeout(check, 100);
                };

                check();
            });
        }
    }

    // Main controller
    class ReservationAutomation {
        constructor() {
            this.tabManager = new TabManager();
            this.state = {
                searchingText: true,
                switchedTabs: false,
                completed: false
            };

            this.init();
        }

        init() {
            // Only run in first tab
            if (!this.tabManager.isFirstTab) {
                console.log('Not first tab, stopping execution');
                return;
            }

            // Check if on main page
            if (!this.isMainPage()) {
                console.log('Not on main page, stopping execution');
                return;
            }

            this.start();
        }

        isMainPage() {
            const path = window.location.pathname;
            return path === '/' || path === '/index.html' || path === '';
        }

        async start() {
            console.log('Reservation automation started');

            // Step 1: Wait for correct time
            await this.waitForTime();

            // Step 2: Search for text and handle tabs
            await this.executeMainLogic();
        }

        async waitForTime() {
            while (!TimeManager.isWithinTimeRange()) {
                const waitTime = TimeManager.getTimeUntilStart();
                console.log(`Outside time range. Waiting ${Math.round(waitTime/1000/60)} minutes...`);

                // Check every minute
                await this.delay(60000);
            }

            console.log('Within time range (22:30-03:30). Proceeding...');
        }

        async executeMainLogic() {
            while (!this.state.completed) {
                if (this.state.searchingText) {
                    await this.handleTextSearch();
                } else if (!this.state.switchedTabs) {
                    await this.handleTabSwitch();
                } else {
                    await this.handleSecondTab();
                }

                // Small delay between cycles
                await this.delay(CONFIG.CHECK_INTERVAL);
            }
        }

        async handleTextSearch() {
            const pageText = document.body.innerText || document.body.textContent;

            if (pageText.includes(CONFIG.TARGET_TEXT)) {
                console.log('Target text found. Waiting 5 seconds...');
                await this.delay(5000);
                window.location.reload();
                return;
            }

            console.log('Target text not found. Proceeding to tab switch...');
            this.state.searchingText = false;
        }

        async handleTabSwitch() {
            console.log('Switching to second tab...');

            // Create new tab
            const success = this.tabManager.createNewTab(CONFIG.RESERVATION_URL);

            if (success) {
                console.log('Second tab created successfully');
                this.state.switchedTabs = true;

                // Wait for tab to load
                await this.delay(3000);

                // Try to bring second tab to front
                const secondTabId = GM_getValue('secondTabId');
                if (secondTabId) {
                    this.tabManager.sendCommand(secondTabId, 'switchToTab');
                }
            } else {
                console.log('Failed to create new tab. Retrying in 5 seconds...');
                await this.delay(5000);
            }
        }

        async handleSecondTab() {
            if (!this.tabManager.isSecondTab) {
                return;
            }

            console.log('In second tab. Looking for submit button...');

            // Wait for page to be fully loaded
            if (document.readyState !== 'complete') {
                await this.waitForPageLoad();
            }

            // Find and click submit button
            const submitButton = await ElementFinder.waitForElement('input, button, #submit', 10000);

            if (submitButton) {
                console.log('Submit button found. Clicking...');

                // Multiple click methods for reliability
                this.safeClick(submitButton);

                // Verify click was successful
                await this.delay(1000);

                console.log('Script completed successfully');
                this.state.completed = true;
            } else {
                console.log('Submit button not found. Retrying...');
                // Try alternative approach: search all elements
                const anyButton = ElementFinder.findSubmitButton();
                if (anyButton) {
                    this.safeClick(anyButton);
                    this.state.completed = true;
                }
            }
        }

        safeClick(element) {
            // Try multiple click methods
            const methods = [
                () => element.click(),
                () => element.dispatchEvent(new MouseEvent('click', { bubbles: true })),
                () => element.focus() && element.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter' })),
                () => {
                    const rect = element.getBoundingClientRect();
                    const clickEvent = new MouseEvent('click', {
                        clientX: rect.left + rect.width / 2,
                        clientY: rect.top + rect.height / 2,
                        bubbles: true
                    });
                    element.dispatchEvent(clickEvent);
                }
            ];

            for (const method of methods) {
                try {
                    method();
                    console.log('Click method succeeded');
                    break;
                } catch (e) {
                    console.log('Click method failed:', e.message);
                }
            }
        }

        async waitForPageLoad() {
            return new Promise((resolve) => {
                if (document.readyState === 'complete') {
                    resolve();
                    return;
                }

                window.addEventListener('load', resolve, { once: true });
                document.addEventListener('DOMContentLoaded', resolve, { once: true });

                // Fallback timeout
                setTimeout(resolve, 5000);
            });
        }

        delay(ms) {
            return new Promise(resolve => setTimeout(resolve, ms));
        }
    }

    // Initialize the automation
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            new ReservationAutomation();
        });
    } else {
        new ReservationAutomation();
    }

    // Utility functions
    function simulateCtrlTab() {
        // Alternative tab switching using keyboard simulation
        const event = new KeyboardEvent('keydown', {
            key: 'Tab',
            code: 'Tab',
            keyCode: 9,
            which: 9,
            ctrlKey: true,
            bubbles: true
        });

        document.dispatchEvent(event);

        // Also try alt+tab for some browsers
        setTimeout(() => {
            const altEvent = new KeyboardEvent('keydown', {
                key: 'Tab',
                code: 'Tab',
                keyCode: 9,
                which: 9,
                altKey: true,
                bubbles: true
            });
            document.dispatchEvent(altEvent);
        }, 100);
    }

})();
