    const totalPoints = apiData?.length || 0;
    const totalBatches = Math.ceil(totalPoints / BATCH_SIZE);

    Alert.alert(
      'Results Summary',
      `Total Points: ${totalPoints}\n` +
      `Batches Completed: ${completedPaths.length}\n` +
      `Total Drawing Time: ${calculateTotalDrawingTime()} seconds`,
      [{ text: 'OK' }]
    );
  };

  const calculateTotalDrawingTime = () => {
    if (completedPaths.length === 0) return 0;

    const firstPath = completedPaths[0];
    const lastPath = completedPaths[completedPaths.length - 1];

    return Math.round((lastPath.timestamp - firstPath.timestamp) / 1000);
  };

