    diagram.append("")
    diagram.append("Processing Order: RIGHT → LEFT (Last loader processes FIRST)")
    diagram.append("")

    # Show flow from right to left (processing order)
    for i, loader in enumerate(reversed(breakdown['loaders'])):
        position = len(breakdown['loaders']) - i
        arrow = "└──▶ " if i == len(breakdown['loaders']) - 1 else "├──▶ "

        line = f"{position:2d}. {arrow}{loader.get('name', loader['raw'][:40])}"
        if loader.get('processed_first'):
            line += " [PROCESSES FIRST]"

        diagram.append(line)

        if loader.get('purpose'):
            diagram.append(f"     Purpose: {loader['purpose']}")

        if loader.get('category'):
            diagram.append(f"     Category: {loader['category']}")

        if 'option_details' in loader:
            diagram.append("     Options:")
            for opt_key, opt_info in loader['option_details'].items():
                diagram.append(f"       • {opt_key}: {opt_info['value']}")
                diagram.append(f"         {opt_info['explanation']}")

        diagram.append("")

    diagram.append("=" * 80)
    diagram.append("FINAL RESULT: Vue component with styles injected into DOM")
    diagram.append("=" * 80)

