% =========================================================================
% 2-D SOURCE PANEL METHOD IMPLEMENTATION IN MATLAB
% =========================================================================
% This code implements the 2-D source panel method for potential flow
% analysis around arbitrary airfoils. The method uses constant strength
% source panels with a vortex to satisfy the Kutta condition.
%
% Features:
% 1. Reads airfoil coordinates from text file
% 2. Interactive user input for flow conditions
% 3. Convergence study with different panel numbers
% 4. Pressure coefficient calculation and plotting
% 5. Lift coefficient calculation using Kutta-Joukowski theorem
% 6. Comparison with thin airfoil theory
%
% File format for airfoil coordinates:
%   x1 y1
%   x2 y2
%   ...
%   xn yn
%
% =========================================================================

clear all; close all; clc;

%% MAIN FUNCTION
function main()
    fprintf('========================================\n');
    fprintf('    2-D SOURCE PANEL METHOD\n');
    fprintf('========================================\n\n');

    % Get airfoil geometry
    fprintf('AIRFOIL GEOMETRY INPUT:\n');
    fprintf('1. Use default NACA 0012 airfoil\n');
    fprintf('2. Load from text file\n');

    choice = input('Enter choice (1 or 2): ', 's');

    if strcmp(choice, '2')
        filename = input('Enter filename: ', 's');
        if ~exist(filename, 'file')
            fprintf('File not found. Using default airfoil.\n');
            [x_points, y_points] = create_default_airfoil();
        else
            [x_points, y_points] = load_airfoil_points(filename);
        end
    else
        [x_points, y_points] = create_default_airfoil();
    end

    % Get flow conditions
    fprintf('\n========================================\n');
    fprintf('        FLOW CONDITIONS\n');
    fprintf('========================================\n');

    V_inf = input('Enter free stream velocity (m/s): ');
    alpha_deg = input('Enter angle of attack (degrees): ');
    alpha_rad = deg2rad(alpha_deg);

    % Run convergence study
    fprintf('\n========================================\n');
    fprintf('      CONVERGENCE STUDY\n');
    fprintf('========================================\n');
    fprintf('Panel # |   Cl   | Error (%%)\n');
    fprintf('--------|--------|----------\n');

    panel_numbers = [10, 20, 40, 80, 160];
    Cl_values = zeros(size(panel_numbers));

    for i = 1:length(panel_numbers)
        n_panels = panel_numbers(i);

        % Create panels
        panels = create_panels(x_points, y_points, n_panels);

        % Solve flow
        [source_strengths, gamma] = solve_flow(panels, V_inf, alpha_rad);

        % Compute lift coefficient
        chord = max(x_points) - min(x_points);
        Cl = 2 * gamma / (V_inf * chord);
        Cl_values(i) = Cl;

        % Calculate error
        if i > 1
            error = abs((Cl - Cl_values(i-1)) / Cl_values(i-1)) * 100;
            fprintf('%7d | %6.4f | %7.2f\n', n_panels, Cl, error);
        else
            fprintf('%7d | %6.4f |     -\n', n_panels, Cl);
        end
    end

    % Use finest mesh for final results
    n_panels = 160;
    panels = create_panels(x_points, y_points, n_panels);
    [source_strengths, gamma] = solve_flow(panels, V_inf, alpha_rad);

    % Compute pressure coefficients
    Cp = compute_pressure_coefficient(panels, source_strengths, gamma, V_inf, alpha_rad);

    % Compute lift coefficient
    chord = max(x_points) - min(x_points);
    Cl = 2 * gamma / (V_inf * chord);

    % Compare with thin airfoil theory
    Cl_theory = 2 * pi * alpha_rad;

    % Display results
    fprintf('\n========================================\n');
    fprintf('         FINAL RESULTS\n');
    fprintf('========================================\n');
    fprintf('Lift Coefficient (Cl): %.6f\n', Cl);
    fprintf('Circulation (Gamma): %.6f\n', gamma);
    fprintf('\nTheoretical Cl (thin airfoil): %.6f\n', Cl_theory);
    fprintf('Percentage difference: %.2f%%\n', abs(Cl - Cl_theory)/Cl_theory*100);

    % Plot results
    plot_results(panels, x_points, y_points, Cp, V_inf, alpha_rad, source_strengths, gamma);
end

%% LOAD AIRFOIL POINTS FROM FILE
function [x_points, y_points] = load_airfoil_points(filename)
    try
        data = load(filename);
        x_points = data(:, 1);
        y_points = data(:, 2);
        fprintf('Loaded %d points from %s\n', length(x_points), filename);
    catch
        error('Error loading file. Please check file format and path.');
    end
end

%% CREATE DEFAULT AIRFOIL (NACA 0012)
function [x_points, y_points] = create_default_airfoil()
    n_points = 100;
    theta = linspace(0, 2*pi, n_points);
    x_points = 0.5 * (1 + cos(theta));
    y_points = 0.12 * sin(theta);
    fprintf('Using default NACA 0012 airfoil\n');
end

%% CREATE PANELS FROM AIRFOIL POINTS
function panels = create_panels(x_points, y_points, n_panels)
    % Resample points if needed
    if n_panels ~= length(x_points) - 1
        t_original = linspace(0, 1, length(x_points));
        t_new = linspace(0, 1, n_panels + 1);
        x_points = interp1(t_original, x_points, t_new);
        y_points = interp1(t_original, y_points, t_new);
    end

    % Initialize panels structure
    panels = struct('xa', {}, 'ya', {}, 'xb', {}, 'yb', {}, ...
                    'xc', {}, 'yc', {}, 'length', {}, 'theta', {});

    % Create panels
    for i = 1:n_panels
        panels(i).xa = x_points(i);
        panels(i).ya = y_points(i);
        panels(i).xb = x_points(i+1);
        panels(i).yb = y_points(i+1);
        panels(i).xc = (x_points(i) + x_points(i+1)) / 2;
        panels(i).yc = (y_points(i) + y_points(i+1)) / 2;
        panels(i).length = sqrt((x_points(i+1) - x_points(i))^2 + ...
                               (y_points(i+1) - y_points(i))^2);
        panels(i).theta = atan2(y_points(i+1) - y_points(i), ...
                               x_points(i+1) - x_points(i));
    end

    fprintf('Created %d panels\n', n_panels);
end

%% COMPUTE I INTEGRAL FOR SOURCE PANEL
function I = compute_I_integral(X, Y, L)
    if abs(Y) < 1e-12
        if X < 0
            I = 0;
        elseif X > L
            I = pi;
        else
            I = pi/2;
        end
    else
        term1 = (X - L) * atan2(Y, X - L) - X * atan2(Y, X);
        term2 = 0.5 * Y * log(((X - L)^2 + Y^2) / (X^2 + Y^2));
        I = term1 + term2;
    end
end

%% COMPUTE J INTEGRAL FOR VORTEX PANEL
function J = compute_J_integral(X, Y, L)
    if abs(Y) < 1e-12
        J = 0;
    else
        J = 0.5 * log(((X - L)^2 + Y^2) / (X^2 + Y^2));
    end
end

%% SOLVE FLOW FOR SOURCE STRENGTHS AND VORTEX STRENGTH
function [source_strengths, gamma] = solve_flow(panels, V_inf, alpha_rad)
    n_panels = length(panels);

    % Initialize matrices
    A = zeros(n_panels + 1, n_panels + 1);
    b = zeros(n_panels + 1, 1);

    % Compute influence coefficients
    for i = 1:n_panels
        for j = 1:n_panels
            if i == j
                A(i, j) = 0.5;
            else
                % Transform to panel j coordinates
                X = (panels(i).xc - panels(j).xa) * cos(panels(j).theta) + ...
                    (panels(i).yc - panels(j).ya) * sin(panels(j).theta);
                Y = -(panels(i).xc - panels(j).xa) * sin(panels(j).theta) + ...
                     (panels(i).yc - panels(j).ya) * cos(panels(j).theta);
                L = panels(j).length;

                % Compute influence coefficient
                I = compute_I_integral(X, Y, L);
                A(i, j) = I / (2 * pi);
            end
        end

        % Kutta condition column
        A(i, n_panels + 1) = 1.0;

        % RHS for boundary condition
        b(i) = -V_inf * cos(panels(i).theta - alpha_rad);
    end

    % Kutta condition row
    A(n_panels + 1, 1) = 1.0;
    A(n_panels + 1, n_panels) = 1.0;
    A(n_panels + 1, n_panels + 1) = 0.0;
    b(n_panels + 1) = 0.0;

    % Solve linear system
    q = A \ b;

    % Extract results
    source_strengths = q(1:n_panels);
    gamma = q(n_panels + 1);

    fprintf('Solved flow: Gamma = %.6f\n', gamma);
end

%% COMPUTE VELOCITY AT A POINT
function [u, v] = compute_velocity(x, y, panels, source_strengths, gamma, V_inf, alpha_rad)
    u = V_inf * cos(alpha_rad);
    v = V_inf * sin(alpha_rad);

    n_panels = length(panels);

    for j = 1:n_panels
        % Transform to panel j coordinates
        X = (x - panels(j).xa) * cos(panels(j).theta) + ...
            (y - panels(j).ya) * sin(panels(j).theta);
        Y = -(x - panels(j).xa) * sin(panels(j).theta) + ...
             (y - panels(j).ya) * cos(panels(j).theta);
        L = panels(j).length;

        % Compute integrals
        I = compute_I_integral(X, Y, L);
        J = compute_J_integral(X, Y, L);

        % Velocity in panel coordinates
        u_p = source_strengths(j) * I / (2 * pi);
        v_p = source_strengths(j) * J / (2 * pi) + gamma / (2 * pi);

        % Transform back to global coordinates
        u = u + u_p * cos(panels(j).theta) - v_p * sin(panels(j).theta);
        v = v + u_p * sin(panels(j).theta) + v_p * cos(panels(j).theta);
    end
end

%% COMPUTE PRESSURE COEFFICIENT ON EACH PANEL
function Cp = compute_pressure_coefficient(panels, source_strengths, gamma, V_inf, alpha_rad)
    n_panels = length(panels);
    Cp = zeros(n_panels, 1);

    for i = 1:n_panels
        % Compute velocity at control point
        [u, v] = compute_velocity(panels(i).xc, panels(i).yc, panels, ...
                                 source_strengths, gamma, V_inf, alpha_rad);

        % Tangential velocity
        V = u * cos(panels(i).theta) + v * sin(panels(i).theta);

        % Pressure coefficient
        Cp(i) = 1 - (V / V_inf)^2;
    end
end

%% PLOT RESULTS
function plot_results(panels, x_points, y_points, Cp, V_inf, alpha_rad, source_strengths, gamma)
    figure('Position', [100, 100, 1200, 900]);

    % Panel 1: Airfoil geometry
    subplot(2, 2, 1);
    plot(x_points, y_points, 'k-', 'LineWidth', 2);
    hold on;
    plot(x_points, y_points, 'ro', 'MarkerSize', 3);
    xlabel('x');
    ylabel('y');
    title('Airfoil Geometry');
    axis equal;
    grid on;

    % Panel 2: Pressure coefficient
    subplot(2, 2, 2);
    xc = [panels.xc];
    plot(xc, Cp, 'b-', 'LineWidth', 2);
    xlabel('x/c');
    ylabel('Cp');
    title('Pressure Coefficient Distribution');
    set(gca, 'YDir', 'reverse');
    grid on;

    % Panel 3: Comparison with thin airfoil theory
    subplot(2, 2, 3);
    theta = linspace(0, pi, length(panels));
    x_theory = 0.5 * (1 - cos(theta));
    Cp_theory = 1 - 4 * sin(theta).^2 .* (sin(alpha_rad)./sin(theta) + cos(alpha_rad)).^2;

    plot(x_theory, Cp_theory, 'r--', 'LineWidth', 2, 'DisplayName', 'Thin Airfoil Theory');
    hold on;
    plot(xc, Cp, 'b-', 'LineWidth', 1, 'DisplayName', 'Panel Method');
    xlabel('x/c');
    ylabel('Cp');
    title('Comparison with Analytical Solution');
    set(gca, 'YDir', 'reverse');
    grid on;
    legend('Location', 'best');

    % Panel 4: Streamlines
    subplot(2, 2, 4);
    x_min = min(x_points); x_max = max(x_points);
    y_min = min(y_points); y_max = max(y_points);

    [X, Y] = meshgrid(linspace(x_min-0.5, x_max+0.5, 30), ...
                      linspace(y_min-0.5, y_max+0.5, 30));

    U = zeros(size(X));
    V = zeros(size(Y));

    for i = 1:size(X, 1)
        for j = 1:size(X, 2)
            [u, v] = compute_velocity(X(i, j), Y(i, j), panels, ...
                                     source_strengths, gamma, V_inf, alpha_rad);
            U(i, j) = u;
            V(i, j) = v;
        end
    end

    startx = linspace(x_min-0.5, x_max+0.5, 15);
    starty = linspace(y_min-0.5, y_max+0.5, 15);
    [startx, starty] = meshgrid(startx, starty);

    streamline(X, Y, U, V, startx, starty);
    hold on;
    plot(x_points, y_points, 'k-', 'LineWidth', 2);
    xlabel('x');
    ylabel('y');
    title('Streamlines');
    axis equal;
    grid on;

    sgtitle(sprintf('2-D Source Panel Method Results (\\alpha = %.1f°)', rad2deg(alpha_rad)));
end

