function exp_data = load_experimental_file(filename)
    exp_data = struct();

    try
        if ~exist(filename, 'file')
            error('File not found.');
        end

        [~, ~, ext] = fileparts(filename);

        if strcmpi(ext, '.mat')
            % MATLAB format
            data = load(filename);
            exp_data.alpha = data.alpha_exp(:)';
            exp_data.Cl = data.Cl_exp(:)';

            if isfield(data, 'Cp_exp')
                exp_data.Cp = data.Cp_exp;
            end

        elseif strcmpi(ext, '.csv') || strcmpi(ext, '.txt')
            % CSV/TXT format
            data = csvread(filename);
            exp_data.alpha = data(:, 1)';
            exp_data.Cl = data(:, 2)';

            if size(data, 2) > 2
                exp_data.Cp = data(:, 3:end);
            end

        else
            error('Unsupported file format. Use .mat, .csv, or .txt.');
        end

        exp_data.source = filename;
        fprintf('✓ Loaded experimental data from %s\n', filename);

    catch ME
        fprintf('Error loading experimental data: %s\n', ME.message);
        fprintf('Proceeding without experimental comparison.\n');
        exp_data = struct();
    end
