class PhotoRepository @Inject constructor(
    private val apiService: PhotoApiService,
    private val photoDao: PhotoDao
) {
    suspend fun submitPhoto(photoData: PhotoSubmissionData): Result<SubmissionResult> {
        return try {
            val response = apiService.submitPhoto(photoData.toMultipart())
            if (response.isSuccessful) {
                Result.Success(response.body()!!)
            } else {
                Result.Error(Exception("Submission failed"))
            }
        } catch (e: Exception) {
            Result.Error(e)
        }
    }

    suspend fun searchPhotos(query: String, sortBy: String): Flow<List<Photo>> {
        return flow {
            // Try network first
            val response = apiService.searchPhotos(query, sortBy, "asc")
            if (response.isSuccessful) {
                emit(response.body()!!.results)
                // Cache to local database
                photoDao.insertAll(response.body()!!.results)
            } else {
                // Fallback to local cache
                emit(photoDao.searchPhotos("%$query%"))
            }
        }
    }
}
