    return determinant_recursive(minor_mat)


def determinant_recursive(matrix: List[List[float]]) -> float:
    """
    Recursive determinant calculation for small matrices.
    Optimized with Sarrus' rule for 3x3 and row selection.
    """
    n = len(matrix)

    # Base cases
    if n == 1:
        return matrix[0][0]
    if n == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    if n == 3:
        # Sarrus' rule (more efficient than recursion for 3x3)
        a, b, c = matrix[0]
        d, e, f = matrix[1]
        g, h, i = matrix[2]
        return (a*e*i + b*f*g + c*d*h) - (c*e*g + b*d*i + a*f*h)

    # For n > 3, use recursive cofactor expansion
    # Choose row with most zeros for efficiency
    best_row = 0
    max_zeros = 0
    for i in range(n):
        zeros = sum(1 for x in matrix[i] if abs(x) < 1e-12)
        if zeros > max_zeros:
            max_zeros = zeros
            best_row = i

    det = 0.0
    for j in range(n):
        if abs(matrix[best_row][j]) < 1e-12:
            continue  # Skip zero elements

        # Create minor matrix for element (best_row, j)
        minor_mat = []
        for i in range(n):
            if i == best_row:
                continue
            row = []
            for k in range(n):
                if k != j:
                    row.append(matrix[i][k])
            minor_mat.append(row)

        # Compute cofactor
        sign = 1 if (best_row + j) % 2 == 0 else -1
        det += sign * matrix[best_row][j] * determinant_recursive(minor_mat)

    return det


