    # Pre-allocate memory for minor matrix to avoid repeated allocations
    minor_size = n - 1
    minor_mat = [[0.0] * minor_size for _ in range(minor_size)]

    det = 0.0
    best_row_data = matrix[best_row]

    # Expand along the best row
    for j in range(n):
        element = best_row_data[j]
        if abs(element) < 1e-12:
            continue  # Skip zero elements

        # Build minor matrix efficiently with cache-friendly access
        minor_i = 0
        for i in range(n):
            if i == best_row:
                continue

            row_i = matrix[i]
            minor_j = 0
            for k in range(n):
                if k == j:
                    continue
                minor_mat[minor_i][minor_j] = row_i[k]
                minor_j += 1
            minor_i += 1

        # Compute cofactor
        sign = 1 if (best_row + j) % 2 == 0 else -1
        det += sign * element * determinant_optimized_recursive(minor_mat)

    return det


