% Trust Region Analysis for Rosenbrock Function
% f(x) = 10*(x2 - x1^2)^2 + (1 - x1)^2

clear all; close all; clc;

%% Define the Rosenbrock function and its derivatives
f = @(x) 10*(x(2) - x(1)^2)^2 + (1 - x(1))^2;

grad_f = @(x) [-40*x(1)*(x(2) - x(1)^2) - 2*(1 - x(1));
                20*(x(2) - x(1)^2)];

hess_f = @(x) [-40*(x(2) - x(1)^2) + 80*x(1)^2 + 2, -40*x(1);
                -40*x(1), 20];

%% Quadratic model function
quadratic_model = @(x, p, B) f(x) + grad_f(x)'*p + 0.5*p'*B*p;

%% Solve trust region subproblem using MATLAB's fmincon
function p_opt = solve_trust_region(x, B, delta)
    % Objective function: minimize m(p) = f(x) + grad_f(x)'*p + 0.5*p'*B*p
    grad = grad_f(x);
    obj_fun = @(p) grad'*p + 0.5*p'*B*p;

    % Initial guess
    p0 = [0; 0];

    % Trust region constraint: ||p|| <= delta
    nonlcon = @(p) trust_region_constraint(p, delta);

    % Bounds (optional, helps with convergence)
    lb = [-delta; -delta];
    ub = [delta; delta];

    % Solve using fmincon
    options = optimoptions('fmincon', 'Display', 'off', ...
                          'Algorithm', 'interior-point');
    p_opt = fmincon(obj_fun, p0, [], [], [], [], lb, ub, nonlcon, options);
end

function [c, ceq] = trust_region_constraint(p, delta)
