function cleanCustomerData(customer) {
    const cleaned = {};

    // Trim whitespace from all string fields
    for (const [key, value] of Object.entries(customer)) {
        if (typeof value === 'string') {
            cleaned[key] = value.trim();
        } else {
            cleaned[key] = value;
        }
    }

