/**
 * Process CSV chunk and insert into database
 * @param {Array} chunk - Array of customer objects
 * @param {string} tableName - Database table name
 * @returns {Promise<Object>} Processing results
 */
async function processChunk(chunk, tableName) {
    const client = await dbPool.connect();

    try {
        // Clean all customer data in the chunk
        const cleanedChunk = chunk.map(cleanCustomerData);

        // Prepare bulk insert query
        const columns = Object.keys(cleanedChunk[0]);
        const placeholders = cleanedChunk.map((_, rowIndex) => 
            `(${columns.map((_, colIndex) => `$${rowIndex * columns.length + colIndex + 1}`).join(', ')})`
        ).join(', ');

        const values = cleanedChunk.flatMap(row => 
            columns.map(col => row[col] || null)
        );

        const query = `
            INSERT INTO ${tableName} (${columns.join(', ')})
            VALUES ${placeholders}
            ON CONFLICT (email) DO UPDATE SET
                ${columns.map(col => `${col} = EXCLUDED.${col}`).join(', ')}
        `;

        await client.query(query, values);

        return {
            success: true,
            rowsProcessed: cleanedChunk.length,
            errors: [],
        };
    } catch (error) {
        console.error('Error processing chunk:', error);
        return {
            success: false,
            rowsProcessed: 0,
            errors: [error.message],
        };
    } finally {
        client.release();
    }
}

