        if (message.type === 'progress') {
            const progress = (message.data.processed / message.data.total) * 100;
            const job = jobStatus.get(jobId);
            if (job) {
                job.progress = Math.round(progress);
                jobStatus.set(jobId, job);
            }
        } else if (message.type === 'complete') {
            const job = jobStatus.get(jobId);
            if (job) {
                job.status = message.data.overallSuccess ? 'completed' : 'failed';
                job.endTime = new Date().toISOString();
                job.results = message.data;
                jobStatus.set(jobId, job);
            }
        }
    });

    worker.on('error', (error) => {
        console.error(`Worker error for job ${jobId}:`, error);
        const job = jobStatus.get(jobId);
        if (job) {
            job.status = 'failed';
            job.error = error.message;
            jobStatus.set(jobId, job);
        }
    });

    worker.on('exit', (code) => {
        if (code !== 0) {
            console.error(`Worker stopped with exit code ${code} for job ${jobId}`);
        }
    });

    return {
        success: true,
        data: {
            jobId,
            status: 'processing_started',
            message: 'CSV processing started in background',
            startTime: new Date().toISOString(),
            file: path.basename(filePath),
        },
        message: 'CSV processing started successfully',
    };
}

