import threading

class Ticket:
    def __init__(self, max_tickets=1000):
        self.MAX_TICKETS = max_tickets
        self._next = 0  # Avoids shadowing, similar to Java instance variable
        self.lock = threading.Lock()

    def get_ticket(self):
        """Java equivalent: public synchronized int getTicket()"""
        with self.lock:
            self._next = (self._next % self.MAX_TICKETS) + 1
            return self._next

class Counter:
    def __init__(self, max_tickets=1000):
        self.MAX_TICKETS = max_tickets
        self._serve = 1  # Avoids shadowing, similar to Java instance variable
        self.condition = threading.Condition()

    def serve_ticket(self, ticket):
        """
        Java equivalent: public synchronized void serveTicket(int ticket) throws InterruptedException

        Note: Python doesn't have checked exceptions like Java's InterruptedException,
        but we handle thread interruption through the Condition variable.
        """
        with self.condition:
            while ticket != self._serve:
                self.condition.wait()  # Similar to Java's wait()

            self._serve = (self._serve % self.MAX_TICKETS) + 1
            self.condition.notify_all()  # Similar to Java's notifyAll()

# Example usage demonstrating the corrected logic
if __name__ == "__main__":
    ticket_counter = Ticket(max_tickets=5)
    counter = Counter(max_tickets=5)

    def customer(customer_id):
        ticket = ticket_counter.get_ticket()
