        print(f"Customer {customer_id} with ticket {ticket} served!")

    # Create multiple threads to simulate concurrent customers
    threads = []
    for i in range(10):
        t = threading.Thread(target=customer, args=(i,))
        threads.append(t)
        t.start()

    for t in threads:
