const sharp = require('sharp');
const fs = require('fs').promises;
const path = require('path');

class WatermarkProcessor {
    /**
     * Initialize the watermark processor
     * @param {string} watermarkDir - Directory containing watermark images of different sizes
     */
    constructor(watermarkDir) {
        this.watermarkDir = watermarkDir;
        this.watermarkCache = new Map();
    }

    /**
     * Load the most appropriate watermark size for the target dimensions
     * @param {Object} targetSize - Target size {width, height}
     * @returns {Promise<Buffer|null>} Watermark buffer or null if no suitable watermark found
     */
    async _loadWatermark(targetSize) {
        try {
            // Get all watermark files
            const files = await fs.readdir(this.watermarkDir);
            const watermarkFiles = files.filter(f => 
                /\.(png|jpg|jpeg|webp)$/i.test(f)
            );

            if (watermarkFiles.length === 0) {
                console.warn('No watermark files found in directory');
                return null;
            }

            const targetArea = targetSize.width * targetSize.height;
            let bestWatermark = null;
            let bestSizeDiff = Infinity;

            for (const wmFile of watermarkFiles) {
                const wmPath = path.join(this.watermarkDir, wmFile);

                // Cache watermark metadata to avoid repeated loading
                if (!this.watermarkCache.has(wmPath)) {
                    try {
                        const metadata = await sharp(wmPath).metadata();
                        this.watermarkCache.set(wmPath, {
                            path: wmPath,
                            width: metadata.width,
                            height: metadata.height,
                            area: metadata.width * metadata.height
                        });
                    } catch (error) {
                        console.warn(`Failed to load watermark ${wmFile}:`, error.message);
                        continue;
                    }
                }

                const wmInfo = this.watermarkCache.get(wmPath);
                const wmArea = wmInfo.area;

                // Calculate size difference (prefer watermarks slightly smaller than target)
                const sizeDiff = Math.abs(wmArea - targetArea * 0.1); // Aim for ~10% of target area

                if (sizeDiff < bestSizeDiff) {
                    bestSizeDiff = sizeDiff;
                    bestWatermark = wmPath;
                }
            }

            return bestWatermark ? await fs.readFile(bestWatermark) : null;
        } catch (error) {
            console.error('Error loading watermark:', error);
            return null;
        }
    }

    /**
     * Detect how occupied each corner of the image is
     * @param {Buffer} imageBuffer - Input image buffer
     * @param {number} cornerRegion - Size of corner region to analyze (in pixels)
     * @returns {Promise<Array<number>>} Occupancy percentages for [top-left, top-right, bottom-left, bottom-right]
     */
    async _detectCornerOccupancy(imageBuffer, cornerRegion = 100) {
        try {
            // Get image metadata and extract corner regions
            const metadata = await sharp(imageBuffer).metadata();
            const { width, height } = metadata;

            // Define corner regions
            const corners = [
                { left: 0, top: 0, width: Math.min(cornerRegion, width), height: Math.min(cornerRegion, height) }, // Top-left
                { left: Math.max(0, width - cornerRegion), top: 0, width: Math.min(cornerRegion, width), height: Math.min(cornerRegion, height) }, // Top-right
                { left: 0, top: Math.max(0, height - cornerRegion), width: Math.min(cornerRegion, width), height: Math.min(cornerRegion, height) }, // Bottom-left
                { left: Math.max(0, width - cornerRegion), top: Math.max(0, height - cornerRegion), width: Math.min(cornerRegion, width), height: Math.min(cornerRegion, height) } // Bottom-right
            ];

            const occupancy = [];

            for (const corner of corners) {
                if (corner.width <= 0 || corner.height <= 0) {
                    occupancy.push(0);
                    continue;
                }

                // Extract corner region and convert to grayscale
                const cornerBuffer = await sharp(imageBuffer)
                    .extract(corner)
                    .grayscale()
                    .raw()
                    .toBuffer();

                // Calculate pixel intensity variance
                const pixels = new Uint8Array(cornerBuffer);
                const mean = pixels.reduce((sum, val) => sum + val, 0) / pixels.length;
                const variance = pixels.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) / pixels.length;

                // Calculate overall image variance for normalization
                const fullImageBuffer = await sharp(imageBuffer)
                    .grayscale()
                    .raw()
                    .toBuffer();
                const fullPixels = new Uint8Array(fullImageBuffer);
                const fullMean = fullPixels.reduce((sum, val) => sum + val, 0) / fullPixels.length;
                const fullVariance = fullPixels.reduce((sum, val) => sum + Math.pow(val - fullMean, 2), 0) / fullPixels.length;

                // Normalize occupancy percentage
                const occupancyPct = fullVariance > 0 
                    ? Math.min(100, (variance / fullVariance) * 100)
                    : 0;

                occupancy.push(occupancyPct);
            }

            return occupancy;
        } catch (error) {
            console.error('Error detecting corner occupancy:', error);
            return [0, 0, 0, 0]; // Default to all corners empty on error
        }
    }

    /**
     * Apply transparency to watermark
     * @param {Buffer} watermarkBuffer - Watermark image buffer
     * @param {number} opacity - Opacity level (0.0 = fully transparent, 1.0 = fully opaque)
     * @returns {Promise<Buffer>} Transparent watermark buffer
     */
    async _applyTransparency(watermarkBuffer, opacity = 0.7) {
        try {
            // Ensure opacity is within valid range
            const safeOpacity = Math.max(0, Math.min(1, opacity));

            // Apply opacity to the watermark
            return await sharp(watermarkBuffer)
                .ensureAlpha() // Ensure the image has an alpha channel
                .composite([{
                    input: Buffer.from([255, 255, 255, Math.round(255 * safeOpacity)]),
                    raw: { width: 1, height: 1, channels: 4 },
                    tile: true,
                    blend: 'dest-in'
                }])
                .toBuffer();
        } catch (error) {
            console.error('Error applying transparency:', error);
            return watermarkBuffer; // Return original if transparency fails
        }
    }

    /**
     * Add watermark to an image
     * @param {string} imagePath - Path to input image
     * @param {string} outputPath - Path to save watermarked image
     * @param {Object} options - Configuration options
     * @returns {Promise<boolean>} True if successful, false otherwise
     */
    async addWatermark(imagePath, outputPath, options = {}) {
        const {
            opacity = 0.7,
            margin = 20,
            minWatermarkRatio = 0.05,
            maxWatermarkRatio = 0.15,
            cornerRegion = 100
        } = options;

        try {
            // Load original image
            const originalBuffer = await fs.readFile(imagePath);
            const originalMetadata = await sharp(originalBuffer).metadata();

            // Get appropriate watermark
            const watermarkBuffer = await this._loadWatermark({
                width: originalMetadata.width,
                height: originalMetadata.height
            });

            if (!watermarkBuffer) {
                console.error(`No suitable watermark found for ${imagePath}`);
                return false;
            }

            // Apply transparency
            const transparentWatermark = await this._applyTransparency(watermarkBuffer, opacity);
            const watermarkMetadata = await sharp(transparentWatermark).metadata();

            // Detect best corner for placement
            const cornerOccupancy = await this._detectCornerOccupancy(originalBuffer, cornerRegion);
            const bestCornerIdx = cornerOccupancy.indexOf(Math.min(...cornerOccupancy));

            // Calculate watermark size with constraints
            const maxWmWidth = Math.floor(originalMetadata.width * maxWatermarkRatio);
            const maxWmHeight = Math.floor(originalMetadata.height * maxWatermarkRatio);
            const minWmWidth = Math.floor(originalMetadata.width * minWatermarkRatio);
            const minWmHeight = Math.floor(originalMetadata.height * minWatermarkRatio);

            // Calculate proportional resize
            const wmAspect = watermarkMetadata.width / watermarkMetadata.height;
            let newWidth, newHeight;

            if (watermarkMetadata.width > maxWmWidth) {
                newWidth = maxWmWidth;
                newHeight = Math.floor(newWidth / wmAspect);
            } else if (watermarkMetadata.height > maxWmHeight) {
                newHeight = maxWmHeight;
                newWidth = Math.floor(newHeight * wmAspect);
            } else {
                newWidth = watermarkMetadata.width;
                newHeight = watermarkMetadata.height;
            }

            // Ensure minimum size
            if (newWidth < minWmWidth) {
                newWidth = minWmWidth;
                newHeight = Math.floor(newWidth / wmAspect);
            }
            if (newHeight < minWmHeight) {
                newHeight = minWmHeight;
                newWidth = Math.floor(newHeight * wmAspect);
            }

            // Resize watermark
            const resizedWatermark = await sharp(transparentWatermark)
                .resize(newWidth, newHeight, { fit: 'fill' })
                .toBuffer();

            // Calculate position based on selected corner
            const positions = [
                { left: margin, top: margin }, // Top-left
                { left: originalMetadata.width - newWidth - margin, top: margin }, // Top-right
                { left: margin, top: originalMetadata.height - newHeight - margin }, // Bottom-left
                { left: originalMetadata.width - newWidth - margin, top: originalMetadata.height - newHeight - margin } // Bottom-right
            ];

            const position = positions[bestCornerIdx];

            // Apply watermark using composite
            await sharp(originalBuffer)
                .composite([{
                    input: resizedWatermark,
                    left: position.left,
                    top: position.top,
                    blend: 'over'
                }])
                .toFile(outputPath);

            console.log(`Watermark added successfully: ${outputPath}`);
            console.log(`Placed in corner: ${['top-left', 'top-right', 'bottom-left', 'bottom-right'][bestCornerIdx]}`);
            console.log(`Corner occupancy percentages: ${cornerOccupancy.map(p => p.toFixed(2))}`);

            return true;
        } catch (error) {
            console.error(`Error processing ${imagePath}:`, error.message);
            return false;
        }
    }
}

