#!/usr/bin/env python3
import re
import sys
from collections import defaultdict

def parse_gff3_for_exon_counts(gff_file_path):
    """
    Parse GFF3 file and count exons per gene.

    Args:
        gff_file_path (str): Path to GFF3 file

    Returns:
        dict: Gene ID to exon count mapping
    """
    gene_exon_counts = defaultdict(int)
    gene_parents = {}  # Track gene-to-parent relationships if needed

    try:
        with open(gff_file_path, 'r') as file:
            for line_num, line in enumerate(file, 1):
                # Skip comments and empty lines
                if line.startswith('#') or not line.strip():
                    continue

                # Split into columns
                columns = line.strip().split('\t')
                if len(columns) < 9:
                    continue

                seqid, source, feature_type, start, end, score, strand, phase, attributes = columns

                # Parse attributes into a dictionary
                attr_dict = {}
                for attr in attributes.split(';'):
                    if '=' in attr:
                        key, value = attr.split('=', 1)
                        attr_dict[key] = value

                # Handle gene features
                if feature_type == "gene":
                    gene_id = attr_dict.get('ID', '').replace('gene:', '')
                    if gene_id:
                        # Initialize exon count for this gene
                        if gene_id not in gene_exon_counts:
                            gene_exon_counts[gene_id] = 0

                # Handle exon features
                elif feature_type == "exon":
                    # Try to get parent gene from Parent attribute
                    parent = attr_dict.get('Parent', '')
                    if parent:
                        # Extract gene ID from Parent (could be gene:XXX or just XXX)
                        if 'gene:' in parent:
                            gene_id = parent.split('gene:')[-1]
                        else:
                            gene_id = parent

                        # Also check if there's a direct gene ID
                        if not gene_id and 'gene' in attr_dict:
                            gene_id = attr_dict['gene']

                        if gene_id:
                            gene_exon_counts[gene_id] += 1

    except FileNotFoundError:
        print(f"Error: File '{gff_file_path}' not found.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error processing file: {e}", file=sys.stderr)
        sys.exit(1)

    return dict(gene_exon_counts)

def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <gff3_file>", file=sys.stderr)
        sys.exit(1)

    gff_file = sys.argv[1]
    exon_counts = parse_gff3_for_exon_counts(gff_file)

    # Print results in the requested format
    for gene_id, count in sorted(exon_counts.items()):
        print(f"Gene: {gene_id}, Exon Count: {count}")

if __name__ == "__main__":
    main()
