class GFF3Validator:
    """Class for validating GFF3 file structure and content"""

    @staticmethod
    def validate_file_path(file_path: str) -> Tuple[bool, str]:
        """Comprehensive file path validation"""
        if not os.path.exists(file_path):
            return False, f"File not found: {file_path}"

        if not os.path.isfile(file_path):
            return False, f"Path is not a file: {file_path}"

        if not os.access(file_path, os.R_OK):
            return False, f"File is not readable: {file_path}"

        if os.path.getsize(file_path) == 0:
            return False, f"File is empty: {file_path}"

        return True, "File path validation passed"

    @staticmethod
    def validate_gff3_format(file_path: str, sample_size: int = 100) -> Tuple[bool, str]:
        """Validate GFF3 format by sampling file content"""
        try:
            opener = gzip.open if file_path.endswith('.gz') else open

            with opener(file_path, 'rt', encoding='utf-8') as f:
                lines_checked = 0
                valid_gff3_lines = 0

                for line in f:
                    lines_checked += 1
                    if lines_checked > sample_size:
                        break

                    # Skip comments and empty lines
                    if line.startswith('#') or not line.strip():
                        continue

                    # Check tab-separated columns
                    columns = line.strip().split('\t')

                    # GFF3 must have at least 9 columns
                    if len(columns) < 9:
                        return False, f"Line {lines_checked}: Expected 9 columns, found {len(columns)}"

                    # Validate column data types
                    try:
                        # Columns 4 and 5 should be integers (start, end positions)
                        start = int(columns[3])
                        end = int(columns[4])

                        if start < 1 or end < 1:
                            return False, f"Line {lines_checked}: Invalid coordinates ({start}, {end})"
                        if start > end:
                            return False, f"Line {lines_checked}: Start ({start}) > End ({end})"

                    except ValueError:
                        return False, f"Line {lines_checked}: Invalid coordinate format"

                    # Check feature type (column 3)
                    feature_type = columns[2]
                    if not feature_type:
                        return False, f"Line {lines_checked}: Empty feature type"

                    valid_gff3_lines += 1

                if valid_gff3_lines == 0:
                    return False, "No valid GFF3 feature lines found in sample"

                return True, f"GFF3 format validation passed ({valid_gff3_lines} valid lines sampled)"

        except UnicodeDecodeError:
            return False, "File encoding error - not valid UTF-8 text"
        except Exception as e:
            return False, f"Error reading file: {str(e)}"

class GFF3Parser:
    """Optimized GFF3 parser with performance enhancements"""

    # Precompiled regex patterns for performance
    GENE_ID_PATTERN = re.compile(r'ID=gene:([^;]+)')
    PARENT_GENE_PATTERN = re.compile(r'Parent=gene:([^;]+)')
    GENE_ATTR_PATTERN = re.compile(r'gene=([^;]+)')
    ID_PATTERN = re.compile(r'ID=([^;]+)')
    PARENT_PATTERN = re.compile(r'Parent=([^;]+)')

    @staticmethod
    def parse_attributes_fast(attributes_str: str) -> Dict[str, str]:
        """Fast attribute parsing using split instead of regex when possible"""
        if not attributes_str or attributes_str == '.':
            return {}

        attrs = {}
        for attr in attributes_str.split(';'):
            attr = attr.strip()
            if not attr:
                continue

            if '=' in attr:
                key, value = attr.split('=', 1)
                attrs[key.strip()] = value.strip()
            else:
                attrs[attr] = True

        return attrs

    @staticmethod
    def extract_gene_id_fast(attributes: Dict[str, str]) -> Optional[str]:
        """Fast gene ID extraction with multiple fallback strategies"""
        # Strategy 1: ID=gene:XXX
        if 'ID' in attributes:
            id_value = attributes['ID']
            if id_value.startswith('gene:'):
                return id_value[5:]
            return id_value

        # Strategy 2: gene=XXX
        if 'gene' in attributes:
            return attributes['gene']

        # Strategy 3: Name attribute
        if 'Name' in attributes:
            return attributes['Name']

        return None

    @staticmethod
    def extract_parent_gene_fast(attributes: Dict[str, str]) -> Optional[str]:
        """Fast parent gene extraction"""
        if 'Parent' in attributes:
            parent = attributes['Parent']
            if parent.startswith('gene:'):
                return parent[5:]
            return parent

