        exon_counts = defaultdict(int)
        gene_registry = set()
        current_gene = None

        # Step 3: Process file with performance optimizations
        try:
            opener = gzip.open if gff_file_path.endswith('.gz') else open

            with opener(gff_file_path, 'rt', encoding='utf-8') as file:
                # Use enumerate for line numbers and batch processing
                batch_size = 10000
                line_buffer = []

                for line_num, line in enumerate(file, 1):
                    self.stats['total_lines'] += 1

                    # Skip comments and empty lines early
                    if line.startswith('#') or not line.strip():
                        self.stats['skipped_lines'] += 1
                        continue

                    # Batch processing for performance
                    line_buffer.append((line_num, line))

                    if len(line_buffer) >= batch_size:
                        self._process_batch(line_buffer, exon_counts, gene_registry, current_gene)
                        line_buffer = []

                        if self.verbose and line_num % 100000 == 0:
                            print(f"Processed {line_num:,} lines...", file=sys.stderr)

                # Process remaining lines
                if line_buffer:
                    self._process_batch(line_buffer, exon_counts, gene_registry, current_gene)

        except Exception as e:
            print(f"Error processing file: {str(e)}", file=sys.stderr)
            return {}

        # Step 4: Calculate statistics
        self.stats['processing_time'] = time.time() - start_time
        self.stats['genes_with_exons'] = len([c for c in exon_counts.values() if c > 0])

        if self.verbose:
            self._print_statistics()

        return dict(exon_counts)

    def _process_batch(self, batch: List[Tuple[int, str]], 
                      exon_counts: Dict[str, int],
                      gene_registry: set,
                      current_gene: Optional[str]) -> Optional[str]:
        """Process a batch of lines for better performance"""
        local_current_gene = current_gene

        for line_num, line in batch:
            # Split line efficiently
            columns = line.strip().split('\t', 9)  # Split into max 9 parts
            if len(columns) < 9:
                self.stats['skipped_lines'] += 1
                continue

            feature_type = columns[2]
            attributes_str = columns[8]

            # Fast attribute parsing
            attributes = GFF3Parser.parse_attributes_fast(attributes_str)

            # Process gene features
            if feature_type.lower() == "gene":
                self.stats['gene_lines'] += 1
                gene_id = GFF3Parser.extract_gene_id_fast(attributes)

                if gene_id:
                    local_current_gene = gene_id
                    gene_registry.add(gene_id)

                    # Initialize counter if not present
                    if gene_id not in exon_counts:
                        exon_counts[gene_id] = 0

            # Process exon features
            elif feature_type.lower() == "exon":
                self.stats['exon_lines'] += 1

                # Try parent gene first
                parent_gene = GFF3Parser.extract_parent_gene_fast(attributes)

                if parent_gene:
                    exon_counts[parent_gene] += 1
                    gene_registry.add(parent_gene)
                elif local_current_gene:
                    # Fallback to current gene context
                    exon_counts[local_current_gene] += 1
                else:
                    # Try direct gene extraction
                    gene_id = GFF3Parser.extract_gene_id_fast(attributes)
                    if gene_id:
                        exon_counts[gene_id] += 1
                        gene_registry.add(gene_id)
                    else:
                        self.stats['orphan_exons'] += 1

        return local_current_gene

