How would I go about processing the degraded image `y` in MATLAB code, in order to achieve a restored image as close to the original image `im`

Looking at your MATLAB code, you're adding a large constant value (`nn = 1e6`) to four specific frequency components in the Fourier domain, which creates strong periodic noise in the spatial domain. This simulates a degradation with specific frequency interference.

To restore the image in MATLAB, we need to identify and remove these corrupted frequency components. Here's a MATLAB implementation:

```matlab
function restored = restore_degraded_image_matlab(y, corrupted_indices, detection_threshold)
% RESTORE_DEGRADED_IMAGE_MATLAB Restore image degraded by frequency interference
%
% Inputs:
%   y - Degraded image (spatial domain)
%   corrupted_indices - Optional: Known indices of corrupted frequencies
%                       as cell array: {{row1, col1}, {row2, col2}, ...}
%   detection_threshold - Optional: Threshold for automatic detection
%
% Output:
%   restored - Restored image

% Convert to double for processing
y_double = im2double(y);

% Compute 2D Fourier Transform
Y = fft2(y_double);
Y_shifted = fftshift(Y);  % Shift zero frequency to center

% Get magnitude spectrum
magnitude = abs(Y_shifted);

% If corrupted indices not provided, detect them automatically
if nargin < 2 || isempty(corrupted_indices)
    if nargin < 3 || isempty(detection_threshold)
        % Use threshold based on median magnitude
        median_mag = median(magnitude(:));
        detection_threshold = 10 * median_mag;
    end

    % Find peaks above threshold
    [rows, cols] = find(magnitude > detection_threshold);
    corrupted_indices = cell(length(rows), 1);
    for i = 1:length(rows)
        corrupted_indices{i} = {rows(i), cols(i)};
    end

    % Filter out DC component (center of spectrum)
    center = floor(size(magnitude) / 2) + 1;  % MATLAB is 1-indexed
    valid_idx = true(length(rows), 1);
    for i = 1:length(rows)
        if abs(rows(i) - center(1)) < 2 && abs(cols(i) - center(2)) < 2
            valid_idx(i) = false;
        end
    end
    corrupted_indices = corrupted_indices(valid_idx);
end

% Create copy for restoration
Y_restored = Y_shifted;

% Apply restoration: zero out corrupted frequencies
for i = 1:length(corrupted_indices)
    idx = corrupted_indices{i};
    r = idx{1};
    c = idx{2};

    % Zero out the corrupted frequency
    Y_restored(r, c) = 0;

    % Also zero the symmetric frequency (due to real image symmetry)
    sym_r = size(Y_restored, 1) - r + 1;
    sym_c = size(Y_restored, 2) - c + 1;
    Y_restored(sym_r, sym_c) = 0;
end

% Inverse shift and transform back to spatial domain
Y_restored_unshifted = ifftshift(Y_restored);
restored_complex = ifft2(Y_restored_unshifted);

% Take real part (imaginary part should be near zero)
restored = real(restored_complex);

% Clip to valid range [0, 1]
restored = max(0, min(1, restored));

% Display detected corrupted frequencies
fprintf('Detected %d corrupted frequency components\n', length(corrupted_indices));
if length(corrupted_indices) <= 10
    fprintf('Corrupted indices:\n');
    for i = 1:length(corrupted_indices)
        idx = corrupted_indices{i};
        fprintf('  (%d, %d)\n', idx{1}, idx{2});
    end
else
    fprintf('First 10 corrupted indices:\n');
    for i = 1:min(10, length(corrupted_indices))
        idx = corrupted_indices{i};
        fprintf('  (%d, %d)\n', idx{1}, idx{2});
    end
end
end

