function restored = notch_filter_restoration(y, notch_positions)
    % NOTCH_FILTER_RESTORATION Restore image using frequency notch filtering
    %
    % Inputs:
    %   y - Degraded image
    %   notch_positions - Nx2 matrix of [row, col] positions to notch
    %
    % Output:
    %   restored - Restored image

    y_double = im2double(y);
    [M, N] = size(y_double);

    % Compute Fourier Transform
    Y = fft2(y_double);
    Y_shifted = fftshift(Y);

    % Create notch filter
    H = ones(M, N);

    % Apply notches at specified positions
    for i = 1:size(notch_positions, 1)
        r = notch_positions(i, 1);
        c = notch_positions(i, 2);

        % Create 3x3 notch around the frequency
        H(r-1:r+1, c-1:c+1) = 0;

        % Also notch symmetric frequency
        sym_r = M - r + 1;
        sym_c = N - c + 1;
        H(sym_r-1:sym_r+1, sym_c-1:sym_c+1) = 0;
    end

    % Apply filter
    Y_filtered = Y_shifted .* H;
    Y_filtered_unshifted = ifftshift(Y_filtered);
    restored_complex = ifft2(Y_filtered_unshifted);
    restored = real(restored_complex);
    restored = max(0, min(1, restored));
end

