function restored = lucy_richardson_fourier(y, psf, iterations, damping)
    % LUCY_RICHARDSON_FOURIER Lucy-Richardson deconvolution adapted for Fourier artifacts
    %
    % Inputs:
    %   y - Degraded image
    %   psf - Point Spread Function (degradation kernel)
    %   iterations - Number of iterations
    %   damping - Damping parameter (optional)
    %
    % Output:
    %   restored - Restored image

    if nargin < 4
        damping = 0;
    end

    y_double = im2double(y);

    % If no PSF provided, create one that approximates frequency interference
    if nargin < 2 || isempty(psf)
        % Create a PSF that represents the effect of frequency domain corruption
        psf_size = 7;
        psf = zeros(psf_size);
        psf(psf_size/2, psf_size/2) = 1;

        % Add off-center components to simulate frequency interference
        psf(1, 1) = 0.05;
        psf(end, end) = 0.05;
        psf(1, end) = 0.05;
        psf(end, 1) = 0.05;

        psf = psf / sum(psf(:));
    end

    % Initialize estimate
    est = y_double;

    % Create OTF (Optical Transfer Function) in frequency domain
    otf = psf2otf(psf, size(y_double));

    for iter = 1:iterations
        % Compute current estimate in frequency domain
        est_fft = fft2(est);

        % Apply degradation model
        blurred_est_fft = est_fft .* otf;
        blurred_est = real(ifft2(blurred_est_fft));

        % Compute ratio
        ratio = y_double ./ (blurred_est + eps);
        ratio_fft = fft2(ratio);

        % Update estimate
        correction = real(ifft2(ratio_fft .* conj(otf)));

        % Apply damping if specified
        if damping > 0
            est = est .* (1 - damping) + est .* correction * damping;
        else
            est = est .* correction;
        end

        % Non-negativity constraint
        est = max(0, est);

        % Display progress every 10 iterations
        if mod(iter, 10) == 0
            fprintf('Iteration %d/%d\n', iter, iterations);
        end
    end

    restored = est;
    restored = max(0, min(1, restored));
end

