function restored = hybrid_restoration(y, method_sequence)
    % HYBRID_RESTORATION Combine multiple restoration techniques
    %
    % Inputs:
    %   y - Degraded image
    %   method_sequence - Cell array of method names and parameters
    %
    % Output:
    %   restored - Restored image

    current = im2double(y);

    for i = 1:length(method_sequence)
        method = method_sequence{i};

        switch method{1}
            case 'notch'
                % Frequency notch filtering
                notch_positions = method{2};
                current = notch_filter_restoration(current, notch_positions);

            case 'wiener'
                % Wiener filtering
                if length(method) > 1
                    noise_var = method{2};
                    signal_var = method{3};
                    current = wiener_fourier_restoration(current, noise_var, signal_var);
                else
                    current = wiener_fourier_restoration(current);
                end

            case 'lucy_richardson'
                % Lucy-Richardson deconvolution
                if length(method) > 1
                    psf = method{2};
                    iterations = method{3};
                    damping = method{4};
                    current = lucy_richardson_fourier(current, psf, iterations, damping);
                else
                    current = lucy_richardson_fourier(current);
                end

            case 'median'
                % Median filtering for residual noise
                filter_size = method{2};
                current = medfilt2(current, [filter_size filter_size]);
        end
    end

    restored = current;
