function [restored, H, metrics] = notch_filter_tuning(y, original, varargin)
    % NOTCH_FILTER_TUNING Notch filter restoration with parameter tuning
    %
    % Inputs:
    %   y - Degraded image
    %   original - Original image (for metrics)
    %   varargin - Parameter pairs: 'NotchSize', 'Threshold', 'Positions'
    %
    % Outputs:
    %   restored - Restored image
    %   H - Notch filter used
    %   metrics - Performance metrics

    % Parse input parameters
    p = inputParser;
    addParameter(p, 'NotchSize', 3, @(x) isscalar(x) && mod(x,2)==1);
    addParameter(p, 'Threshold', 10, @isscalar);
    addParameter(p, 'Positions', [], @(x) ismatrix(x) || isempty(x));
    parse(p, varargin{:});

    notch_size = p.Results.NotchSize;
    threshold_mult = p.Results.Threshold;
    positions = p.Results.Positions;

    y_double = im2double(y);
    [M, N] = size(y_double);

    % Compute Fourier Transform
    Y = fft2(y_double);
    Y_shifted = fftshift(Y);

    % Create notch filter
    H = ones(M, N);

    if isempty(positions)
        % Auto-detect corrupted frequencies
        magnitude = abs(Y_shifted);
        median_mag = median(magnitude(:));
        threshold = threshold_mult * median_mag;

        % Find peaks
        [rows, cols] = find(magnitude > threshold);

        % Filter out DC component
        center = floor([M, N] / 2) + 1;
        valid_idx = ~(abs(rows - center(1)) < 2 & abs(cols - center(2)) < 2);
        rows = rows(valid_idx);
        cols = cols(valid_idx);

        positions = [rows, cols];
    end

    % Apply notches
    half_size = floor(notch_size / 2);
    for i = 1:size(positions, 1)
        r = positions(i, 1);
        c = positions(i, 2);

        % Create notch around frequency
        r_start = max(1, r - half_size);
        r_end = min(M, r + half_size);
        c_start = max(1, c - half_size);
        c_end = min(N, c + half_size);

        H(r_start:r_end, c_start:c_end) = 0;

        % Also notch symmetric frequency
        sym_r = M - r + 1;
        sym_c = N - c + 1;

        r_start = max(1, sym_r - half_size);
        r_end = min(M, sym_r + half_size);
        c_start = max(1, sym_c - half_size);
        c_end = min(N, sym_c + half_size);

        H(r_start:r_end, c_start:c_end) = 0;
    end

    % Apply filter
    Y_filtered = Y_shifted .* H;
    Y_filtered_unshifted = ifftshift(Y_filtered);
    restored_complex = ifft2(Y_filtered_unshifted);
    restored = real(restored_complex);
    restored = max(0, min(1, restored));

    % Calculate metrics if original is provided
    if nargin >= 2 && ~isempty(original)
        metrics = calculate_metrics(original, restored, y);
    else
        metrics = [];
    end
end

