    %   original - Original image (for metrics)
    %   varargin - Parameter pairs: 'Iterations', 'PSF', 'Damping'
    %
    % Outputs:
    %   restored - Restored image
    %   metrics - Performance metrics

    % Parse input parameters
    p = inputParser;
    addParameter(p, 'Iterations', 30, @isscalar);
    addParameter(p, 'PSF', [], @(x) ismatrix(x) || isempty(x));
    addParameter(p, 'Damping', 0, @isscalar);
    parse(p, varargin{:});

    iterations = p.Results.Iterations;
    psf = p.Results.PSF;
    damping = p.Results.Damping;

    y_double = im2double(y);

    % Create PSF if not provided
    if isempty(psf)
        % Create a PSF that approximates frequency domain corruption
        psf_size = 5;
        psf = zeros(psf_size);
        psf(ceil(psf_size/2), ceil(psf_size/2)) = 1;

        % Add components to simulate frequency interference
        psf(1, 1) = 0.1;
        psf(end, end) = 0.1;
        psf(1, end) = 0.1;
        psf(end, 1) = 0.1;

        psf = psf / sum(psf(:));
    end

    % Use MATLAB's built-in Lucy-Richardson deconvolution
    if damping == 0
        restored = deconvlucy(y_double, psf, iterations);
    else
        % Manual implementation with damping
        est = y_double;
        otf = psf2otf(psf, size(y_double));

        for iter = 1:iterations
            % Compute current estimate
            est_fft = fft2(est);
            blurred_est_fft = est_fft .* otf;
            blurred_est = real(ifft2(blurred_est_fft));

            % Compute ratio
            ratio = y_double ./ (blurred_est + eps);
            ratio_fft = fft2(ratio);

            % Update estimate with damping
            correction = real(ifft2(ratio_fft .* conj(otf)));
            est = est .* (1 - damping) + est .* correction * damping;

            % Non-negativity constraint
            est = max(0, est);
        end

        restored = est;
    end

    % Clip to valid range
    restored = max(0, min(1, restored));

    % Calculate metrics if original is provided
    if nargin >= 2 && ~isempty(original)
        metrics = calculate_metrics(original, restored, y);
    else
        metrics = [];
    end
end

