function metrics = calculate_metrics(original, restored, degraded)
    % CALCULATE_METRICS Calculate restoration performance metrics
    %
    % Inputs:
    %   original - Original image
    %   restored - Restored image
    %   degraded - Degraded image
    %
    % Outputs:
    %   metrics - Structure containing all metrics

    % Ensure images are in double format
    original = im2double(original);
    restored = im2double(restored);
    degraded = im2double(degraded);

    % Mean Squared Error
    mse_degraded = mean((original(:) - degraded(:)).^2);
    mse_restored = mean((original(:) - restored(:)).^2);

    % Peak Signal-to-Noise Ratio
    psnr_degraded = 10 * log10(1 / mse_degraded);
    psnr_restored = 10 * log10(1 / mse_restored);

    % Structural Similarity Index (requires Image Processing Toolbox)
    if license('test', 'image_toolbox')
        ssim_degraded = ssim(degraded, original);
        ssim_restored = ssim(restored, original);
    else
        ssim_degraded = NaN;
        ssim_restored = NaN;
    end

    % Store metrics
    metrics = struct(...
        'MSE_Degraded', mse_degraded, ...
        'MSE_Restored', mse_restored, ...
        'PSNR_Degraded', psnr_degraded, ...
        'PSNR_Restored', psnr_restored, ...
        'Improvement_PSNR', psnr_restored - psnr_degraded, ...
        'SSIM_Degraded', ssim_degraded, ...
        'SSIM_Restored', ssim_restored, ...
        'Improvement_SSIM', ssim_restored - ssim_degraded ...
    );
end

