function analyze_tradeoffs(original, degraded, restored, method_name, params)
    % ANALYZE_TRADEOFFS Analyze trade-offs between noise reduction and detail preservation
    %
    % Inputs:
    %   original - Original image
    %   degraded - Degraded image
    %   restored - Restored image
    %   method_name - Name of restoration method
    %   params - Parameters used for restoration

    fprintf('\n=== TRADE-OFF ANALYSIS: %s ===\n', method_name);
    fprintf('Parameters: %s\n', params);

    % Calculate metrics
    mse_orig = mean((original(:) - degraded(:)).^2);
    mse_rest = mean((original(:) - restored(:)).^2);
    psnr_orig = 10 * log10(1 / mse_orig);
    psnr_rest = 10 * log10(1 / mse_rest);

    % Calculate gradient magnitude for edge preservation analysis
    [Gx_orig, Gy_orig] = gradient(original);
    [Gx_rest, Gy_rest] = gradient(restored);

    edge_strength_orig = sqrt(Gx_orig.^2 + Gy_orig.^2);
    edge_strength_rest = sqrt(Gx_rest.^2 + Gy_rest.^2);

    % Edge preservation metric
    edge_preservation = corr2(edge_strength_orig, edge_strength_rest);

    % Noise level estimation in smooth regions
    smooth_mask = imerode(original > 0.4 & original < 0.6, strel('disk', 3));
    noise_level_orig = std(degraded(smooth_mask));
    noise_level_rest = std(restored(smooth_mask));

    % Texture preservation (using local standard deviation)
    texture_orig = stdfilt(original);
    texture_rest = stdfilt(restored);
    texture_preservation = corr2(texture_orig, texture_rest);

    % Display trade-off metrics
    fprintf('PSNR Improvement: %.2f dB\n', psnr_rest - psnr_orig);
    fprintf('Edge Preservation: %.4f (1.0 = perfect)\n', edge_preservation);
    fprintf('Noise Reduction: %.2f%%\n', (1 - noise_level_rest/noise_level_orig)*100);
    fprintf('Texture Preservation: %.4f\n', texture_preservation);

    % Visual trade-off analysis
    figure('Name', sprintf('Trade-off Analysis: %s', method_name), ...
           'Position', [100, 100, 1200, 400]);

    % Original vs Restored comparison
    subplot(2,4,1);
    imshow(original);
    title('Original');

    subplot(2,4,2);
    imshow(degraded);
    title('Degraded');

    subplot(2,4,3);
    imshow(restored);
    title(sprintf('Restored\nPSNR: %.2f dB', psnr_rest));

    % Edge comparison
    subplot(2,4,4);
    imshowpair(edge_strength_orig > 0.1, edge_strength_rest > 0.1, 'montage');
    title(sprintf('Edge Preservation: %.4f', edge_preservation));

    % Error maps
    subplot(2,4,5);
    imshow(abs(original - degraded), []);
    title('Degradation Error');
    colorbar;

    subplot(2,4,6);
    imshow(abs(original - restored), []);
    title('Restoration Error');
    colorbar;

    % Noise analysis in smooth regions
    subplot(2,4,7);
    plot_region = original(100:150, 100:150);
    plot(plot_region(:), 'b-', 'LineWidth', 1.5);
    hold on;
    plot(restored(100:150, 100:150), 'r-', 'LineWidth', 1.5);
    title('Smooth Region Profile');
    legend({'Original', 'Restored'});
    xlabel('Pixel');
    ylabel('Intensity');
    grid on;

    % Texture analysis
    subplot(2,4,8);
    texture_region = original(50:80, 50:80);
    imagesc(texture_region);
    colormap('gray');
    title(sprintf('Texture Region\nPreservation: %.4f', texture_preservation));
    axis image;
    colorbar;
end

