function best_params = parameter_tuning_framework(y, original, method, param_ranges)
    % PARAMETER_TUNING_FRAMEWORK Systematic parameter tuning with trade-off analysis
    %
    % Inputs:
    %   y - Degraded image
    %   original - Original image
    %   method - Restoration method name
    %   param_ranges - Structure with parameter ranges to test
    %
    % Outputs:
    %   best_params - Optimal parameters based on trade-off analysis

    fprintf('\n=== PARAMETER TUNING: %s ===\n', method);

    results = struct();
    result_count = 0;

    switch lower(method)
        case 'notch'
            % Test different notch sizes and thresholds
            for notch_size = param_ranges.notch_sizes
                for threshold = param_ranges.thresholds
                    result_count = result_count + 1;

                    % Apply notch filter
                    center = floor(size(y) / 2) + 1;
                    positions = [
                        center(1)-1, center(2)-1;
                        center(1)-1, center(2);
                        center(1), center(2)-1;
                        center(1), center(2)
                    ];

                    restored = notch_filter_tuning(y, [], ...
                        'NotchSize', notch_size, ...
                        'Threshold', threshold, ...
                        'Positions', positions);

                    % Calculate trade-off metrics
                    metrics = calculate_tradeoff_metrics(original, y, restored);

                    % Store results
                    results(result_count).notch_size = notch_size;
                    results(result_count).threshold = threshold;
                    results(result_count).metrics = metrics;
                    results(result_count).restored = restored;

                    fprintf('Notch Size: %d, Threshold: %d, PSNR: %.2f, Edge Pres: %.4f\n', ...
                        notch_size, threshold, metrics.psnr, metrics.edge_preservation);
                end
            end

        case 'wiener'
            % Test different NSR values
            for nsr = param_ranges.nsr_values
                result_count = result_count + 1;

                % Apply Wiener filter
                restored = wiener_filter_matlab(y, [], 'NSR', nsr);

                % Calculate trade-off metrics
                metrics = calculate_tradeoff_metrics(original, y, restored);

                % Store results
                results(result_count).nsr = nsr;
                results(result_count).metrics = metrics;
                results(result_count).restored = restored;

                fprintf('NSR: %.4f, PSNR: %.2f, Noise Reduction: %.1f%%\n', ...
                    nsr, metrics.psnr, metrics.noise_reduction);
            end

        case 'lucy_richardson'
            % Test different iterations and damping factors
            for iterations = param_ranges.iterations
                for damping = param_ranges.damping_factors
                    result_count = result_count + 1;

                    % Apply Lucy-Richardson
                    restored = lucy_richardson_matlab(y, [], ...
                        'Iterations', iterations, ...
                        'Damping', damping);

                    % Calculate trade-off metrics
                    metrics = calculate_tradeoff_metrics(original, y, restored);

                    % Store results
                    results(result_count).iterations = iterations;
                    results(result_count).damping = damping;
                    results(result_count).metrics = metrics;
                    results(result_count).restored = restored;

                    fprintf('Iterations: %d, Damping: %.2f, PSNR: %.2f\n', ...
                        iterations, damping, metrics.psnr);
                end
            end
    end

    % Find optimal parameters based on trade-off analysis
    best_params = select_optimal_parameters(results, method);

    % Visualize parameter tuning results
    visualize_parameter_tuning(results, method, best_params);
end

function metrics = calculate_tradeoff_metrics(original, degraded, restored)
    % CALCULATE_TRADEOFF_METRICS Calculate comprehensive trade-off metrics

    % Basic metrics
    mse = mean((original(:) - restored(:)).^2);
    metrics.psnr = 10 * log10(1 / mse);

    % Edge preservation
    [Gx_orig, Gy_orig] = gradient(original);
    [Gx_rest, Gy_rest] = gradient(restored);
    edge_orig = sqrt(Gx_orig.^2 + Gy_orig.^2);
    edge_rest = sqrt(Gx_rest.^2 + Gy_rest.^2);
    metrics.edge_preservation = corr2(edge_orig, edge_rest);

    % Noise reduction
    smooth_mask = imerode(original > 0.4 & original < 0.6, strel('disk', 3));
    if nnz(smooth_mask) > 10
        noise_orig = std(degraded(smooth_mask));
        noise_rest = std(restored(smooth_mask));
        metrics.noise_reduction = (1 - noise_rest/noise_orig) * 100;
    else
        metrics.noise_reduction = 0;
    end

    % Texture preservation
    texture_orig = stdfilt(original);
    texture_rest = stdfilt(restored);
    metrics.texture_preservation = corr2(texture_orig, texture_rest);

    % Overall quality score (weighted combination)
    metrics.quality_score = 0.4 * metrics.psnr/50 + ...  % Normalized PSNR
                           0.3 * metrics.edge_preservation + ...
                           0.2 * min(metrics.noise_reduction/100, 1) + ...
                           0.1 * metrics.texture_preservation;
end

function best_params = select_optimal_parameters(results, method)
    % SELECT_OPTIMAL_PARAMETERS Select optimal parameters based on trade-offs

    % Extract quality scores
    quality_scores = [results(:).metrics];
    quality_scores = [quality_scores.quality_score];

    % Find best score
    [~, best_idx] = max(quality_scores);

    % Return best parameters
    switch lower(method)
        case 'notch'
            best_params = struct(...
                'notch_size', results(best_idx).notch_size, ...
                'threshold', results(best_idx).threshold);

        case 'wiener'
            best_params = struct('nsr', results(best_idx).nsr);

        case 'lucy_richardson'
            best_params = struct(...
                'iterations', results(best_idx).iterations, ...
                'damping', results(best_idx).damping);
    end

    fprintf('\nOptimal Parameters Found:\n');
    disp(best_params);
    fprintf('Quality Score: %.4f\n', quality_scores(best_idx));
end

