function [g, x, y] = extended_gcd(a, b)
    % EXTENDED_GCD Extended Euclidean Algorithm
    %
    % Input:
    %   a, b - Integers
    %
    % Output:
    %   g - gcd(a, b)
    %   x, y - Coefficients such that a*x + b*y = g

    if a == 0
        g = b;
        x = 0;
        y = 1;
    else
        [g, x1, y1] = extended_gcd(mod(b, a), a);
        x = y1 - floor(b / a) * x1;
        y = x1;
    end
end

