function success = verify_rsa_keys(public_key, private_key)
    % VERIFY_RSA_KEYS Verify that RSA keys work correctly
    %
    % Input:
    %   public_key  - Public key structure
    %   private_key - Private key structure
    %
    % Output:
    %   success - True if keys work correctly

    fprintf('\n=== VERIFYING RSA KEYS ===\n');

    % Test with a random message
    test_message = randi([1, public_key.n-1]);
    fprintf('Test message: %d\n', test_message);

    % Encrypt: c = m^e mod n
    encrypted = powermod(test_message, public_key.e, public_key.n);
    fprintf('Encrypted: %d\n', encrypted);

    % Decrypt: m = c^d mod n
    decrypted = powermod(encrypted, private_key.d, private_key.n);
    fprintf('Decrypted: %d\n', decrypted);

    % Check if decryption matches original
    if test_message == decrypted
        fprintf('✓ Keys work correctly!\n');
        success = true;
    else
        fprintf('✗ Keys do not work correctly!\n');
        success = false;
    end
end

