    "strings"
    "time"
)

// ============================================
// STEP 1: UNDERSTANDING THE PROBLEM
// ============================================
// We're creating a budget allocation system that distributes resources
// across different categories (like R&D, Marketing, etc.) while:
// 1. Staying within total budget
// 2. Meeting minimum/maximum limits for each category
// 3. Maximizing expected returns while minimizing risk

// ============================================
// STEP 2: DEFINING OUR DATA STRUCTURES
// ============================================

// Individual represents one possible budget allocation solution
// Think of it as one "guess" at how to distribute the budget
type Individual struct {
    Weights []float64 // How much to allocate to each category
    Fitness float64   // How good this allocation is (higher = better)
}

// BudgetOptimizer holds all our genetic algorithm settings and data
// This is like the "brain" of our optimization system
type BudgetOptimizer struct {
    // Problem setup
    Categories  []string   // Names of budget categories
    MinWeights  []float64  // Minimum allowed for each category
    MaxWeights  []float64  // Maximum allowed for each category
    TotalBudget float64    // Total budget to allocate (usually 1.0 = 100%)

    // Genetic algorithm settings
    PopulationSize int     // How many solutions to work with at once
    MutationRate   float64 // How often to make random changes
    CrossoverRate  float64 // How often to combine solutions
    Generations    int     // How many rounds of improvement to run
    ElitismCount   int     // How many best solutions to keep unchanged
    TournamentSize int     // How many solutions to compare when selecting

    // Performance data (for calculating fitness)
    ExpectedReturns []float64 // Expected return for each category
    RiskFactors     []float64 // Risk level for each category
}

// ============================================
// STEP 3: SETTING UP THE OPTIMIZER
// ============================================

// NewBudgetOptimizer creates and validates our optimizer
func NewBudgetOptimizer(categories []string, minWeights, maxWeights []float64, totalBudget float64) *BudgetOptimizer {
    // First, check that our inputs make sense
    if len(categories) != len(minWeights) || len(categories) != len(maxWeights) {
        panic("All input arrays must have the same length")
    }

    for i := range minWeights {
        if minWeights[i] > maxWeights[i] {
            panic(fmt.Sprintf("Minimum weight cannot exceed maximum weight for category %d", i))
        }
    }

    // Create realistic performance data for each category
    // In a real application, this would come from historical data
    expectedReturns := make([]float64, len(categories))
    riskFactors := make([]float64, len(categories))

    for i := range categories {
        // Categories with wider allocation ranges typically have higher risk/return
        rangeSize := maxWeights[i] - minWeights[i]
        expectedReturns[i] = 0.05 + rangeSize*0.3  // 5-35% expected return
        riskFactors[i] = 0.02 + rangeSize*0.5      // 2-52% risk factor
    }

    // Return our fully configured optimizer
    return &BudgetOptimizer{
        Categories:      categories,
        MinWeights:      minWeights,
        MaxWeights:      maxWeights,
        TotalBudget:     totalBudget,
        PopulationSize:  100,    // Good starting point
        MutationRate:    0.15,   // 15% chance of mutation
        CrossoverRate:   0.85,   // 85% chance of crossover
        Generations:     200,    // Run 200 improvement cycles
        ElitismCount:    2,      // Keep 2 best solutions each generation
        TournamentSize:  3,      // Compare 3 solutions when selecting
        ExpectedReturns: expectedReturns,
        RiskFactors:     riskFactors,
    }
}

// ============================================
// STEP 4: CREATING RANDOM SOLUTIONS
// ============================================

// createIndividual makes one random budget allocation
func (bo *BudgetOptimizer) createIndividual() *Individual {
    weights := make([]float64, len(bo.Categories))

    // Step 1: Fill with random values within allowed ranges
    for i := range weights {
        min := bo.MinWeights[i]
        max := bo.MaxWeights[i]
        weights[i] = min + rand.Float64()*(max-min)
    }

    // Step 2: Adjust so total equals our budget
    bo.normalizeWeights(weights)

    return &Individual{Weights: weights}
}

// normalizeWeights ensures all weights add up to TotalBudget
func (bo *BudgetOptimizer) normalizeWeights(weights []float64) {
    // Calculate current total
    total := 0.0
    for _, w := range weights {
        total += w
    }

    if total > 0 {
        // Scale everything proportionally
        scale := bo.TotalBudget / total
        for i := range weights {
            weights[i] *= scale

            // Make sure we're still within bounds
            if weights[i] < bo.MinWeights[i] {
                weights[i] = bo.MinWeights[i]
            }
            if weights[i] > bo.MaxWeights[i] {
                weights[i] = bo.MaxWeights[i]
            }
        }

        // Recalculate and adjust if needed
        total = 0.0
        for _, w := range weights {
            total += w
        }

        if math.Abs(total-bo.TotalBudget) > 0.001 {
            scale := bo.TotalBudget / total
            for i := range weights {
                weights[i] *= scale
            }
        }
    }
}

// ============================================
// STEP 5: EVALUATING SOLUTION QUALITY
// ============================================

// calculateFitness determines how good a solution is
func (bo *BudgetOptimizer) calculateFitness(ind *Individual) float64 {
    // Calculate expected return (higher is better)
    totalReturn := 0.0
    for i, w := range ind.Weights {
        totalReturn += w * bo.ExpectedReturns[i]
    }

    // Calculate risk (lower is better)
    totalRisk := 0.0
    for i, w := range ind.Weights {
        totalRisk += w * bo.RiskFactors[i]
    }

    // Basic fitness: return minus risk
    fitness := totalReturn - totalRisk

    // Apply penalties for breaking rules
    penalty := bo.calculatePenalty(ind)

    return fitness - penalty
}

// calculatePenalty adds costs for violating constraints
func (bo *BudgetOptimizer) calculatePenalty(ind *Individual) float64 {
    penalty := 0.0

    // Check if any allocation is outside allowed range
    for i, w := range ind.Weights {
        if w < bo.MinWeights[i] {
            penalty += 10 * (bo.MinWeights[i] - w)
        }
        if w > bo.MaxWeights[i] {
            penalty += 10 * (w - bo.MaxWeights[i])
        }
    }

    // Check if total is correct
    totalWeight := 0.0
    for _, w := range ind.Weights {
        totalWeight += w
    }

    if math.Abs(totalWeight-bo.TotalBudget) > 0.01 {
        penalty += 100 * math.Abs(totalWeight-bo.TotalBudget)
    }

    return penalty
}

// ============================================
// STEP 6: GENETIC OPERATIONS
// ============================================

// tournamentSelection picks a good solution using competition
func (bo *BudgetOptimizer) tournamentSelection(population []*Individual) *Individual {
    // Pick one random solution to start
    best := population[rand.Intn(len(population))]

    // Compare with others and keep the best
    for i := 1; i < bo.TournamentSize; i++ {
        contender := population[rand.Intn(len(population))]
        if contender.Fitness > best.Fitness {
            best = contender
        }
    }

    return best
}

// crossover combines two parent solutions to create children
func (bo *BudgetOptimizer) crossover(parent1, parent2 *Individual) (*Individual, *Individual) {
    // Sometimes we just copy parents without mixing
    if rand.Float64() > bo.CrossoverRate {
        child1 := &Individual{Weights: make([]float64, len(parent1.Weights))}
        child2 := &Individual{Weights: make([]float64, len(parent2.Weights))}
        copy(child1.Weights, parent1.Weights)
        copy(child2.Weights, parent2.Weights)
        return child1, child2
    }

    // Mix parent allocations using weighted average
    alpha := rand.Float64()
    child1 := &Individual{Weights: make([]float64, len(parent1.Weights))}
    child2 := &Individual{Weights: make([]float64, len(parent2.Weights))}

    for i := range parent1.Weights {
        child1.Weights[i] = alpha*parent1.Weights[i] + (1-alpha)*parent2.Weights[i]
        child2.Weights[i] = (1-alpha)*parent1.Weights[i] + alpha*parent2.Weights[i]
    }

    // Make sure children follow the rules
    bo.normalizeWeights(child1.Weights)
    bo.normalizeWeights(child2.Weights)

    return child1, child2
}

// mutate makes small random changes to a solution
func (bo *BudgetOptimizer) mutate(ind *Individual) {
    for i := range ind.Weights {
        // Randomly decide whether to mutate this allocation
        if rand.Float64() < bo.MutationRate {
            // Add a small random change
            mutation := rand.NormFloat64() * 0.1 * (bo.MaxWeights[i] - bo.MinWeights[i])
            ind.Weights[i] += mutation

            // Keep within bounds
            if ind.Weights[i] < bo.MinWeights[i] {
                ind.Weights[i] = bo.MinWeights[i]
            }
            if ind.Weights[i] > bo.MaxWeights[i] {
                ind.Weights[i] = bo.MaxWeights[i]
            }
        }
    }

    // Re-normalize after mutations
    bo.normalizeWeights(ind.Weights)
}

// ============================================
// STEP 7: POPULATION MANAGEMENT
// ============================================

// createInitialPopulation makes our starting set of solutions
func (bo *BudgetOptimizer) createInitialPopulation() []*Individual {
    population := make([]*Individual, bo.PopulationSize)

    for i := range population {
        population[i] = bo.createIndividual()
        population[i].Fitness = bo.calculateFitness(population[i])
    }

    return population
}

// sortPopulation organizes solutions from best to worst
func (bo *BudgetOptimizer) sortPopulation(population []*Individual) {
    sort.Slice(population, func(i, j int) bool {
        return population[i].Fitness > population[j].Fitness
    })
}

// ============================================
// STEP 8: MAIN GENETIC ALGORITHM LOOP
// ============================================

// Run executes the complete optimization process
func (bo *BudgetOptimizer) Run() (*Individual, []float64, []float64) {
    // Initialize random number generator
    rand.Seed(time.Now().UnixNano())

    // Create starting population
    population := bo.createInitialPopulation()
    bo.sortPopulation(population)

    // Track progress over time
    bestFitnessHistory := make([]float64, 0, bo.Generations)
    avgFitnessHistory := make([]float64, 0, bo.Generations)

    bestIndividual := population[0]

    // Main evolution loop
    for generation := 0; generation < bo.Generations; generation++ {
        // Calculate statistics for this generation
        bestFitness := population[0].Fitness
        avgFitness := 0.0
        for _, ind := range population {
            avgFitness += ind.Fitness
        }
        avgFitness /= float64(len(population))

        // Record history
        bestFitnessHistory = append(bestFitnessHistory, bestFitness)
        avgFitnessHistory = append(avgFitnessHistory, avgFitness)

        // Update best solution found so far
        if bestFitness > bestIndividual.Fitness {
            bestIndividual = &Individual{
                Weights: make([]float64, len(population[0].Weights)),
                Fitness: bestFitness,
            }
            copy(bestIndividual.Weights, population[0].Weights)
        }

        // Create next generation
        newPopulation := make([]*Individual, 0, bo.PopulationSize)

        // Keep the best solutions unchanged (elitism)
        for i := 0; i < bo.ElitismCount && i < len(population); i++ {
            elite := &Individual{
                Weights: make([]float64, len(population[i].Weights)),
                Fitness: population[i].Fitness,
            }
            copy(elite.Weights, population[i].Weights)
            newPopulation = append(newPopulation, elite)
        }

        // Fill the rest of the population
        for len(newPopulation) < bo.PopulationSize {
            // Select parents
            parent1 := bo.tournamentSelection(population)
            parent2 := bo.tournamentSelection(population)

            // Create children through crossover
            child1, child2 := bo.crossover(parent1, parent2)

            // Apply mutation
            bo.mutate(child1)
            bo.mutate(child2)

            // Evaluate children
            child1.Fitness = bo.calculateFitness(child1)
            child2.Fitness = bo.calculateFitness(child2)

            newPopulation = append(newPopulation, child1, child2)
        }

        // Trim if we have too many
        if len(newPopulation) > bo.PopulationSize {
            newPopulation = newPopulation[:bo.PopulationSize]
        }

        // Sort and replace old population
        bo.sortPopulation(newPopulation)
        population = newPopulation

        // Show progress
        if generation%50 == 0 {
            fmt.Printf("Generation %3d: Best = %.4f, Average = %.4f\n",
                generation, bestFitness, avgFitness)
        }
    }

    return bestIndividual, bestFitnessHistory, avgFitnessHistory
}

// ============================================
// STEP 9: DISPLAYING RESULTS
// ============================================

// PrintResults shows the optimized budget allocation
func (bo *BudgetOptimizer) PrintResults(best *Individual) {
    fmt.Println("\n" + strings.Repeat("=", 60))
    fmt.Println("OPTIMAL BUDGET ALLOCATION FOUND")
    fmt.Println(strings.Repeat("=", 60))
    fmt.Printf("Overall Quality Score: %.4f\n", best.Fitness)
    fmt.Println("\nCategory Breakdown:")

    total := 0.0
    for i, category := range bo.Categories {
        allocation := best.Weights[i]
        total += allocation
        fmt.Printf("  %-20s: %.3f (%.1f%%)\n", 
            category, allocation, allocation*100)
    }

    fmt.Printf("\nTotal Allocation: %.3f (Target: %.3f)\n", total, bo.TotalBudget)

    // Calculate performance metrics
    expectedReturn := 0.0
    expectedRisk := 0.0
    for i, w := range best.Weights {
        expectedReturn += w * bo.ExpectedReturns[i]
        expectedRisk += w * bo.RiskFactors[i]
    }

    fmt.Println("\nExpected Performance:")
    fmt.Printf("  Return: %.2f%%\n", expectedReturn*100)
    fmt.Printf("  Risk:   %.2f%%\n", expectedRisk*100)
    if expectedRisk > 0 {
        fmt.Printf("  Return/Risk Ratio: %.2f\n", expectedReturn/expectedRisk)
    }
}

// ============================================
// STEP 10: EXAMPLE USAGE
// ============================================

func main() {
    // Initialize random number generator
    rand.Seed(time.Now().UnixNano())

    fmt.Println("GENETIC ALGORITHM BUDGET OPTIMIZER")
    fmt.Println(strings.Repeat("-", 40))

    // Define our budget categories
    categories := []string{
        "Research & Development",
        "Marketing",
        "Operations",
        "Human Resources",
        "Information Technology",
    }

    // Set minimum required allocations
    minWeights := []float64{0.10, 0.05, 0.20, 0.03, 0.08}

    // Set maximum allowed allocations
    maxWeights := []float64{0.35, 0.25, 0.40, 0.15, 0.25}

    // Create the optimizer
    optimizer := NewBudgetOptimizer(categories, minWeights, maxWeights, 1.0)

    // Customize settings (optional)
    optimizer.PopulationSize = 80
    optimizer.MutationRate = 0.2
    optimizer.CrossoverRate = 0.9
    optimizer.Generations = 250
    optimizer.ElitismCount = 3

    // Run the optimization
    fmt.Println("\nStarting optimization process...")
    fmt.Printf("Optimizing %d categories over %d generations\n", 
        len(categories), optimizer.Generations)
    fmt.Println(strings.Repeat("-", 40))

    startTime := time.Now()
    bestIndividual, _, _ := optimizer.Run()
    elapsedTime := time.Since(startTime)

    // Display results
    optimizer.PrintResults(bestIndividual)

    // Show summary
    fmt.Println("\n" + strings.Repeat("-", 40))
    fmt.Println("OPTIMIZATION COMPLETE")
    fmt.Printf("Time taken: %v\n", elapsedTime)
    fmt.Println("All constraints satisfied ✓")
}
