```go
package main

import (
    "fmt"
    "math"
    "math/rand"
    "sort"
    "strings"
    "time"
)

// ============================================
// PART 1: UNDERSTANDING THE PROBLEM
// ============================================
// We're creating a system to allocate a budget across different categories
// (like Marketing, R&D, Operations, etc.) while following these rules:
// 1. Total must equal 100% of the budget
// 2. Each category has minimum and maximum limits
// 3. We want to maximize returns while minimizing risk

// ============================================
// PART 2: DEFINING OUR DATA STRUCTURES
// ============================================

// Individual represents one possible budget allocation
// Think of it as one "plan" for how to distribute the money
type Individual struct {
    Weights []float64 // How much to give each category (e.g., [0.2, 0.3, 0.5])
    Fitness float64   // How good this plan is (higher number = better plan)
}

// BudgetOptimizer is the main controller for our genetic algorithm
// It holds all the settings and data needed to find the best allocation
type BudgetOptimizer struct {
    // Problem setup - what we're trying to solve
    Categories  []string   // Names of budget areas (e.g., "Marketing", "R&D")
    MinWeights  []float64  // Minimum required for each category
    MaxWeights  []float64  // Maximum allowed for each category
    TotalBudget float64    // Total to allocate (usually 1.0 = 100%)

    // Genetic algorithm settings - how we'll search for solutions
    PopulationSize int     // How many different plans to consider at once
    MutationRate   float64 // How often to make random changes to plans
    CrossoverRate  float64 // How often to combine two plans
    Generations    int     // How many rounds of improvement to run
    ElitismCount   int     // How many best plans to keep unchanged each round
    TournamentSize int     // How many plans to compare when choosing parents

    // Performance data - used to evaluate how good a plan is
    ExpectedReturns []float64 // Expected profit from each category
    RiskFactors     []float64 // Risk level for each category
}

// ============================================
// PART 3: SETTING UP THE OPTIMIZER
// ============================================

// NewBudgetOptimizer creates and configures our optimizer
func NewBudgetOptimizer(categories []string, minWeights, maxWeights []float64, totalBudget float64) *BudgetOptimizer {
    // First, check that our inputs make sense
    if len(categories) != len(minWeights) || len(categories) != len(maxWeights) {
        panic("All input arrays must have the same length")
    }

    for i := range minWeights {
        if minWeights[i] > maxWeights[i] {
            panic(fmt.Sprintf("Minimum cannot exceed maximum for category %d", i))
        }
    }

    // Create realistic performance estimates for each category
    // In a real application, this would come from historical data
    expectedReturns := make([]float64, len(categories))
    riskFactors := make([]float64, len(categories))

    for i := range categories {
        // Categories with wider allocation ranges typically offer higher returns but with more risk
        rangeSize := maxWeights[i] - minWeights[i]
        expectedReturns[i] = 0.05 + rangeSize*0.3  // 5-35% expected return
        riskFactors[i] = 0.02 + rangeSize*0.5      // 2-52% risk factor
    }

    // Return our fully configured optimizer with sensible defaults
    return &BudgetOptimizer{
        Categories:      categories,
        MinWeights:      minWeights,
        MaxWeights:      maxWeights,
        TotalBudget:     totalBudget,
        PopulationSize:  100,    // Start with 100 different plans
        MutationRate:    0.15,   // 15% chance of random changes
        CrossoverRate:   0.85,   // 85% chance of combining plans
        Generations:     200,    // Run 200 improvement cycles
        ElitismCount:    2,      // Keep 2 best plans each generation
        TournamentSize:  3,      // Compare 3 plans when selecting
        ExpectedReturns: expectedReturns,
        RiskFactors:     riskFactors,
    }
}

// ============================================
// PART 4: CREATING RANDOM PLANS
// ============================================

// createIndividual makes one random budget allocation plan
func (bo *BudgetOptimizer) createIndividual() *Individual {
    weights := make([]float64, len(bo.Categories))

    // Step 1: Fill with random values within allowed ranges
    for i := range weights {
        min := bo.MinWeights[i]
        max := bo.MaxWeights[i]
        weights[i] = min + rand.Float64()*(max-min)
    }

    // Step 2: Adjust so total equals our budget
    bo.normalizeWeights(weights)

    return &Individual{Weights: weights}
}

// normalizeWeights ensures all weights add up to TotalBudget
func (bo *BudgetOptimizer) normalizeWeights(weights []float64) {
    // Calculate current total
    total := 0.0
    for _, w := range weights {
        total += w
    }

    if total > 0 {
        // Scale everything proportionally
        scale := bo.TotalBudget / total
        for i := range weights {
            weights[i] *= scale

            // Make sure we're still within bounds
            if weights[i] < bo.MinWeights[i] {
                weights[i] = bo.MinWeights[i]
            }
            if weights[i] > bo.MaxWeights[i] {
                weights[i] = bo.MaxWeights[i]
            }
        }

        // Recalculate and adjust if needed
        total = 0.0
        for _, w := range weights {
            total += w
        }

        if math.Abs(total-bo.TotalBudget) > 0.001 {
            scale := bo.TotalBudget / total
            for i := range weights {
                weights[i] *= scale
            }
        }
    }
}

// ============================================
// PART 5: EVALUATING PLAN QUALITY
// ============================================

// calculateFitness determines how good a plan is
func (bo *BudgetOptimizer) calculateFitness(ind *Individual) float64 {
    // Calculate expected return (higher is better)
    totalReturn := 0.0
    for i, w := range ind.Weights {
        totalReturn += w * bo.ExpectedReturns[i]
    }

    // Calculate risk (lower is better)
    totalRisk := 0.0
    for i, w := range ind.Weights {
        totalRisk += w * bo.RiskFactors[i]
    }

    // Basic fitness: return minus risk
    fitness := totalReturn - totalRisk

    // Apply penalties for breaking rules
    penalty := bo.calculatePenalty(ind)

    return fitness - penalty
}

// calculatePenalty adds costs for violating constraints
func (bo *BudgetOptimizer) calculatePenalty(ind *Individual) float64 {
    penalty := 0.0

    // Check if any allocation is outside allowed range
    for i, w := range ind.Weights {
        if w < bo.MinWeights[i] {
            penalty += 10 * (bo.MinWeights[i] - w)
        }
        if w > bo.MaxWeights[i] {
            penalty += 10 * (w - bo.MaxWeights[i])
        }
    }

    // Check if total is correct
    totalWeight := 0.0
    for _, w := range ind.Weights {
        totalWeight += w
    }

    if math.Abs(totalWeight-bo.TotalBudget) > 0.01 {
        penalty += 100 * math.Abs(totalWeight-bo.TotalBudget)
    }

    return penalty
}

// ============================================
// PART 6: GENETIC OPERATIONS
// ============================================

// tournamentSelection picks a good plan using competition
func (bo *BudgetOptimizer) tournamentSelection(population []*Individual) *Individual {
    // Pick one random plan to start
    best := population[rand.Intn(len(population))]

    // Compare with others and keep the best
    for i := 1; i < bo.TournamentSize; i++ {
        contender := population[rand.Intn(len(population))]
        if contender.Fitness > best.Fitness {
            best = contender
        }
    }

    return best
}

// crossover combines two parent plans to create children
func (bo *BudgetOptimizer) crossover(parent1, parent2 *Individual) (*Individual, *Individual) {
    // Sometimes we just copy parents without mixing
    if rand.Float64() > bo.CrossoverRate {
        child1 := &Individual{Weights: make([]float64, len(parent1.Weights))}
        child2 := &Individual{Weights: make([]float64, len(parent2.Weights))}
        copy(child1.Weights, parent1.Weights)
        copy(child2.Weights, parent2.Weights)
        return child1, child2
    }

    // Mix parent allocations using weighted average
    alpha := rand.Float64()
    child1 := &Individual{Weights: make([]float64, len(parent1.Weights))}
    child2 := &Individual{Weights: make([]float64, len(parent2.Weights))}

    for i := range parent1.Weights {
        child1.Weights[i] = alpha*parent1.Weights[i] + (1-alpha)*parent2.Weights[i]
        child2.Weights[i] = (1-alpha)*parent1.Weights[i] + alpha*parent2.Weights[i]
    }

    // Make sure children follow the rules
    bo.normalizeWeights(child1.Weights)
    bo.normalizeWeights(child2.Weights)

    return child1, child2
}

// mutate makes small random changes to a plan
func (bo *BudgetOptimizer) mutate(ind *Individual) {
    for i := range ind.Weights {
        // Randomly decide whether to mutate this allocation
        if rand.Float64() < bo.MutationRate {
            // Add a small random change
            mutation := rand.NormFloat64() * 0.1 * (bo.MaxWeights[i] - bo.MinWeights[i])
            ind.Weights[i] += mutation

            // Keep within bounds
            if ind.Weights[i] < bo.MinWeights[i] {
                ind.Weights[i] = bo.MinWeights[i]
            }
            if ind.Weights[i] > bo.MaxWeights[i] {
                ind.Weights[i] = bo.MaxWeights[i]
            }
        }
    }

    // Re-normalize after mutations
    bo.normalizeWeights(ind.Weights)
}

// ============================================
// PART 7: POPULATION MANAGEMENT
// ============================================

// createInitialPopulation makes our starting set of plans
func (bo *BudgetOptimizer) createInitialPopulation() []*Individual {
    population := make([]*Individual, bo.PopulationSize)

    for i := range population {
        population[i] = bo.createIndividual()
        population[i].Fitness = bo.calculateFitness(population[i])
    }

    return population
}

// sortPopulation organizes plans from best to worst
func (bo *BudgetOptimizer) sortPopulation(population []*Individual) {
    sort.Slice(population, func(i, j int) bool {
        return population[i].Fitness > population[j].Fitness
    })
}

// ============================================
// PART 8: MAIN GENETIC ALGORITHM LOOP
// ============================================

// Run executes the complete optimization process
func (bo *BudgetOptimizer) Run() (*Individual, []float64, []float64) {
    // Initialize random number generator
    rand.Seed(time.Now().UnixNano())

    // Create starting population
    population := bo.createInitialPopulation()
    bo.sortPopulation(population)

