@app.route('/api/signup/email', methods=['POST'])
def signup_with_email():
    """Step 1: Signup with email"""
    data = request.json
    email = data.get('email')

    if not email:
        return jsonify({'success': False, 'error': 'Email is required'}), 400

    result = FirebaseAuthManager.create_user_with_email(email)
    return jsonify(result), 200 if result['success'] else 400

@app.route('/api/signup/password', methods=['POST'])
def set_password():
    """Step 2: Set password"""
    data = request.json
    uid = data.get('uid')
    password = data.get('password')
    confirm_password = data.get('confirm_password')

    if not all([uid, password, confirm_password]):
        return jsonify({'success': False, 'error': 'All fields are required'}), 400

    result = FirebaseAuthManager.update_password(uid, password, confirm_password)
    return jsonify(result), 200 if result['success'] else 400

@app.route('/api/signup/personal-info', methods=['POST'])
def set_personal_info():
    """Step 3: Set personal information"""
    data = request.json
    uid = data.get('uid')
    first_name = data.get('first_name')
    last_name = data.get('last_name')

    if not all([uid, first_name, last_name]):
        return jsonify({'success': False, 'error': 'All fields are required'}), 400

    result = FirebaseAuthManager.update_personal_info(uid, first_name, last_name)
    return jsonify(result), 200 if result['success'] else 400

@app.route('/api/signup/profile-picture', methods=['POST'])
def upload_profile_pic():
    """Upload profile picture"""
    if 'image' not in request.files:
        return jsonify({'success': False, 'error': 'No image provided'}), 400

    uid = request.form.get('uid')
    image_file = request.files['image']

    if not uid:
        return jsonify({'success': False, 'error': 'User ID is required'}), 400

    result = FirebaseAuthManager.upload_profile_picture(uid, image_file)
    return jsonify(result), 200 if result['success'] else 400

@app.route('/api/signup/body-metrics', methods=['POST'])
def set_body_metrics():
    """Step 4: Set body metrics"""
    data = request.json
    uid = data.get('uid')
    weight = data.get('weight')
    height = data.get('height')
    body_type = data.get('body_type')

    if not all([uid, weight, height, body_type]):
        return jsonify({'success': False, 'error': 'All fields are required'}), 400

    result = FirebaseAuthManager.update_body_metrics(uid, weight, height, body_type)
    return jsonify(result), 200 if result['success'] else 400

@app.route('/api/profile/<uid>', methods=['GET'])
