  final FlutterSecureStorage _secureStorage = FlutterSecureStorage();

  Future<void> _saveBodyMetrics() async {
    if (!_formKey.currentState!.validate()) return;
    if (_selectedBodyType == null) {
      setState(() {
        _errorMessage = 'Please select a body type';
      });
      return;
    }

    setState(() {
      _isLoading = true;
      _errorMessage = '';
    });

    try {
      final response = await http.post(
        Uri.parse('http://localhost:5000/api/signup/body-metrics'),
        headers: {
          'Content-Type': 'application/json',
          'Authorization': await _getAuthToken(), // Secure API call
        },
        body: json.encode({
          'uid': widget.uid,
          'weight': _weightController.text,
          'height': _heightController.text,
          'body_type': _selectedBodyType,
        }),
      );

      final data = json.decode(response.body);

      if (response.statusCode == 200 && data['success']) {
        // Store user data securely
        await _storeUserDataSecurely(data['user_data']);

        // Navigate to profile page
        Navigator.pushAndRemoveUntil(
          context,
          MaterialPageRoute(
            builder: (context) => ProfilePage(uid: widget.uid),
          ),
          (route) => false,
        );
      } else {
        setState(() {
          _errorMessage = data['error'] ?? 'Failed to save body metrics';
        });
      }
    } catch (e) {
      setState(() {
        _errorMessage = 'Network error: $e';
      });
    } finally {
      setState(() {
        _isLoading = false;
      });
    }
  }

  Future<String> _getAuthToken() async {
    // Retrieve authentication token from secure storage
    final token = await _secureStorage.read(key: 'auth_token');
    return token ?? '';
  }

  Future<void> _storeUserDataSecurely(Map<String, dynamic> userData) async {
    // Store sensitive user data securely
    await _secureStorage.write(
      key: 'user_data',
      value: json.encode({
        'uid': userData['uid'],
        'email': userData['email'],
        'first_name': userData['first_name'],
        'last_name': userData['last_name'],
      }),
    );

    // Store profile completion status
    await _secureStorage.write(
      key: 'profile_completed',
      value: userData['profile_completed'].toString(),
