class _EnhancedProfilePageState extends State<EnhancedProfilePage> {
  Map<String, dynamic>? _userData;
  bool _isLoading = true;
  String _errorMessage = '';
  final FlutterSecureStorage _secureStorage = FlutterSecureStorage();

  @override
  void initState() {
    super.initState();
    _loadUserProfile();
  }

  Future<void> _loadUserProfile() async {
    try {
      // Try to load from cache first for better UX
      final cachedData = await _getCachedUserData();
      if (cachedData != null) {
        setState(() {
          _userData = cachedData;
          _isLoading = false;
        });
      }

      // Then fetch fresh data from server
      final response = await http.get(
        Uri.parse('http://localhost:5000/api/profile/${widget.uid}'),
        headers: {
          'Content-Type': 'application/json',
          'Authorization': await _getAuthToken(),
        },
      );

      if (response.statusCode == 200) {
        final data = json.decode(response.body);
        if (data['success']) {
          // Cache the fresh data
          await _cacheUserData(data['user_data']);

          setState(() {
            _userData = data['user_data'];
            _isLoading = false;
          });
        } else {
          setState(() {
            _errorMessage = data['error'] ?? 'Failed to load profile';
            _isLoading = false;
          });
        }
      } else {
        setState(() {
          _errorMessage = 'Server error: ${response.statusCode}';
          _isLoading = false;
        });
      }
    } catch (e) {
      setState(() {
        _errorMessage = 'Network error: $e';
        _isLoading = false;
      });
    }
  }

  Future<String> _getAuthToken() async {
    final token = await _secureStorage.read(key: 'auth_token');
    return token ?? '';
  }

  Future<void> _cacheUserData(Map<String, dynamic> userData) async {
    // Store non-sensitive data in cache
    await _secureStorage.write(
      key: 'cached_user_data',
      value: json.encode({
        'first_name': userData['first_name'],
        'last_name': userData['last_name'],
        'profile_picture': userData['profile_picture'],
        'weight': userData['weight'],
        'height': userData['height'],
        'body_type': userData['body_type'],
        'bmi': userData['bmi'],
        'last_updated': DateTime.now().toIso8601String(),
      }),
    );
  }

  Future<Map<String, dynamic>?> _getCachedUserData() async {
    try {
      final cachedData = await _secureStorage.read(key: 'cached_user_data');
      if (cachedData != null) {
        final data = json.decode(cachedData);
        final lastUpdated = DateTime.parse(data['last_updated']);
        final now = DateTime.now();

        // Only use cache if it's less than 1 hour old
        if (now.difference(lastUpdated).inHours < 1) {
          return data;
        }
      }
    } catch (e) {
      print('Error reading cache: $e');
    }
    return null;
  }

