  final FirebaseStorage _storage = FirebaseStorage.instance;
  final FirebaseFirestore _firestore = FirebaseFirestore.instance;

  // Image validation
  bool _validateImage(File image) {
    // Check file size (max 5MB)
    final fileSize = image.lengthSync();
    if (fileSize > 5 * 1024 * 1024) {
      return false;
    }

    // Check file extension
    final fileName = image.path.toLowerCase();
    final allowedExtensions = ['.jpg', '.jpeg', '.png', '.gif'];
    return allowedExtensions.any((ext) => fileName.endsWith(ext));
  }

  Future<void> _pickImage() async {
    try {
      final pickedFile = await _picker.pickImage(
        source: ImageSource.gallery,
        maxWidth: 800,
        maxHeight: 800,
        imageQuality: 85,
      );

      if (pickedFile != null) {
        final imageFile = File(pickedFile.path);

        if (!_validateImage(imageFile)) {
          setState(() {
            _errorMessage = 'Image must be JPG, PNG, or GIF and less than 5MB';
          });
          return;
        }

        setState(() {
          _selectedImage = imageFile;
          _errorMessage = '';
        });
      }
    } catch (e) {
      setState(() {
        _errorMessage = 'Error selecting image: $e';
      });
    }
  }

  Future<void> _uploadProfilePicture() async {
    if (_selectedImage == null) {
      setState(() {
        _errorMessage = 'Please select a profile picture';
      });
      return;
    }

    setState(() {
      _isLoading = true;
      _errorMessage = '';
    });

    try {
      // Generate unique filename with user ID
      final timestamp = DateTime.now().millisecondsSinceEpoch;
      final fileName = 'profile_${widget.uid}_$timestamp.jpg';

      // Create storage reference
      final Reference storageRef = _storage.ref().child('profile_pictures/$fileName');

      // Upload with metadata
      final metadata = SettableMetadata(
        contentType: 'image/jpeg',
        customMetadata: {
          'uploadedBy': widget.uid,
          'uploadedAt': DateTime.now().toIso8601String(),
        },
      );

      final UploadTask uploadTask = storageRef.putFile(
        _selectedImage!,
        metadata,
      );

      // Show upload progress
      uploadTask.snapshotEvents.listen((TaskSnapshot snapshot) {
        final progress = snapshot.bytesTransferred / snapshot.totalBytes;
        print('Upload progress: ${(progress * 100).toStringAsFixed(2)}%');
      });

      // Wait for upload completion
      final TaskSnapshot snapshot = await uploadTask;

      // Get download URL
      final String downloadUrl = await snapshot.ref.getDownloadURL();

      // Save URL to Firestore
      await _firestore.collection('users').doc(widget.uid).set({
        'profile_picture': downloadUrl,
        'profile_picture_updated': FieldValue.serverTimestamp(),
        'signup_stage': 'profile_picture_set',
      }, SetOptions(merge: true));

      // Navigate to body metrics page
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (context) => BodyMetricsPage(
            uid: widget.uid,
            profileImageUrl: downloadUrl,
          ),
        ),
      );
    } on FirebaseException catch (e) {
      setState(() {
        _errorMessage = 'Upload failed: ${e.message}';
      });
    } catch (e) {
      setState(() {
        _errorMessage = 'An error occurred: $e';
      });
    } finally {
      setState(() {
        _isLoading = false;
      });
    }
  }

