                    // Only add valid, running routers
                    if (std::find(current_router.flags.begin(), current_router.flags.end(), "Running") != current_router.flags.end() &&
                        std::find(current_router.flags.begin(), current_router.flags.end(), "Valid") != current_router.flags.end()) {
                        routers.push_back(current_router);
                    }
                    in_router_block = false;
                    current_router = RouterDescriptor();
                }
                continue;
            }

            if (line[0] == 'r' && line[1] == ' ') {
                // Router descriptor line
                std::istringstream iss(line.substr(2));
                iss >> current_router.nickname
                    >> current_router.identity_key
                    >> current_router.digest
                    >> current_router.ip_address
                    >> current_router.or_port
                    >> current_router.dir_port;
                in_router_block = true;
            }
            else if (line[0] == 's' && line[1] == ' ' && in_router_block) {
                // Flags line
                std::istringstream iss(line.substr(2));
