        // Calculate player velocity
        velocity = (player.position - lastPosition) / Time.deltaTime;
        lastPosition = player.position;

        // Predict future positions
        PredictFutureChunks();

        // Pre-load predicted chunks
        PreloadPredictedChunks();
    }

