        // VistaHeightmapOptimizer.cs
        using UnityEngine;
        using Vista.TerrainGeneration;
        using System.Threading.Tasks;

        public class VistaHeightmapOptimizer : MonoBehaviour
        {
            [Header("Optimization Settings")]
            [SerializeField] private bool useGPUHeightmap = true;
            [SerializeField] private int heightmapResolution = 512;
            [SerializeField] private bool cacheHeightmapSamples = true;
            [SerializeField] private bool incrementalErosion = false;

            private ComputeShader heightmapComputeShader;
            private RenderTexture heightmapRT;
            private Dictionary<Vector2Int, HeightmapData> heightmapCache;

            void Start()
            {
                heightmapCache = new Dictionary<Vector2Int, HeightmapData>();

                if (useGPUHeightmap)
                {
                    InitializeGPUHeightmapGeneration();
                }
            }

            void InitializeGPUHeightmapGeneration()
            {
                // Load Vista 2023 compute shader for GPU heightmap generation
                heightmapComputeShader = Resources.Load<ComputeShader>("Vista/Shaders/HeightmapGeneration");

                // Create render texture for GPU heightmap
                heightmapRT = new RenderTexture(
                    heightmapResolution, 
                    heightmapResolution, 
                    0, 
                    RenderTextureFormat.RFloat
                );
                heightmapRT.enableRandomWrite = true;
                heightmapRT.Create();

                Debug.Log("GPU heightmap generation initialized");
            }

            public async Task<HeightmapData> GenerateOptimizedHeightmap(
                Vector2Int chunkCoord, 
                Vector3 worldPosition
            )
            {
                // Check cache first
                if (cacheHeightmapSamples && heightmapCache.ContainsKey(chunkCoord))
                {
                    return heightmapCache[chunkCoord];
                }

                HeightmapData heightmap;

                if (useGPUHeightmap)
                {
                    // Generate heightmap on GPU
                    heightmap = await GenerateHeightmapGPU(worldPosition);
                }
                else
                {
                    // Generate on CPU with optimization
                    heightmap = await GenerateHeightmapCPUOptimized(worldPosition);
                }

                // Cache result
                if (cacheHeightmapSamples)
                {
                    heightmapCache[chunkCoord] = heightmap;

                    // Limit cache size
                    if (heightmapCache.Count > 100)
                    {
                        RemoveOldestCacheEntries();
                    }
                }

                return heightmap;
            }

            async Task<HeightmapData> GenerateHeightmapGPU(Vector3 worldPosition)
            {
                // Set up compute shader
                int kernelIndex = heightmapComputeShader.FindKernel("CSMain");
                heightmapComputeShader.SetTexture(kernelIndex, "Result", heightmapRT);
                heightmapComputeShader.SetVector("WorldPosition", worldPosition);
                heightmapComputeShader.SetFloat("NoiseScale", 100f);

                // Dispatch compute shader
                heightmapComputeShader.Dispatch(
                    kernelIndex, 
                    heightmapResolution / 8, 
                    heightmapResolution / 8, 
                    1
                );

                // Read back from GPU asynchronously
                Texture2D heightmapTex = new Texture2D(
                    heightmapResolution, 
                    heightmapResolution, 
                    TextureFormat.RFloat, 
                    false
                );

                await Task.Run(() =>
                {
                    RenderTexture.active = heightmapRT;
                    heightmapTex.ReadPixels(
                        new Rect(0, 0, heightmapResolution, heightmapResolution), 
                        0, 
                        0
                    );
                    heightmapTex.Apply();
                    RenderTexture.active = null;
                });

                return ConvertTextureToHeightmapData(heightmapTex);
            }

            async Task<HeightmapData> GenerateHeightmapCPUOptimized(Vector3 worldPosition)
            {
                // Use Vista 2023 API with optimized settings
                VistaHeightmapSettings settings = new VistaHeightmapSettings
                {
                    width = heightmapResolution,
                    height = heightmapResolution,
                    noiseType = VistaNoiseType.Simplex,  // Faster than Perlin
                    octaves = 4,  // Reduced from default 6
                    persistence = 0.4f,
                    lacunarity = 1.8f,
                    scale = 150f
                };

                // Generate base heightmap
                HeightmapData heightmap = await Task.Run(() =>
                    VistaAPI.GetHeightmapProcessor().GenerateHeightmap(settings, worldPosition)
                );

                // Apply erosion incrementally if enabled
                if (incrementalErosion)
                {
                    await Task.Run(() =>
                    {
                        // Apply erosion in smaller batches
                        for (int i = 0; i < 10; i++)  // 10 iterations instead of 50
                        {
                            heightmap = VistaAPI.GetHeightmapProcessor().ApplyErosion(
                                heightmap, 
                                5,  // 5 iterations per batch
                                0.3f
                            );
                        }
                    });
                }

                return heightmap;
            }

            void RemoveOldestCacheEntries()
            {
                // Remove oldest 20% of cache entries
                int entriesToRemove = heightmapCache.Count / 5;
                var keysToRemove = new List<Vector2Int>();

                foreach (var entry in heightmapCache)
                {
                    if (keysToRemove.Count >= entriesToRemove) break;
                    keysToRemove.Add(entry.Key);
                }

                foreach (var key in keysToRemove)
                {
                    heightmapCache.Remove(key);
                }
            }
        }
