        public class VistaSeamBlender : MonoBehaviour
        {
            [Header("Seam Blending")]
            [SerializeField] private float blendWidth = 10f;
            [SerializeField] private bool enableHeightBlending = true;
            [SerializeField] private bool enableNormalBlending = true;

            public HeightmapData BlendChunkEdges(
                HeightmapData heightmap, 
                Vector2Int chunkCoord,
                Dictionary<Vector2Int, HeightmapData> neighborHeightmaps
            )
            {
                if (!enableHeightBlending) return heightmap;

                int resolution = heightmap.width;
                float[,] blendedHeights = heightmap.heights.Clone() as float[,];

                // Blend each edge
                BlendEdge(blendedHeights, resolution, chunkCoord, neighborHeightmaps, Edge.Right);
                BlendEdge(blendedHeights, resolution, chunkCoord, neighborHeightmaps, Edge.Left);
                BlendEdge(blendedHeights, resolution, chunkCoord, neighborHeightmaps, Edge.Top);
                BlendEdge(blendedHeights, resolution, chunkCoord, neighborHeightmaps, Edge.Bottom);

                // Create new heightmap with blended edges
                HeightmapData blendedHeightmap = new HeightmapData
                {
                    width = resolution,
                    height = resolution,
                    heights = blendedHeights
                };

                // Blend normals if enabled
                if (enableNormalBlending)
                {
                    blendedHeightmap.normals = BlendNormals(blendedHeightmap);
                }

                return blendedHeightmap;
            }

            void BlendEdge(
                float[,] heights, 
                int resolution,
                Vector2Int chunkCoord,
                Dictionary<Vector2Int, HeightmapData> neighbors,
                Edge edge
            )
            {
                Vector2Int neighborCoord = GetNeighborCoord(chunkCoord, edge);

                if (!neighbors.ContainsKey(neighborCoord)) return;

                HeightmapData neighborHeightmap = neighbors[neighborCoord];
                int blendPixels = Mathf.FloorToInt(blendWidth / (512f / resolution));

                for (int i = 0; i < resolution; i++)
                {
                    for (int b = 0; b < blendPixels; b++)
                    {
                        float t = (float)b / blendPixels;
                        float thisHeight = GetEdgeHeight(heights, resolution, i, edge, b);
                        float neighborHeight = GetNeighborEdgeHeight(neighborHeightmap, resolution, i, edge, b);

                        float blendedHeight = Mathf.Lerp(thisHeight, neighborHeight, t);
                        SetEdgeHeight(heights, resolution, i, edge, b, blendedHeight);
                    }
                }
            }

            Vector3[,] BlendNormals(HeightmapData heightmap)
            {
                // Use Vista 2023 API for high-quality normal calculation
                return VistaAPI.GetHeightmapProcessor().CalculateNormals(heightmap);
