% -------------------------------------------------------------------------
% Function: tire_model
% Purpose: Calculate tire-road friction coefficient using Magic Formula
% Inputs: slip_ratio - Wheel slip ratio [-]
% Outputs: friction_coefficient - Tire-road friction coefficient [-]
% -------------------------------------------------------------------------
function friction_coefficient = tire_model(slip_ratio, B, C, D, E)
    % Ensure slip ratio is within reasonable bounds
    slip_ratio = max(min(slip_ratio, 1.0), -1.0);

    % Magic Formula calculation
    x = B * slip_ratio;
    friction_coefficient = D * sin(C * atan(x - E * (x - atan(x))));
end

% -------------------------------------------------------------------------
% Function: slip_function
% Purpose: Calculate wheel slip ratio
% Inputs: vehicle_speed - Vehicle longitudinal speed [m/s]
%         wheel_angular_velocity - Wheel angular velocity [rad/s]
%         wheel_radius - Wheel radius [m]
% Outputs: slip_ratio - Wheel slip ratio [-]
% -------------------------------------------------------------------------
function slip_ratio = slip_function(vehicle_speed, wheel_angular_velocity, wheel_radius)
    wheel_linear_speed = wheel_angular_velocity * wheel_radius;

    % Avoid division by zero
    if abs(vehicle_speed) < 0.1 && abs(wheel_linear_speed) < 0.1
        slip_ratio = 0.0;
        return;
    end

    % Slip ratio calculation
    denominator = max([abs(vehicle_speed), abs(wheel_linear_speed), 0.1]);
    slip_ratio = (vehicle_speed - wheel_linear_speed) / denominator;

    % Clip to valid range
    slip_ratio = max(min(slip_ratio, 1.0), -1.0);
end

% -------------------------------------------------------------------------
% Function: braking_torque
% Purpose: Calculate braking torque based on ABS state
% Inputs: time - Current simulation time [s]
%         abs_active - ABS activation state [boolean]
%         current_slip - Current wheel slip ratio [-]
%         target_slip - Target slip ratio [-]
%         slip_tolerance - Slip tolerance [-]
%         max_brake_torque - Maximum braking torque [N·m]
% Outputs: brake_torque - Applied braking torque [N·m]
% -------------------------------------------------------------------------
function brake_torque = braking_torque(time, abs_active, current_slip, ...
                                       target_slip, slip_tolerance, max_brake_torque)
    if ~abs_active
        % Normal braking - ramp up to maximum
        brake_torque = min(max_brake_torque, 500 + 100 * time);
        return;
    end

    % ABS active - modulate torque based on slip
    slip_error = current_slip - target_slip;

    if abs(slip_error) < slip_tolerance
        % Maintain current torque
        brake_torque = max_brake_torque * 0.7;
    elseif slip_error > 0
        % Slip too high - reduce torque
        brake_torque = max_brake_torque * 0.3;
    else
        % Slip too low - increase torque
        brake_torque = max_brake_torque * 0.9;
    end
end

