%         duration - Ramp duration [s]
%         max_value - Maximum ramp value [-]
% Outputs: ramp_value - Ramp signal value [-]
% -------------------------------------------------------------------------
function ramp_value = ramp_function(time, start_time, duration, max_value)
    if time < start_time
        ramp_value = 0.0;
        return;
    end

    elapsed = time - start_time;
    if elapsed > duration
        ramp_value = max_value;
    else
        ramp_value = (elapsed / duration) * max_value;
    end
end

