class RecipeUploadHandler:
    """Handles recipe uploads from various formats"""

    @staticmethod
    def allowed_file(filename: str) -> bool:
        """Check if file extension is allowed"""
        return '.' in filename and \
               filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

    @staticmethod
    def extract_text_from_file(file_path: str, file_type: str) -> str:
        """Extract text from different file formats"""
        try:
            if file_type == 'txt':
                with open(file_path, 'r', encoding='utf-8') as f:
                    return f.read()

            elif file_type in ['pdf']:
                # For PDF, you'd need PyPDF2 or similar
                # This is a simplified version
                try:
                    import PyPDF2
                    with open(file_path, 'rb') as f:
                        pdf_reader = PyPDF2.PdfReader(f)
                        text = ""
                        for page in pdf_reader.pages:
                            text += page.extract_text()
                        return text
                except ImportError:
                    return "PDF processing requires PyPDF2 library"

            elif file_type in ['png', 'jpg', 'jpeg', 'gif']:
                # OCR for image files
                try:
                    image = Image.open(file_path)
                    text = pytesseract.image_to_string(image)
                    return text
                except Exception as e:
                    return f"OCR failed: {str(e)}"

            else:
                return "Unsupported file format"

        except Exception as e:
            return f"Error extracting text: {str(e)}"

    @staticmethod
    def parse_recipe_text(text: str) -> Dict:
        """Parse recipe text into structured format"""
        recipe = {
            'name': '',
            'ingredients': [],
            'instructions': '',
            'notes': ''
        }

        lines = text.split('\n')
        current_section = None

        for line in lines:
            line = line.strip()
            if not line:
                continue

            # Detect sections
            if re.search(r'^ingredients?:', line, re.IGNORECASE):
                current_section = 'ingredients'
                continue
            elif re.search(r'^(directions|instructions|method):', line, re.IGNORECASE):
                current_section = 'instructions'
                continue
            elif re.search(r'^notes?:', line, re.IGNORECASE):
                current_section = 'notes'
                continue
            elif re.search(r'^title:|^name:|^recipe:', line, re.IGNORECASE):
                recipe['name'] = re.sub(r'^[^:]+:\s*', '', line)
                continue

            # Process based on current section
            if current_section == 'ingredients':
                # Clean ingredient line
                ingredient = re.sub(r'^[\d\-•*]\s*', '', line)  # Remove bullets/numbers
                ingredient = re.sub(r'\s+', ' ', ingredient).strip()
                if ingredient:
                    recipe['ingredients'].append(ingredient)

            elif current_section == 'instructions':
                recipe['instructions'] += line + '\n'

            elif current_section == 'notes':
                recipe['notes'] += line + '\n'

            elif not recipe['name'] and len(line) < 100:  # Assume first short line is name
                recipe['name'] = line

        # If no name found, generate one
        if not recipe['name']:
            recipe['name'] = "Uploaded Recipe"

        # If no ingredients found in structured format, try to extract them
        if not recipe['ingredients']:
            recipe['ingredients'] = RecipeUploadHandler._extract_ingredients_from_text(text)

        return recipe

    @staticmethod
