            return jsonify({'error': 'No file uploaded'}), 400

        file = request.files['recipe_file']

        # Check if file is selected
        if file.filename == '':
            return jsonify({'error': 'No file selected'}), 400

        # Check file type
        if not RecipeUploadHandler.allowed_file(file.filename):
            return jsonify({'error': 'File type not allowed'}), 400

        # Secure filename and save
        filename = secure_filename(file.filename)
        unique_filename = f"{uuid.uuid4().hex}_{filename}"
        file_path = os.path.join(app.config['UPLOAD_FOLDER'], unique_filename)
        file.save(file_path)

        # Extract text from file
        file_type = filename.rsplit('.', 1)[1].lower()
        extracted_text = RecipeUploadHandler.extract_text_from_file(file_path, file_type)

        # Parse recipe
        recipe_data = RecipeUploadHandler.parse_recipe_text(extracted_text)

        # Generate spell
        generator = SpellRecipeGenerator()

        # Extract and process ingredients
        ingredients_list = generator.extract_ingredients('\n'.join(recipe_data['ingredients']))
        if not ingredients_list:
            ingredients_list = recipe_data['ingredients'][:10]

        ingredients_with_props = []
        for ingredient in ingredients_list:
            props = generator.get_ingredient_properties(ingredient)
            ingredients_with_props.append(props)

        # Generate spell
        spell = generator.generate_spell(recipe_data['name'], ingredients_with_props)

        # Clean up file
        try:
            os.remove(file_path)
        except:
            pass

        return jsonify({
            'success': True,
            'recipe_name': recipe_data['name'],
            'ingredients_found': recipe_data['ingredients'],
            'spell': spell,
            'file_processed': filename
        })

