class RecipeParser:
    """Enhanced recipe parsing with better ingredient extraction"""

    # Common ingredient patterns with weights
    INGREDIENT_PATTERNS = [
        (r'\b\d+(?:\.\d+)?\s*(?:tsp|tbsp|cup|cups|oz|ounce|ounces|lb|pound|pounds|g|gram|grams|kg|kilogram|kilograms|ml|milliliter|milliliters|l|liter|liters)\b\s+([\w\s\-]+)', 1.0),
        (r'\b\d+/\d+\s*(?:tsp|tbsp|cup|cups|oz|lb|g|kg|ml|l)\b\s+([\w\s\-]+)', 0.9),
        (r'^[\s]*[•\-\*]\s*([\w\s\-]+(?:\s*\([^)]+\))?)', 0.8),
        (r'^\s*\d+\.\s*([\w\s\-]+)', 0.7),
        (r'\b(?:fresh|dried|ground|chopped|diced|minced|sliced|grated|crushed|whole)\s+([\w\s\-]+)', 0.6),
        (r'\b\d+\s+([\w\s\-]+)', 0.5),
    ]

    # Common non-ingredient words to filter out
    NON_INGREDIENT_WORDS = {
        'ingredients', 'directions', 'instructions', 'method', 'preparation',
        'serves', 'yield', 'time', 'prep', 'cook', 'total', 'note', 'tips',
        'optional', 'required', 'equipment', 'tools', 'step'
    }

    @classmethod
    def extract_ingredients(cls, text: str) -> List[str]:
        """Extract ingredients from recipe text with confidence scoring"""
        lines = text.split('\n')
        ingredients = []
        seen = set()

        for line in lines[:50]:  # Limit processing for performance
            line = line.strip().lower()
            if not line or len(line) > 200:
                continue

            # Skip lines that are clearly not ingredients
            if any(non_ing in line for non_ing in cls.NON_INGREDIENT_WORDS):
                continue

            best_match = None
            best_score = 0

            for pattern, weight in cls.INGREDIENT_PATTERNS:
                matches = re.findall(pattern, line, re.IGNORECASE)
                if matches:
                    for match in matches:
                        if isinstance(match, tuple):
                            match = match[0]

                        # Clean the ingredient
                        ingredient = cls._clean_ingredient(match)

                        if ingredient and len(ingredient) >= 2:
                            score = weight * cls._calculate_confidence(ingredient)
                            if score > best_score:
                                best_score = score
                                best_match = ingredient

            if best_match and best_score > 0.3 and best_match not in seen:
                ingredients.append(best_match)
                seen.add(best_match)

        return ingredients[:10]  # Return top 10 ingredients

    @staticmethod
    def _clean_ingredient(ingredient: str) -> str:
        """Clean and normalize ingredient text"""
        # Remove measurements and numbers
        ingredient = re.sub(r'^\d+(?:/\d+)?\s*', '', ingredient)
        ingredient = re.sub(r'\b\d+(?:/\d+)?\s*(?:tsp|tbsp|cup|oz|lb|g|kg|ml|l)\b', '', ingredient, flags=re.IGNORECASE)

        # Remove parentheses and their contents
        ingredient = re.sub(r'\([^)]*\)', '', ingredient)

        # Remove common descriptors
        descriptors = ['chopped', 'diced', 'minced', 'sliced', 'grated', 'crushed', 
                      'fresh', 'dried', 'ground', 'whole', 'optional', 'to taste']
        for desc in descriptors:
            ingredient = re.sub(r'\b' + desc + r'\b', '', ingredient, flags=re.IGNORECASE)

        # Clean up whitespace and punctuation
        ingredient = re.sub(r'[^\w\s\-]', '', ingredient)
        ingredient = ' '.join(ingredient.split())

        return ingredient.strip().lower()

    @staticmethod
    def _calculate_confidence(ingredient: str) -> float:
        """Calculate confidence score for ingredient validity"""
        score = 0.5  # Base score

        # Length check
        if 2 <= len(ingredient) <= 30:
            score += 0.2

        # Common ingredient words
        common_words = {'salt', 'pepper', 'oil', 'water', 'sugar', 'flour', 
                       'butter', 'garlic', 'onion', 'egg', 'milk', 'cream'}
        if any(word in ingredient for word in common_words):
            score += 0.3

        # Not a single common word
        if len(ingredient.split()) > 1:
            score += 0.2

        return min(1.0, score)

