class RecipeParser:
    """Advanced recipe parser that handles various recipe formats"""

    @staticmethod
    def extract_ingredients(text: str) -> List[str]:
        """Extract ingredients from recipe text"""
        ingredients = set()
        lines = text.split('\n')

        # Common patterns for ingredients
        patterns = [
            r'\b\d+(?:\.\d+)?(?:/\d+)?\s*(?:tsp|tbsp|cup|cups|oz|ounce|ounces|lb|pound|pounds|g|gram|grams|kg|kilogram|kilograms|ml|milliliter|milliliters|l|liter|liters)?\s+([a-zA-Z\s\-]+)',
            r'^[\s]*[•\-\*]\s*([^\.]+?)(?=\.|$)',
            r'\b(?:fresh|dried|ground|chopped|diced|minced|sliced|grated|crushed|whole)\s+([\w\s\-]+)'
        ]

        for line in lines[:100]:  # Limit processing
            line = line.strip()
            if not line:
                continue

            # Skip section headers
            if any(header in line.lower() for header in ['ingredients:', 'directions:', 'instructions:', 'method:']):
                continue

            for pattern in patterns:
                matches = re.findall(pattern, line, re.IGNORECASE)
                for match in matches:
                    if isinstance(match, tuple):
                        match = match[0]
                    ingredient = RecipeParser._clean_ingredient(match)
                    if ingredient:
                        ingredients.add(ingredient.lower())

        return list(ingredients)[:15]

    @staticmethod
    def _clean_ingredient(ingredient: str) -> str:
        """Clean ingredient text"""
        # Remove descriptors and measurements
        descriptors = [
            'chopped', 'diced', 'minced', 'sliced', 'grated', 'crushed',
            'fresh', 'dried', 'ground', 'whole', 'optional', 'to taste'
        ]

        for desc in descriptors:
            ingredient = re.sub(r'\b' + desc + r'\b', '', ingredient, flags=re.IGNORECASE)

        # Remove measurements and numbers
        ingredient = re.sub(r'\b\d+(?:\.\d+)?(?:/\d+)?\s*(?:tsp|tbsp|cup|oz|lb|g|kg|ml|l)\b', '', ingredient, flags=re.IGNORECASE)
        ingredient = re.sub(r'^\d+\s*', '', ingredient)

        # Clean up
        ingredient = re.sub(r'[^\w\s\-]', '', ingredient)
        ingredient = ' '.join(ingredient.split())

        return ingredient.strip()

