public class TableEmbedder
{
    /// <summary>
    /// Embeds drawing primitives into a specified cell of McTable in nanoCAD
    /// </summary>
    /// <param name="entityGeometry">List of geometry entities to embed</param>
    /// <param name="table">The target McTable object</param>
    /// <param name="rowIndex">Zero-based row index</param>
    /// <param name="columnIndex">Zero-based column index</param>
    /// <returns>True if successful, false otherwise</returns>
    public static bool EmbedPrimitivesToTableCell(
        List<EntityGeometry> entityGeometry, 
        McTable table, 
        int rowIndex, 
        int columnIndex)
    {
        try
        {
            // Validate inputs
            if (entityGeometry == null || entityGeometry.Count == 0)
            {
                Logger.AddMessage("No geometry entities provided");
                return false;
            }

            if (table == null)
            {
                Logger.AddMessage("Table is null");
                return false;
            }

            // Validate row and column indices
            if (rowIndex < 0 || rowIndex >= table.RowsCount)
            {
                Logger.AddMessage($"Invalid row index: {rowIndex}. Table has {table.RowsCount} rows.");
                return false;
            }

            if (columnIndex < 0 || columnIndex >= table.ColumnsCount)
            {
                Logger.AddMessage($"Invalid column index: {columnIndex}. Table has {table.ColumnsCount} columns.");
                return false;
            }

            // Create a block definition to hold the geometry
            using (McBlock block = new McBlock())
            {
                block.Name = $"EmbeddedGeometry_{DateTime.Now.Ticks}";

                // Add all geometry entities to the block
                foreach (var entity in entityGeometry)
                {
                    if (entity != null)
                    {
                        // Clone the entity to avoid modifying the original
                        EntityGeometry clonedEntity = entity.Clone() as EntityGeometry;
                        if (clonedEntity != null)
                        {
                            block.Entities.Add(clonedEntity);
                        }
                    }
                }

                // Check if we added any entities
                if (block.Entities.Count == 0)
                {
                    Logger.AddMessage("No valid geometry entities to embed");
                    return false;
                }

                // Add the block to the database
                Database.CurrentDatabase.BlockTable.Add(block);

                // Create a block reference for the table cell
                using (McBlockReference blockRef = new McBlockReference())
                {
                    blockRef.BlockTableRecord = block.ObjectId;
                    blockRef.Position = new Point3d(0, 0, 0);
                    blockRef.ScaleFactors = new Scale3d(1.0, 1.0, 1.0);

                    // Set the block reference to the specified table cell
                    // Note: McTable cell content management might vary based on nanoCAD version
                    // This is a general approach - you might need to adjust based on your specific API version
                    table.SetCellContent(rowIndex, columnIndex, blockRef);
                }

                Logger.AddMessage($"Successfully embedded {block.Entities.Count} entities into table cell [{rowIndex},{columnIndex}]");
                return true;
            }
        }
        catch (Exception ex)
        {
            Logger.AddMessage($"Error embedding primitives to table cell: {ex.Message}");
            return false;
        }
    }
}

