            if (!validationResult.Success)
                return validationResult;

            try
            {
                // Detect available strategies
                var availableStrategies = DetectAvailableStrategies(table);

                // Determine which strategy to use
                var strategy = DetermineStrategy(availableStrategies, preferredStrategy);

                // Execute embedding with selected strategy
                switch (strategy)
                {
                    case EmbeddingStrategy.DirectGeometry:
                        return EmbedDirectGeometry(entities, table, rowIndex, columnIndex);

                    case EmbeddingStrategy.ImageEmbedding:
                        return EmbedAsImage(entities, table, rowIndex, columnIndex);

