            // Count valid entities
            int validEntityCount = entities.Count(e => e != null);
            if (validEntityCount == 0)
                return new EmbeddingResult(false, EmbeddingStrategy.TextReference,
                    "No valid geometry entities in the list");

            // Validate table
            if (table == null)
                return new EmbeddingResult(false, EmbeddingStrategy.TextReference,
