        {
            var availableStrategies = new List<EmbeddingStrategy>();

            // Check for direct geometry embedding methods
            if (HasMethod(table, "SetCellGeometry") || HasMethod(table, "SetCellContent"))
                availableStrategies.Add(EmbeddingStrategy.DirectGeometry);

            // Check for image embedding
            if (HasMethod(table, "InsertImage"))
                availableStrategies.Add(EmbeddingStrategy.ImageEmbedding);

            // Check for OLE object embedding
            if (HasMethod(table, "InsertOleObject"))
                availableStrategies.Add(EmbeddingStrategy.OleObject);

            // Block reference and text reference are always available as fallbacks
            availableStrategies.Add(EmbeddingStrategy.BlockReference);
            availableStrategies.Add(EmbeddingStrategy.TextReference);

            return availableStrategies;
        }

