        {
            try
            {
                // Use reflection to check if method exists
                var method = table.GetType().GetMethod(methodName);
                return method != null;
            }
            catch
            {
                return false;
            }
        }

        private static EmbeddingStrategy DetermineStrategy(
            List<EmbeddingStrategy> availableStrategies,
            EmbeddingStrategy preferredStrategy)
        {
            // If preferred strategy is available, use it
            if (availableStrategies.Contains(preferredStrategy))
                return preferredStrategy;

            // Otherwise, use the first available strategy in order of preference
            var preferenceOrder = new[]
            {
                EmbeddingStrategy.DirectGeometry,
                EmbeddingStrategy.ImageEmbedding,
                EmbeddingStrategy.OleObject,
                EmbeddingStrategy.BlockReference,
                EmbeddingStrategy.TextReference
            };

            foreach (var strategy in preferenceOrder)
            {
                if (availableStrategies.Contains(strategy))
                    return strategy;
            }

            // Fallback to text reference
            return EmbeddingStrategy.TextReference;
        }

