                    if (addedCount == 0)
                        return new EmbeddingResult(false, EmbeddingStrategy.BlockReference,
                            "No entities could be added to block");

                    // Add block to database
                    Database.CurrentDatabase.BlockTable.Add(block);

                    // Create reference in table cell
                    string referenceText = $"Block: {block.Name}";
                    table.SetCellText(rowIndex, columnIndex, referenceText);

                    var result = new EmbeddingResult(true, EmbeddingStrategy.BlockReference,
                        $"Geometry stored in block '{block.Name}' and referenced in cell");
                    result.Details.Add("EntityCount", addedCount);
                    result.Details.Add("BlockName", block.Name);
                    result.Details.Add("ReferenceText", referenceText);
