        private static Bitmap RenderGeometryToBitmap(List<EntityGeometry> entities, int width, int height)
        {
            try
            {
                var bitmap = new Bitmap(width, height);
                using (var graphics = Graphics.FromImage(bitmap))
                {
                    // Set background
                    graphics.Clear(Color.White);

                    // Calculate total bounds
                    var totalBounds = new Extents3d();
                    foreach (var entity in entities)
                    {
                        if (entity != null)
                        {
                            var bounds = entity.GetBounds();
                            totalBounds.Add(bounds);
                        }
                    }

                    if (totalBounds.IsEmpty)
                        return null;

                    // Draw each entity
                    var colors = new[] { Color.Blue, Color.Green, Color.Red, Color.Purple };
                    int colorIndex = 0;

                    foreach (var entity in entities)
                    {
                        if (entity != null)
                        {
                            var bounds = entity.GetBounds();
                            var color = colors[colorIndex % colors.Length];
                            colorIndex++;

                            // Scale to fit bitmap
                            double scaleX = width / totalBounds.Size.X;
                            double scaleY = height / totalBounds.Size.Y;
                            double scale = Math.Min(scaleX, scaleY) * 0.7;

                            int x = (int)((bounds.MinPoint.X - totalBounds.MinPoint.X) * scale) + 20;
                            int y = (int)((bounds.MinPoint.Y - totalBounds.MinPoint.Y) * scale) + 20;
                            int rectWidth = (int)(bounds.Size.X * scale);
                            int rectHeight = (int)(bounds.Size.Y * scale);

                            // Draw rectangle representing entity
                            graphics.DrawRectangle(new Pen(color, 2), x, y, rectWidth, rectHeight);
                            graphics.FillRectangle(new SolidBrush(Color.FromArgb(50, color)), 
                                x, y, rectWidth, rectHeight);
                        }
