                            compound.Entities.Add(cloned);
                        }
                    }
                    catch (Exception ex)
                    {
                        Logger.AddMessage($"Warning: Could not clone entity: {ex.Message}");
                    }
                }
            }

            return compound.Entities.Count > 0 ? compound : null;
        }

        private static Point3d GetCellCenter(McTable table, int row, int col)
        {
            // Get table position
            Point3d tablePos = table.Position;

            try
            {
                // Try to get cell rectangle using McTable API
                // This is the most accurate method
                var cellRect = table.GetCellRectangle(row, col);
                if (cellRect != null)
                {
                    double centerX = (cellRect.Left + cellRect.Right) / 2;
                    double centerY = (cellRect.Top + cellRect.Bottom) / 2;
                    return new Point3d(centerX, centerY, tablePos.Z);
                }
            }
            catch
            {
                // Fallback if GetCellRectangle is not available
            }

            // Estimate cell center based on indices
            double cellWidth = 50.0;  // Default width
            double cellHeight = 25.0; // Default height

            double centerX = tablePos.X + (col * cellWidth) + (cellWidth / 2);
            double centerY = tablePos.Y - (row * cellHeight) - (cellHeight / 2);

            return new Point3d(centerX, centerY, tablePos.Z);
        }

        private static void PositionGeometry(McCompound geometry, Point3d targetPosition)
        {
            try
            {
                // Get current position
                Point3d currentPos = geometry.GetPosition();

                // Calculate translation vector
                Vector3d translation = targetPosition - currentPos;

                // Create translation matrix
                Matrix3d translationMatrix = Matrix3d.Translation(translation);

                // Apply transformation
                geometry.TransformBy(translationMatrix);
            }
            catch (Exception ex)
            {
                Logger.AddMessage($"Warning: Could not position geometry: {ex.Message}");
            }
        }
    }
