            }
            catch
            {
                // Fallback if GetCellInfo is not available
            }

            // Estimate cell center based on row/column indices
            // Adjust these values based on your table's actual cell dimensions
            double estimatedCellWidth = 50.0;
            double estimatedCellHeight = 25.0;

            double centerX = tablePosition.X + (col * estimatedCellWidth) + (estimatedCellWidth / 2);
            double centerY = tablePosition.Y - (row * estimatedCellHeight) - (estimatedCellHeight / 2);

            return new Point3d(centerX, centerY, tablePosition.Z);
        }

        #endregion

        #region Embedding Methods

        private static bool TryEmbedUsingSetCellContent(McTable table, int row, int col, McCompound geometry)
        {
            try
            {
                // Attempt to use SetCellContent method
                table.SetCellContent(row, col, geometry);
                return true;
            }
            catch (MissingMethodException)
            {
                // Method doesn't exist in this API version
                return false;
            }
            catch (Exception ex)
            {
                Logger.AddMessage($"SetCellContent failed: {ex.Message}");
                return false;
            }
        }

        private static bool TryEmbedUsingSetCellValue(McTable table, int row, int col, McCompound geometry)
        {
            try
            {
                // Attempt to use SetCellValue method
                table.SetCellValue(row, col, geometry);
                return true;
            }
            catch (MissingMethodException)
            {
                // Method doesn't exist in this API version
                return false;
            }
            catch (Exception ex)
            {
                Logger.AddMessage($"SetCellValue failed: {ex.Message}");
                return false;
            }
        }

        private static bool CreateBlockReference(List<EntityGeometry> entities, McTable table, int row, int col)
        {
            try
            {
                // Create a block to hold the geometry
                using (McBlock block = new McBlock())
                {
                    block.Name = $"TableGeometry_{row}_{col}_{Guid.NewGuid().ToString("N").Substring(0, 8)}";

                    // Add entities to block
                    int addedCount = 0;
                    foreach (var entity in entities)
                    {
                        if (entity != null)
                        {
                            try
                            {
                                EntityGeometry clonedEntity = entity.Clone() as EntityGeometry;
                                if (clonedEntity != null)
                                {
                                    block.Entities.Add(clonedEntity);
                                    addedCount++;
                                }
                            }
                            catch (Exception ex)
                            {
                                Logger.AddMessage($"Warning: Could not add entity to block: {ex.Message}");
                            }
                        }
                    }

                    if (addedCount == 0)
                    {
                        Logger.AddMessage("No entities could be added to block");
                        return false;
                    }

                    // Add block to database
                    Database.CurrentDatabase.BlockTable.Add(block);

                    // Create block reference
                    using (McBlockReference blockRef = new McBlockReference())
                    {
                        blockRef.BlockTableRecord = block.ObjectId;
                        blockRef.Position = CalculateCellCenter(table, row, col);
                        blockRef.ScaleFactors = new Scale3d(1.0, 1.0, 1.0);

                        // Add block reference to model space
                        Database.CurrentDatabase.ModelSpace.AddEntity(blockRef);

                        // Add reference text in table cell
                        string referenceText = $"Geometry Block: {block.Name}";
                        table.SetCellText(row, col, referenceText);
                    }

                    Logger.AddMessage($"Created block '{block.Name}' with {addedCount} entities referenced in cell [{row},{col}]");
                    return true;
                }
            }
            catch (Exception ex)
            {
                Logger.AddMessage($"Error creating block reference: {ex.Message}");
                return false;
            }
        }

        #endregion

        #region Example Usage

        /// <summary>
        /// Example command method for embedding geometry into table cells
        /// </summary>
        [CommandMethod("EMBEDGEOMETRY")]
        public static void EmbedGeometryCommand()
        {
            try
            {
                // Get selected geometry entities
                var selection = Editor.Selection.GetSelection();
                if (selection.Count == 0)
                {
                    Editor.WriteMessage("\nPlease select geometry entities to embed.");
                    return;
                }

                // Convert selection to EntityGeometry list
                List<EntityGeometry> entities = new List<EntityGeometry>();
                foreach (var obj in selection)
                {
                    if (obj is EntityGeometry entity)
                    {
                        entities.Add(entity);
                    }
                }

                if (entities.Count == 0)
                {
                    Editor.WriteMessage("\nNo valid geometry entities in selection.");
                    return;
                }

                // Select target table
                Editor.WriteMessage("\nSelect a table: ");
                var tableResult = Editor.Selection.GetEntity("\nSelect a table: ");

                if (tableResult.Status != PromptStatus.OK)
                    return;

                if (!(tableResult.Object is McTable table))
                {
                    Editor.WriteMessage("\nSelected object is not a table.");
                    return;
                }

                // Get target cell coordinates
                int rowIndex = Editor.GetInteger("\nEnter row index (0-based): ").Value;
                int columnIndex = Editor.GetInteger("\nEnter column index (0-based): ").Value;

                // Execute embedding
                bool success = EmbedGeometryToTableCell(entities, table, rowIndex, columnIndex);

                if (success)
                {
                    Editor.WriteMessage("\nGeometry successfully processed and embedded into table cell.");
                }
                else
                {
                    Editor.WriteMessage("\nFailed to embed geometry into table cell.");
                }
            }
            catch (Exception ex)
            {
                Editor.WriteMessage($"\nCommand error: {ex.Message}");
            }
        }

        #endregion
    }
}
