from flask import Flask, request, jsonify
from flask_cors import CORS
import mysql.connector
from mysql.connector import Error
import os
from dotenv import load_dotenv
import hashlib

# Load environment variables
load_dotenv()

app = Flask(__name__)
CORS(app)  # Enable CORS for frontend-backend communication

def create_database_connection():
    """Create and return a database connection"""
    try:
        connection = mysql.connector.connect(
            host=os.getenv('DB_HOST', 'your-aws-rds-endpoint'),
            database=os.getenv('DB_NAME', 'student_database'),
            user=os.getenv('DB_USER', 'your_username'),
            password=os.getenv('DB_PASSWORD', 'your_password'),
            port=os.getenv('DB_PORT', 3306)
        )

        if connection.is_connected():
            print("Connected to MySQL database")
            return connection

    except Error as e:
        print(f"Error connecting to MySQL: {e}")
        return None

def create_students_table():
    """Create students table if it doesn't exist"""
    connection = create_database_connection()
    if connection:
        try:
            cursor = connection.cursor()

            create_table_query = """
            CREATE TABLE IF NOT EXISTS students (
                id INT AUTO_INCREMENT PRIMARY KEY,
                name VARCHAR(100) NOT NULL,
                email VARCHAR(100) UNIQUE NOT NULL,
                phone VARCHAR(20) NOT NULL,
                password_hash VARCHAR(255) NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            """

            cursor.execute(create_table_query)
            connection.commit()
            print("Students table created or already exists")

        except Error as e:
            print(f"Error creating table: {e}")
        finally:
            cursor.close()
            connection.close()

def hash_password(password):
    """Hash password using SHA-256"""
    return hashlib.sha256(password.encode()).hexdigest()

@app.route('/register', methods=['POST'])
def register_student():
    """Handle student registration"""
    try:
        # Get data from request
        data = request.json
        name = data.get('name')
        email = data.get('email')
        phone = data.get('phone')
        password = data.get('password')

        # Validate required fields
        if not all([name, email, phone, password]):
            return jsonify({
                'success': False,
                'message': 'All fields are required'
            }), 400

        # Hash the password
        password_hash = hash_password(password)

        # Connect to database
        connection = create_database_connection()
        if not connection:
            return jsonify({
                'success': False,
                'message': 'Database connection failed'
            }), 500

        cursor = connection.cursor()

        # Insert student data
        insert_query = """
        INSERT INTO students (name, email, phone, password_hash)
        VALUES (%s, %s, %s, %s)
        """

        cursor.execute(insert_query, (name, email, phone, password_hash))
        connection.commit()

        # Get the inserted student ID
        student_id = cursor.lastrowid

        cursor.close()
        connection.close()

        return jsonify({
            'success': True,
            'message': f'Student {name} registered successfully with ID: {student_id}',
            'student_id': student_id
        }), 201

    except mysql.connector.IntegrityError:
        return jsonify({
            'success': False,
            'message': 'Email already exists'
        }), 400

    except Error as e:
        return jsonify({
            'success': False,
            'message': f'Database error: {str(e)}'
        }), 500

    except Exception as e:
        return jsonify({
            'success': False,
            'message': f'Server error: {str(e)}'
        }), 500

@app.route('/students', methods=['GET'])
def get_students():
    """Retrieve all students (for testing/verification)"""
    try:
        connection = create_database_connection()
        if not connection:
            return jsonify({'error': 'Database connection failed'}), 500

        cursor = connection.cursor(dictionary=True)
        cursor.execute("SELECT id, name, email, phone, created_at FROM students")
        students = cursor.fetchall()

        cursor.close()
        connection.close()

        return jsonify({
            'success': True,
            'students': students,
            'count': len(students)
        })

    except Error as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health_check():
    """Health check endpoint"""
    return jsonify({'status': 'healthy', 'service': 'student-registration-api'})

if __name__ == '__main__':
    # Create table on startup
    create_students_table()

    # Run the Flask app
    app.run(debug=True, host='0.0.0.0', port=5000)
