%% Supporting Functions

function sequence = generateMarkovSequence(symbols, transition_matrix, length)
    % Generate sequence from Markov source
    num_symbols = length(symbols);
    sequence = cell(1, length);

    % Start with random initial state
    current_state = randi(num_symbols);
    sequence{1} = symbols{current_state};

    for i = 2:length
        % Get probabilities for next state
        probs = transition_matrix(current_state, :);

        % Choose next state based on probabilities
        next_state = randsample(num_symbols, 1, true, probs);

        % Update sequence and current state
        sequence{i} = symbols{next_state};
        current_state = next_state;
    end
end

function [encoded_bits, coder_state] = contextAdaptiveEncode(sequence, symbols, context_order)
    % Context-adaptive arithmetic encoding
    num_symbols = length(symbols);
    encoded_bits = [];

    % Initialize context models
    context_models = containers.Map('KeyType', 'char', 'ValueType', 'any');

    % Initialize coding interval
    low = 0;
    high = 1;

    for i = 1:length(sequence)
        % Determine context
        if i <= context_order
            context = strjoin(sequence(1:i-1), '');
        else
            context = strjoin(sequence(i-context_order:i-1), '');
        end

        % Get or create probability model for current context
        if ~isKey(context_models, context)
            % Uniform initialization
            context_models(context) = ones(1, num_symbols) / num_symbols;
        end
        probs = context_models(context);

        % Find symbol index
        symbol_idx = find(strcmp(symbols, sequence{i}));

        % Calculate cumulative probabilities
        cum_probs = cumsum([0, probs]);

        % Update interval
        range_width = high - low;
        high = low + range_width * cum_probs(symbol_idx + 1);
        low = low + range_width * cum_probs(symbol_idx);

        % Update context model (adaptive learning)
        context_models(context) = updateModel(probs, symbol_idx, num_symbols);

        % Output bits when possible
        while true
            if high < 0.5
                encoded_bits = [encoded_bits, 0];
                low = low * 2;
                high = high * 2;
            elseif low >= 0.5
                encoded_bits = [encoded_bits, 1];
                low = 2 * (low - 0.5);
                high = 2 * (high - 0.5);
            elseif low >= 0.25 && high < 0.75
                % E3 scaling
                low = 2 * (low - 0.25);
                high = 2 * (high - 0.25);
            else
                break;
            end
        end
    end

    % Final bits to uniquely identify the interval
    bits_to_add = 1;
    while true
        if low < 0.25
            encoded_bits = [encoded_bits, 0];
            encoded_bits = [encoded_bits, ones(1, bits_to_add)];
            break;
        elseif low >= 0.75
            encoded_bits = [encoded_bits, 1];
            encoded_bits = [encoded_bits, zeros(1, bits_to_add)];
            break;
        else
            bits_to_add = bits_to_add + 1;
            low = 2 * (low - 0.25);
        end
    end

    coder_state.context_models = context_models;
end

function decoded_sequence = contextAdaptiveDecode(encoded_bits, length, symbols, context_order)
    % Context-adaptive arithmetic decoding
    num_symbols = length(symbols);
    decoded_sequence = cell(1, length);

    % Initialize context models (same as encoder)
    context_models = containers.Map('KeyType', 'char', 'ValueType', 'any');

    % Convert bits to value
    value = 0;
    bit_weight = 0.5;
    for i = 1:min(53, length(encoded_bits))
        if encoded_bits(i) == 1
            value = value + bit_weight;
        end
        bit_weight = bit_weight / 2;
    end

    % Initialize coding interval
    low = 0;
    high = 1;

    for i = 1:length
        % Determine context
        if i <= context_order
            context = strjoin(decoded_sequence(1:i-1), '');
        else
            context = strjoin(decoded_sequence(i-context_order:i-1), '');
        end

        % Get or create probability model
        if ~isKey(context_models, context)
            context_models(context) = ones(1, num_symbols) / num_symbols;
        end
        probs = context_models(context);

        % Calculate cumulative probabilities
        cum_probs = cumsum([0, probs]);

        % Find symbol containing the current value
        range_width = high - low;
        current_point = (value - low) / range_width;

        symbol_idx = find(current_point >= cum_probs(1:end-1) & ...
                         current_point < cum_probs(2:end), 1);

        if isempty(symbol_idx)
            symbol_idx = num_symbols;
        end

        % Update decoded sequence
        decoded_sequence{i} = symbols{symbol_idx};

        % Update interval
        high = low + range_width * cum_probs(symbol_idx + 1);
        low = low + range_width * cum_probs(symbol_idx);

        % Update context model
        context_models(context) = updateModel(probs, symbol_idx, num_symbols);

        % Renormalize
        while true
            if high < 0.5
                low = low * 2;
                high = high * 2;
                value = value * 2;
            elseif low >= 0.5
                low = 2 * (low - 0.5);
                high = 2 * (high - 0.5);
                value = 2 * (value - 0.5);
            elseif low >= 0.25 && high < 0.75
                low = 2 * (low - 0.25);
                high = 2 * (high - 0.25);
                value = 2 * (value - 0.25);
            else
                break;
            end

            % Read next bit if available
            if ~isempty(encoded_bits)
                next_bit = encoded_bits(1);
                encoded_bits(1) = [];
                value = value + next_bit * bit_weight;
                bit_weight = bit_weight / 2;
            end
        end
    end
end

function updated_probs = updateModel(probs, observed_idx, num_symbols)
    % Update probability model using adaptive learning
    learning_rate = 0.01;

    % Increment count for observed symbol
    counts = probs * 100;  % Scale to reasonable counts
    counts(observed_idx) = counts(observed_idx) + 1;

    % Add small constant to avoid zero probabilities
    counts = counts + 0.1;

    % Normalize
    updated_probs = counts / sum(counts);
end

function received_bits = transmitThroughChannel(bits, error_probability)
    % Simulate Binary Symmetric Channel
    received_bits = bits;

    % Generate random errors
    error_mask = rand(size(bits)) < error_probability;

    % Flip bits where errors occur
    received_bits(error_mask) = 1 - received_bits(error_mask);
end

function ber = calculateBER(original_bits, received_bits)
    % Calculate Bit Error Rate
    if length(original_bits) ~= length(received_bits)
        error('Bit sequences must have same length');
    end

    errors = sum(original_bits ~= received_bits);
    ber = errors / length(original_bits);
end
```

