                                ));
                            }
                            Err(err) => {
                                error_messages.push(err);
                            }
                        }
                    }
                }
            }
        }
    }

    // If there were parsing errors in attributes, report them
    if !error_messages.is_empty() {
        // Use emit_error! to report multiple errors without aborting immediately
        for err in error_messages {
            proc_macro_error::emit_error!(err.span(), err.message());
        }
        // Return a dummy token stream since we have errors
        return TokenStream::new();
    }

    // Generate the implementation
    let expanded = quote! {
        impl #struct_name {
            pub fn validate(&self) -> Result<(), Vec<String>> {
                let mut errors = Vec::new();

                #(#validation_checks)*

                if errors.is_empty() {
                    Ok(())
                } else {
                    Err(errors)
                }
            }
        }
    };

    expanded.into()
}

