// Example 4: Incremental parsing and validation
#[proc_macro]
#[proc_macro_error]
pub fn build_query(input: TokenStream) -> TokenStream {
    let mut tokens = input.into_iter().peekable();
    let mut query_parts = Vec::new();
    let mut errors = Vec::<proc_macro_error::Diagnostic>::new();

    // Parse tokens incrementally with error recovery
    while let Some(token) = tokens.next() {
        match &token {
            proc_macro::TokenTree::Ident(ident) => {
                if ident.to_string() == "SELECT" {
                    query_parts.push("SELECT".to_string());
                    // Parse columns
                    parse_columns(&mut tokens, &mut query_parts, &mut errors);
                } else {
                    errors.push(
                        proc_macro_error::Diagnostic::spanned(
                            ident.span(),
                            proc_macro_error::Level::Error,
                            format!("Unexpected identifier: {}", ident)
                        )
                    );
                }
            }
            _ => {
                errors.push(
                    proc_macro_error::Diagnostic::spanned(
                        token.span(),
                        proc_macro_error::Level::Error,
                        "Expected SELECT keyword"
                    )
                );
            }
        }
    }

    // Emit all collected errors
    if !errors.is_empty() {
        for error in errors {
            error.emit();
        }
        return TokenStream::new();
    }

    // Generate the query
    let query = query_parts.join(" ");
    quote! {
        {
            let query = #query;
            println!("Generated query: {}", query);
            query
        }
    }.into()
}

fn parse_columns(
    tokens: &mut std::iter::Peekable<proc_macro::token_stream::IntoIter>,
    query_parts: &mut Vec<String>,
    errors: &mut Vec<proc_macro_error::Diagnostic>,
) {
    // Simplified column parsing with error recovery
    let mut columns = Vec::new();

    while let Some(token) = tokens.peek() {
        match token {
            proc_macro::TokenTree::Ident(ident) => {
                columns.push(ident.to_string());
                tokens.next(); // Consume the token
            }
            proc_macro::TokenTree::Punct(punct) if punct.as_char() == ',' => {
                tokens.next(); // Consume comma
                continue;
            }
            _ => break,
        }
    }

    if columns.is_empty() {
        errors.push(
            proc_macro_error::Diagnostic::new(
                proc_macro_error::Level::Error,
                "SELECT statement must have at least one column"
            )
        );
    } else {
        query_parts.push(columns.join(", "));
    }
}

