    Generates and saves solar system data to a JSON file.
    This file can be loaded by JavaScript for the simulation.
    """
    data = generate_solar_system_data()

    # Convert to JSON-serializable format
    def convert_to_serializable(obj):
        if isinstance(obj, (int, float, str, bool, type(None))):
            return obj
        elif isinstance(obj, dict):
            return {key: convert_to_serializable(value) for key, value in obj.items()}
        elif isinstance(obj, (list, tuple)):
            return [convert_to_serializable(item) for item in obj]
        else:
            return str(obj)

    serializable_data = convert_to_serializable(data)

    with open(filename, 'w') as f:
        json.dump(serializable_data, f, indent=2)

    print(f"Solar system data saved to {filename}")
    print(f"Total planets: {len(data['planets'])}")
