@dataclass
class CelestialBody:
    """Represents a celestial body in the solar system"""
    name: str
    type: str  # 'star', 'planet', 'dwarf_planet', 'moon'
    radius_km: float
    distance_from_sun_au: float  # astronomical units
    orbital_period_days: float
    rotation_period_hours: float
    color: str
    mass_kg: float
    orbital_inclination_deg: float = 0
    eccentricity: float = 0
    has_rings: bool = False
    moons: List['CelestialBody'] = field(default_factory=list)

def generate_solar_system_data() -> Dict[str, Any]:
    """Generate solar system data optimized for web visualization"""

    # Core celestial bodies for demonstration
