    )

    # Add moon to Earth
    moon = CelestialBody(
        name="Moon", type="moon", radius_km=1737.4, distance_from_sun_au=1.0,
        orbital_period_days=27.3, rotation_period_hours=655.7, color="#B0B0B0",
