    )

    planets = [earth, mars]

    def calculate_scaled_values(body: CelestialBody) -> Dict[str, Any]:
        """Calculate optimized scaled values for web visualization"""
        # Logarithmic scaling for better visual representation
        if body.type == "star":
            scaled_radius = 50  # Fixed size for sun
        else:
            scaled_radius = max(math.log10(body.radius_km + 1000) * 6, 8)

        # Non-linear distance scaling for better screen usage
        scaled_distance = body.distance_from_sun_au * 80

        # Orbital speed calculation with eccentricity adjustment
        orbital_speed = 360 / body.orbital_period_days if body.orbital_period_days > 0 else 0
        orbital_speed *= (1 - body.eccentricity * 0.3)  # Adjust for elliptical orbits

        return {
            "scaled_radius": scaled_radius,
            "scaled_distance": scaled_distance,
            "orbital_speed": orbital_speed,
            "rotation_speed": 360 / body.rotation_period_hours if body.rotation_period_hours != 0 else 0
        }

    # Prepare data structure with metadata
    solar_system_data = {
        "metadata": {
            "generated": datetime.utcnow().isoformat() + "Z",
