                    "Interactivity: Implement efficient hit testing"
                ]
            },

            # Library recommendations
            "recommended_libraries": {
                "for_beginners": {
                    "library": "Canvas API + Vanilla JS",
                    "reason": "No dependencies, full control, good performance",
                    "best_for": "Learning, simple simulations, educational projects"
                },
                "for_data_visualization": {
                    "library": "D3.js",
                    "reason": "Excellent for data binding, interactive charts, orbital diagrams",
                    "best_for": "Educational visualizations, data dashboards, orbital mechanics"
                },
                "for_3d_simulations": {
                    "library": "Three.js",
                    "reason": "WebGL rendering, realistic 3D, large ecosystem",
                    "best_for": "Realistic 3D simulations, complex orbital mechanics"
                }
            }
        },

        "sun": {
            "name": sun.name,
            "type": sun.type,
            "radius_km": sun.radius_km,
            "color": sun.color,
            **calculate_scaled_values(sun)
        },
        "planets": []
    }

    for planet in planets:
        planet_data = {
            "name": planet.name,
            "type": planet.type,
            "radius_km": planet.radius_km,
            "distance_from_sun_au": planet.distance_from_sun_au,
            "orbital_period_days": planet.orbital_period_days,
            "rotation_period_hours": planet.rotation_period_hours,
            "color": planet.color,
            "eccentricity": planet.eccentricity,
            "moons": [
                {
                    "name": moon.name,
                    "radius_km": moon.radius_km,
                    "color": moon.color,
                    "orbital_period_days": moon.orbital_period_days,
                    **calculate_scaled_values(moon)
                }
                for moon in planet.moons
            ],
            **calculate_scaled_values(planet)
        }
        solar_system_data["planets"].append(planet_data)

    return solar_system_data

